/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220310-3","meetingId":"r04-c-budget","date":"2022年3月10日","dateIso":"2022-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を171件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"私からは、２８７ページ、犬の登録、時間があれば、３０５ページの商店街活性化事業についてお伺いします。犬の登録について、殺処分ゼロに向けて区にどういったことができるのかということを幾つかお伺いしたいと思います。","respondent":"鈴木生活衛生課長","answer":"大きく２つ、犬の種類、それから特徴というようなところを登録をします。それと併せて、そのときに狂犬病の予防注射を済ませているかどうかというところも確認をした上で、鑑札、それから注射済票を交付しています。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"そうすると、区内の犬の情報というのは、おおむね１００％把握できているという認識でよろしいのでしょうか。かつ、そう簡単に殺処分もできないものですから、非常に困ったという事例がありました。","respondent":"鈴木生活衛生課長","answer":"区内の飼われている犬の把握ですが、基本的には法に義務づけられておりますので、全員の方に届出をいただいてというふうに認識しております。虐待と考えられたり、例で挙げられたように、都の動物愛護相談センターのほうで対応するというような役割になっているところです。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"例えばワンルームの中で、ブリーダー登録があるのかどうかとか、そういう動きを品川区がかけられているのかもお聞かせいただきたい。これから品川区としてどういった対応をとるのかということをお聞かせいただきたいのですが、アクセス権があるとすれば、先ほどの例えと同じように。","respondent":"鈴木生活衛生課長","answer":"それから、新しくこの６月に開始される予定のワンストップサービスへの登録制度に自治体として参加をすれば、登録業務を国から指定された団体から。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"地域猫についてもお伺いいたしますが、これからどんどん頭数を減らしていこうというような思いでやっていらっしゃるというふうに認識をしています。今、モデル地区を、小山のほうでやっていらっしゃると思うのですが、そこからの広がり、全区的にどういった対応をとられているのか説明を求めました。","respondent":"鈴木生活衛生課長","answer":"地域猫活動に関するモデル事業ですが、現在、区内全体で２１の地区で活動いただいております。制度が開始されて、９地区は対応完了や、延べ３０地区で展開されているという現状です。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"そこから虐待なり犯罪につながってしまうというような懸念もあるというふうに伺っていて、この地域猫に関しても、ぜひご検討ほしいと求めました。いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"この場でその対応ができるかどうかは分かりませんが、今後、検討したいというふうに考えております。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"２９３ページ、２９５ページ、順不同で伺ってまいります。子宮頸がんワクチンについてお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"ＨＰＶワクチンについてのお尋ねです。３月末までには確実にお手元に届くように、２月末ぎりぎりに出ましたが、何とか３月末までにはお手元に届けられるという状況で準備を進めております。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"「重要必ず中をご確認ください」など、ぜひこの封筒に入れて、必ずご確認いただけるような工夫をしてほしいと求めました。中にある資料がＱＲコード化されてデータで読み取っておくことができるような、そういう工夫も必要と考えますが、ご見解を伺います。","respondent":"鷹箸保健予防課長","answer":"実は年齢が１６歳以上ということで、保護者の同意が基本的に不要となる年代ということで、予診票自体が実はまだ出来上がっておりません。２３区統一で制定するものなのですけれども、また、積極的な周知に努めてまいりたいというふうに考えてあります。","id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"それから、１点だけ確認です。１回だけ打って、２回、３回目を打っていない方には、今回、接種券が発送されると伺いましたが、期間が空いてしまっても効果があるものなのか。","respondent":"鷹箸保健予防課長","answer":"一応３回でマックスという考え方の中で、今のところ、こちらでは把握してございません。ですが、とにかく３回、なるべく早く接種していただきたいというふうに考えてあります。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"お問合せも増えることと思いますが、丁寧なご対応とともに、例えば、もし自費でも打ちたいとなれば、それが打つことが可能なのでしょうか。２回分だけは助成対象になって、１回は自費というような、まだ国のほうから指針が出ていないということなのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"この４月から始まるのは定期接種、今、シルガード９を急ぎ入れるというような方向性の議論も今進められているというふうに聞いてあります。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"そういう中で、品川区はもったいないプロジェクトを、７年目になりますでしょうか、進めていただいていることは大変重要なことと思います。どれだけの効果があったのか、この事業検証について、区の見解をお伺いします。","respondent":"河内環境課長","answer":"販売などにつきまして、各工程におきまして一定のエネルギーを使うことから、ＣＯ２削減に向けて重要な取組みということで認識しています。拡充の方向で現在検討しています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区の中にも大型スーパーが何店舗かあるかと思いますので、そういうところへの働きかけもぜひ進めてほしいと求めましたが、いかがでしょうか。いよいよエコルとごしが開設するにあたって、ぜひエコルとごしでのフードドライブの常設を要望いたしますが、お伺いいたします。","respondent":"河内環境課長","answer":"収集と利用の両面から検討を加える必要があるということで、現在、検討を進めているところです。この検討の間、利用を促進いたしまして対応し、拡大に向けて進めていきたいというふうに考えているところです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"エコルとごしでの段階を踏まえての常設ということを、ぜひご検討いただくよう、よろしくお願いしたいと思います。もしこれが予算額に達してしまったときは、さらに増やしていただきたいという思いもあるのですが、事業展開をお知らせください。","respondent":"品川品川区清掃事務所長","answer":"それから、予算の充実というところですけれども、前年度に比べまして、予算上は件数を２倍にしています。状況を見まして、この辺のところも拡充していくかどうするかというところも状況を見ていきたいというふうに考えております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"これは本当にそれぞれ区民が生ごみを絞ることでのＣＯ２削減につながっていく取組みとなりますので、どうぞ前向きにご検討ほしいと求めました。以上で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問","question":"３０３ページ、３０１ページ、就業支援費についてお伺いいたします。１点目に、創業支援施設等経費と就業支援費についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"創業支援の私どもの支援が必要か必要ではないか、いろいろな悩みがあってというような方もいらっしゃるので、福祉につなげるようなケースもあります。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"メンズ・クライシスの予防を進めていただきたいというふうに要望いたしますが、改めて区のご見解をお聞かせいただけたらと思います。２点目に、中小企業活性化事業費についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"そこの部分と、それから実際に入居された後の場合でも、そういう部分を生かしまして福祉部門と連携していきたいというふうに考えております。２点目の中小企業の支援の効果ですけれども、ここ２年間、しっかり支援が行き届いているのかなというふうに考えているところです。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"特にオミクロン株の影響下におきましては、ボディブローのようにじわじわとダメージを与えられているというようなお話をお伺いしました。今後、対象月の売上げが例えば２０％以上から３０％未満減少しているなど、区のご見解を説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"来年度におきましては、借換専用資金、もともとの緊急資金の継続などもさせていただいているところです。必要があれば補正予算等を提案する形になろうかと思いますけれども、引き続き効果的な支援を続けていきたいというふうに考えております。","id":"exchange-016"},{"speaker":"横山委員","kind":"提案","question":"３点目に、予防接種費、母子健康診査費についてお伺いいたします。鈴木博委員より質問しますので、私からはＨＰＶワクチンの接種勧奨再開に関する要望のみといたしますが、との意見を述べました。","respondent":"高山健康課長","answer":"区での検討状況ですが、日本では約８０年の歴史を誇るといったものでございまして、時代に合わせまして様々変化を続けてきたところです。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"そのクリアファイルには、赤ちゃんはたくさん泣きます。赤ちゃんが泣いたときの対応など、このような啓発の手法をぜひ取り入れていただきたいというふうに思いますが、区のご見解を説明を求めました。","respondent":"高山健康課長","answer":"子どもの救急に関するご案内など、様々現在でもたくさんのものを入れているので、かなりのボリュームとなっています。そういったものも１つ有効な啓発手段と考えますので、内容を精査しつつ、新しいものも取り入れてまいりたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"続けて質問してしまいますけれども、このマニュアルは、どのような内容なのでしょうか。どのように活用されているかについて伺います。","respondent":"鷹箸保健予防課長","answer":"その後、ご本人がご希望していただければ、個別の面談等にもつながる、そういったシステムで、今、実施しています。上級編なども実施していますが、詰め込めば１００人ぐらいいけたのですけれども、かなり受講ができています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺って、１点は、希死念慮を抱いた方への対策のように思います。区が高橋さんを講師に選んだ理由についてですが、どのような中身を期待して高橋さんに講演を依頼したのでしょうか、伺います。","respondent":"鷹箸保健予防課長","answer":"運営、それから企画に関しましては、子ども若者応援ネットワーク品川のほうで全て企画されたと聞いております。この先生の経歴ですとか、子ども・若者へのＳＯＳを含めて非常に見識が広い方であるということから選ばれたのではないかというふうに考えてあります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"品川区の２０歳未満の自殺死亡率は、全国と比較して高く、上位１０％から２０％に入っていると紹介されています。伺いますが、品川区の子ども若者の自殺率が全国に比較して高い理由について、区はどのように分析されているのでしょうか、伺います。","respondent":"鷹箸保健予防課長","answer":"ＮＰＯ法人自殺対策支援センターライフリンクのほうで、確かに高いという事実があるというふうに当然認識しておりまして、ますます力を入れて対策をしていくべきだというふうに認識しています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"ですから、もちろん重点施策に入れているということで、本当にそうだと思うのです。伺いますけれども、区はどのように受け止めているのでしょうか、伺います。","respondent":"鷹箸保健予防課長","answer":"様々な原因がある中で、身近な大人や子どもが生きている身近な環境にあるということも十分認識しております。家庭内の緊張感、そういったものを少しでも和らげることができればというふうに考えて、昨年度から取り組んでいるところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"誰でもかかる可能性があるわけですから、そういう基本的な知識等を学ぶ内容にすべきだと思いますが、いかがでしょうか。そのことを対策の中では重視していただきたいのですけれども、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"自殺の対応の重要さを取り上げていただいたところですか、まず寄り添う、日々努力してまいりたいというふうに考えております。高校で新たにそういった授業を始めることになりましたので、そことも連携していきたいと考えています。","id":"exchange-023"},{"speaker":"くにば委員","kind":"提案","question":"そしてもう１点が、このオンライン面談の条件を緩和して、希望者全員がオンラインで相談できるようにしてはというご提案です。こちらの２点を伺いますとの意見を述べました。","respondent":"柏木品川保健センター所長","answer":"対象者の「その他」ですが、これは(1)から(3)以外の方で、ご相談の内容によって柔軟に対応するために、その他の(4)の設定をしています。","id":"exchange-024"},{"speaker":"くにば委員","kind":"提案","question":"様々、希望者が少ないとしても、希望者にはそういったオンラインでの面談が受けられるようになればいいのかなというご提案で終わらせていただきます。そちらに関してお考えを説明を求めました。","respondent":"柏木品川保健センター所長","answer":"実際に来ていただいてという部分が、利用者、使われる方にとっては非常にいいのかなというふうに考えているところです。ただ、今後につきましては、他区の状況、利用者の方の声も聞きながら判断していきたいと考えております。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"そこでお伺いします。そちらの現状の認識をお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"昨年１１月に実施しましたキャッシュレス決済ポイント還元事業です。今回の還元事業で加盟店自体は、事業者にとって、キャッシュレスのメリットがまだなかなか伝わっていないのかなということも感じたところです。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"本当はお伺いしようと思っていたところが、既に２回目以降のキャンペーンを実施しているところ、約３分の１の１２８に上るのです。事業者の方々ともう１回改めて話合い等をして、もういいかなという形になるのか、その辺りの見通しを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"２回目というのも念頭には置いたところではあったのですけれども、４分の３、今回は断念したようなところもあります。２３区でも多くのところがやっていただいているので、商店街支援といいますか、今後また検討するような形になろうかと思います。","id":"exchange-027"},{"speaker":"くにば委員","kind":"意見","question":"２か月であったり、３か月間、期間の延長等もお考えほしいと求めました。そして令和５年度に向けた取り組みであるとか、事業者との話合いがどういった形で進んでいるのか、最後に説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"今回のＰａｙＰａｙの事業者とのやり取りで、デジタル通貨のいい部分と、なかなかハードルの高い面がいろいろ課題が出てきておりますので、実際に使われる事業者などと、今後もまた検討していければなというふうに考えているところです。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"２月２１日に厚労省から全自治体に通知があったと伺いました。３回目接種に関しては、すぐに対応できる医療連携体制の構築をあらかじめ求める内容、体制整備にかかった費用と経費は国から出ると言っていました。","respondent":"高山健康課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"しかしながら、令和３年度におきましては、現在、１月末までの時点で１３名の方に受診いただくなど、昨年を上回る受診者数ということもあります。引き続き、歯科医師会とも協議を進めながら、よい制度としていきたいと考えております。何か副反応が出たときに、２４時間対応できるような、東京都が設置しております副反応相談センターというコールセンターがあります。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"すぐには進まないなということは思っていたのですけれども、ぜひ使いやすい制度を求めての質問ですので、そのようにお願いします。その５Ｇ基地局を否定することはできないと考えていますが、区としても考えていただきたいのですが、その辺について見解を伺います。","respondent":"河内環境課長","answer":"こういったご相談におきましては、私どもの窓口に来られた方などにつきましても、そういった対応窓口のご案内も含めて対応しています。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"昨年の決算特別委員会では、教育委員会に対して学校への掲示を求めたところ、各学校には配布されたという答弁を得ました。ぜひ区の公共的な施設での活用を促すべきと考えますが、現状を伺います。","respondent":"河内環境課長","answer":"個人の発する臭いなどにつきまして、規制的な対応をするのは非常に困難です。香りについては、そういった周知全般につきましては、今後の検討がいろいろ必要になる状況ではないかというふうに考えているところです。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう少しきちんと言ってほしいなと思うのですけれども、そのポスターが、ほかの自治体では既に消費者センターとかに掲示をされています。５省庁連名で出されているポスターを区として活用してほしい、区としての活用を求めての質問なのですが、改めて伺います。","respondent":"河内環境課長","answer":"改めまして、活用につきまして検討を進めてまいりたいと考えているところです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"提案","question":"生活者ネットとしても、今どちらにすべきという提案はないのです。ぜひ早く議論を始めていただきたいのですが、今現在、何かあったら説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"４月から受け入れられるというような状況でもないような状態と聞いておりますので、当然、考えていかなければいけません。こういったところもいろいろ検討しながら進めていきたいと、このように考えております。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"やっぱり区民への負担というものも、そういう視点もぜひ考えてほしいと求めました。そういう仕組みも明らかにしながら、拡大生産者責任は区としてもぜひ国に対して主張していただきたいのですが、改めて伺います。","respondent":"品川品川区清掃事務所長","answer":"こういうものもなるべく使っていかないようにということで、これは各企業がいろいろと努力して、今、進めているような状況です。こういった面も総合的に捉えて啓発は進めていきたいと、このように考えております。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"これについては、これまでずっと若者や女性への就業支援の相談について、継続して丁寧にやっていただきたいということを求めております。これまでも求めてきましたが、まだ３月のものが出ていないかと思いますが、分かるところまで説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"利用人数といたしまして１８７件という形になっていまして、そのうちこちらで把握している就職決定の人数は２６件で、５％ほど落ちているような形で相談の件数が推移しています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"相談の件数が落ちているということですか。落ちているということであれば、ぜひもっと拡充してほしいと求めましたが、その辺の工夫も併せて説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"周知等は特に今までどおりしっかりさせていただいているところですので、コロナとか、いろいろな状況があるのかなと考えているところです。オンラインなどもいろいろ考えて、若者、いわゆる氷河期世代なども対象にしたものをやっていきたいというふうに考えているところです。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"オンラインは、これからなのですね、ぜひ活用してほしいと求めました。どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"木村委員","kind":"質問","question":"私からは、２７９ページの上から８行目、受動喫煙防止対策費、３９３万円余からお聞きいたします。区でも、法律や条例等に基づいて受動喫煙防止対策を進めていますが、現在の状況はいかがになっているか尋ねました。","respondent":"高山健康課長","answer":"引き続き表示状況を確認しつつ、この割合が限りなく１００％に近付いていくよう、引き続き啓発に努めてまいります。粘り強く説得など、協力を働きかけまして、そうした状況の解消に努めているといった状況です。","id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"そして、この条例ができ、これを機会に、たばこをやめられて喫煙者数も少なくなったとのうわさもちらほらお聞きしました。自販機を含め、本区での販売量に影響はどのように出ているのか、説明を求めました。","respondent":"高山健康課長","answer":"それから２点目のたばこの販売状況という点ですが、９８８億本ということで、その前年と比較しまして１６.３％の減少というふうに聞いております。","id":"exchange-039"},{"speaker":"木村委員","kind":"意見","question":"そして今度は、令和３年度は４７２万円余でしたけれども、令和４年度は３９３万円余の予算が組まれました。昨年より８０万円程度、なぜ予算を減額されたのか、説明を求めました。","respondent":"高山健康課長","answer":"令和４年度の予算額が、前年との比較で減少しているという点でのお尋ねです。いわゆる卒煙に関する支援事業につきましては、法律や条例などが徹底されることで、こうしたかける経費が徐々に減らしていけるものと考えております。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問","question":"次に、予防接種費、３７億１,７００万円余からの質問をいたします。これから先の見通しは、行政としてどのように読んでいるのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今、委員お尋ねの４回目についてです。４回目についても他国の状況を見ながら、これから少し精査をしていくというお話があった以上の情報は、区のほうには現在まだ下りてきておりません。","id":"exchange-041"},{"speaker":"木村委員","kind":"意見","question":"多分、四度目もあることと思いますけれども、早く収まることを願っております。規則を守ることが大きな力になり、また特効薬になると思いますけれども、最後にそのお考えを説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"感染が一刻も早く収まることは当然期待はしております。できる限り早く希望する方が打てるように、区としても体制を万全で整えてまいりますので、どうぞご協力のほどよろしくお願いいたします。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"２８７ページの感染症対策事業についてお聞きします。そして、区民の皆様方に対して、何をすべきなのかということも、答えるよう求めました。","respondent":"鷹箸保健予防課長","answer":"住民全てが感染症に罹患し普通の生活を営めなくなり、その結果、様々な生活に支障が出ることをまずは予防するということが重要だと思います。隔離、その辺を含めてしっかり対応していくところが感染症対策の目的、また方法だというふうに考えております。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"今、安心して暮らせているのだろうか。では、その安心に対してはいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"感染症対策と安心・安全ですか。端的にお答えするのが非常に難しいのですけれども、これまでどおりの生活を送れること、それが一番重要なことかと思います。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"来年度、令和４年度の保健所の体制強化ということがありますけれども、どういう形で安心を得られるようにしていくのか。今どういうところに一番区民の皆様方は不安に思って、どうしてほしいのかということを、どういうふうに思われているのかのお考えをお聞きします。","respondent":"鷹箸保健予防課長","answer":"国あるいは都の方針が頻回に変更がありまして、大変重要な問題というふうに認識しているところで、それを本当に区の使命だと考えています。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"この第一歩をどうすればいいのですか。非常に現場のお医者さんも大変だなと私は思っていますけれども、まず最初に、どこにコンタクトをとったらいいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"今、これは１月２４日の国の通知に基づきまして、誰でも彼でもみなし陽性ということでは決してございません。１月２４日に国の通知が出まして、必要な対応、患者さんと同等に確実な対応をさせていただいているところになります。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"かかりつけ、私はかかりつけ医がいますからかかりつけへ行きますけれども、でも、電話がかからない、どうしたらいいのですかということです。そういう場合はどうしたらいいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"かかりつけ医がいない方については、近所の医師に相談するなりという本来の対応は、別にコロナ以外でもまずはやっていただきたいと思います。２４時間のもの、４月以降になりますけれども、ご自身で相談をするということも心がけていただきたいと思います。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問","question":"２７５ページ、そして２８１ページの乳児健康診査、２８５ページのがん検診普及事業について質問いたします。この健康ポイント事業の概要、そして、これまでの事業の評価について説明を求めました。","respondent":"高山健康課長","answer":"運動を始めるきっかけづくりでありますとか、継続する動機となるインセンティブを付与することで健康づくりに取り組むことを目指すものです。その２つのうちからいずれかをというような形に変更させていただいておりまして、従来ですと、参加者に一定の上限があったものが。","id":"exchange-048"},{"speaker":"松澤委員","kind":"質問","question":"スマートフォンのアプリ、要はスマホに統一することによって、どういったメリットがあるのか。そういったサポートが必要な方、そういった対応になると、どういったものがあるのか尋ねました。","respondent":"高山健康課長","answer":"８０代の方までこの事業にご参加いただいておりますので、開始にあたりましては、サポートなどもしてまいりたいと考えております。個別な対応などもしていますので、今後もそうしたお困りになっている方には、丁寧に寄り添った対応をしてまいりたいと考えております。","id":"exchange-049"},{"speaker":"松澤委員","kind":"質問・要望","question":"そういった中で、やっぱりもっと、人はいろいろ望むではないですか。もっといろいろなところをやってほしいと、例えばそういった変わった取組みというものも、ちょっと面白いのかなと考えているのです。","respondent":"高山健康課長","answer":"は観光名所などというふうに考えているところではありますが、ご提案の防災の要素なども面白いものかと思います。一本化することによって、事業についてはいろいろと広がりが出てまいりますので、ご提案のことも今後検討してまいりたいと考えております。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問・要望","question":"広報を行うとアプリのダウンロード数が伸びる、そういった現状をしっかりと継続して、さらなる充実を要望しまして、次の質問へいきます。今後、導入に向けてどのように進めていくのか尋ねました。","respondent":"柏木品川保健センター所長","answer":"次に、この進め方と課題についてです。は導入に向けての課題の整理も含めて検討しまして、品川区医師会、荏原医師会とも相談しながら導入を進めていきたいと考えております。","id":"exchange-051"},{"speaker":"こんの委員","kind":"質問・要望","question":"昨年の決算特別委員会の総括質疑において、３歳児の健康診査における視力検査の屈折検査の導入を求めて、遡ること２０１８年より求め続けてきて。ご家庭への周知などはどのようにされるのか、事業概要と実施体制をお聞きしたいと思います。","respondent":"柏木品川保健センター所長","answer":"国の補助金が出る予定になっておりますので、１０月辺りかなという、ちょっとまだここは未確定な部分はあります。健診の通知の中に、新たに屈折検査を実施するという旨は記載した上で保護者には周知したいと考えています。","id":"exchange-052"},{"speaker":"こんの委員","kind":"確認","question":"なぜこの検査が必要なのかというところは大事なところだと思いますので、その点、よろしくお願いしたいというふうに思います。もう１回確認ですが、それで全員この屈折検査を行うという理解でいいのか、もう一度そこの点を確認させてください。","respondent":"柏木品川保健センター所長","answer":"今、委員ご指摘のとおりです。視力検査、それと全員に対して屈折検査を実施いたします。","id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"参考までに、区における入院制度の利用の現状について、各入院の件数などが分かりましたら教えてほしいと求めました。各入院の際の移送費用について、負担先はどのようになっているのか、負担額なども分かりましたら、お知らせほしいと求めました。","respondent":"榎本荏原保健センター所長","answer":"医療保護入院、家族の同意によって入院に至っていくケースですけれども、この医療保護入院は年間３００件前後ぐらいでずっと推移をしております。強制的に入院になるのですけれども、もちろん診察を経て入院になる場合ですけれども、そういった状況になっております。","id":"exchange-054"},{"speaker":"こんの委員","kind":"確認","question":"それぞれの入院体制の状況を確認させていただきました。なぜそのように高額なのかと伺いますと、この高額な移送費用を工面するが大変に厳しい、困っているというご相談でありました。","respondent":"榎本荏原保健センター所長","answer":"民間救急を利用しての入院ということも承知しております。その上でご本人も了解して、ご本人と関係づくりをした上で、同行を行っていくというのが一番ベストだというふうに考えております。","id":"exchange-055"},{"speaker":"こんの委員","kind":"質問・要望","question":"訪問医あるいは看護師の方がご本人と人間関係をつくってということですが、なかなかそこに時間もかかるし、やっぱりいざとなったときの移送費用が必要ということですので、今後そうしたことも考えていただければ、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２８１ページ、順次お尋ねしてまいりますので、よろしくお願いいたします。新型コロナウイルス感染症対策についてお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"潜伏期が短く、比較的短い期間に多くの方に感染が広がるというのも特徴ですが、一方、重症化例は少なく、入院例も少ないとされております。","id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"意見","question":"現在、コロナ第６波はピークを過ぎ、陽性者は緩やかに減少に向かっておりますが、入院者数の減少は鈍いようです。その理由についてご説明をお願いいたしますとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"感染力はなくなっても、もともとの疾患の悪化ということで入院継続が必要な場合が多くて、なかなか退院できないまま長期間の入院に至っているというような症例が多いというふうに聞いてあります。","id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ワクチン追加接種と並んで第６波を収束させるためには、治療薬による治療が必須です。現在使用できるコロナ治療薬の種類と品川区における投与実績をお示しくださいとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"投与方法としては、点滴ですとか服薬、経口などがありますが、それぞれ症状や重症度に応じて使い分けることになります。区内の治療実績、投与実績につきましては、報告するシステムになっていないことからも、区として把握はしてございません。","id":"exchange-059"},{"speaker":"鈴木（博）委員","kind":"確認","question":"品川区の実績を伺いましたが、今ご紹介したような治療は一部の患者に限られている点だけ確認したいと思います。子どものコロナウイルス患者の症状の特徴、入院した事例があったのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"咳、鼻水などの症状がありますが、いわゆる風邪と区別がつかない軽症なものというふうに把握しています。入院したという報告は、オミクロン株になってから、私どもとしては受けておりません。","id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"次に、定期予防接種から子宮頸がん予防のＨＰＶワクチンについて、時間がないので１つだけお伺いします。２次予防として子宮頸がん検診をしっかり受けていただくこと、この点を区はしっかりと説明するべきだと思いますが、区のご見解をお伺いします。","respondent":"高山健康課長","answer":"２０歳以上の偶数年齢でお受けいただくということで、勧奨通知という形で、さらなる受診率向上に向けた取組みなどを実施してきております。受診率向上、それから受診につながるよう、区としても努力してまいります。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"確認","question":"ここから地域猫の質問に入るわけですけれども、そして地域猫活動への事業の予算は、特化して組まれてはいないということでいいのでしょうか。確認をさせてください。","respondent":"鈴木生活衛生課長","answer":"ご質問の地域猫に関する対策につきましては、予算書の中で、猫の不妊・去勢手術費助成という項目で出ておりますが、その他の啓発や活動団体の支援経費も全てここに含まれているものです。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"地域猫の活動への活動費支援の仕組みをつくっていくべきではないかなと。国や都にも予算の確保を求めるべきではないか、していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"今ご質問にありました経費面での支援とか、猫の不妊・去勢手術費助成というタイトルになっておりますが、実際の活動支援の中のメニューは既につくられていて活用いただいているものです。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、病院にかかる治療費、またケージの購入費、そしてえさ代、こうしたものにも使えるということでいいのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"現在、実際に経費の補助として対象にしているのは、このタイトルにある去勢手術、それから、モデル地区に関しては、その保護等に係る必要な医療の経費、それから、えさ代に限定はしていないのですが、いろいろな資機材が必要な場合の経費なども想定をしています。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ予算の支援をしてほしいと求めましたが、いかがでしょうか。その１０頭を超えてしまう地区に、その流用の仕方というのですか、そこはどうお考えか尋ねました。","respondent":"鈴木生活衛生課長","answer":"活動の中で意見を聞いたりしながらご相談をしていますので、現在では、項目として１つ設置するという予定はありません。ほかの地区の分をお渡ししてしまうと、基本的にいつも大体年明けから２月ぐらいの間で、必要に応じて調整をするという形で対応しております。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問","question":"やっぱりそこに区も関わってほしいという声が結構出されたのです。そこにはやっぱり今、区が入っていかないと駄目なのではないかと思うのですけれども、ここはどのようにお考えか尋ねました。","respondent":"鈴木生活衛生課長","answer":"委員へのご相談者の方がご存じなかったのかもしれませんが、区では、地域でのそういう問題と取組みについてのご相談があったときには、町会の会議の場をかりたり、また、当事者の方とお会いして、そういう情報を伝えたり、調整をするということに取り組んでいるところです。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"意見","question":"本当に多岐にわたる作業が、地域に地域活動としてやることというふうに課せられているというか、地域でやられているのです。そこにもうちょっと区が力をかしてほしいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問","question":"３０１ページ、それから３０３ページ、中小企業活性化事業です。参考になる点があると思うのですが、それから、それに伴う品川区としての今後のこの問題に対する方向性をお伺いします。","respondent":"鈴木生活衛生課長","answer":"先ほども説明しましたように、町会を中心とした地域全体での取組みということで、モデル地区を進めているところです。モデル地区の方や、そのほかの皆さんからの意見やご要望も聞きながら、しっかりと事業を拡充していきたいということで検討しています。","id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"公衆浴場と就労継続支援Ｂ型作業所とのマッチングの仕組みを、障害者福祉課と連携して創設していただきたいというふうに思います。その委託料の一部を区が助成をすれば、公衆浴場、銭湯経営の継続支援にもつながると考えますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"初めてのご提案でもございまして、福祉部門から、まだそうしたお話などは聞いてはおりません。健康課といたしましては、マッチングは成立すると考えておりますので、そうした福祉部との連携の中でこの件は考えていきたいと考えております。","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"提案","question":"作戦がありますと、そういうものを浴場のオーナーなどに提案していただいて、そういうものはいかがですかと言っていただかないと。そういったところで、もう一度、障害者福祉課と一緒にネットワークをつくることに関してはいかがか尋ねました。","respondent":"高山健康課長","answer":"積極的にという意味でのご提案だと思いますので、様々、銭湯も経営上の思いなどもありますでしょうから、その中で、こうしたことを話題にした上で、そうした経営者側のご理解が得られるかどうか、今後探ってまいりたいと考えております。","id":"exchange-070"},{"speaker":"高橋（し）委員","kind":"意見","question":"その状況と来年度の見通しについて、なかなか厳しいところもあると思いますけれども、日本との交流事業についてです。それからもう１つは、その後のにぎわいへの期待、その辺りをお願いいたしますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"インターンシップは、当然こちらもできないようなところですけれども、５社４３人が一応面接したという形になっております。５年後にはまた新しい建物、地域のにぎわいにどのようにつなげられるか、いろいろ検討していきたいというふうに思っております。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"意見","question":"モンゴルとの交流は、あまり目立たない話ですけれども、他の自治体にはない非常に有効な、本当に独自のすばらしい施策だと思います。コロナの中でも何とか続けていける見通しがあるので、ぜひ継続してくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"西村委員","kind":"質問","question":"２７９ページ、母子健康診査費、３０１ページ、創業支援センター等運営費、３０７ページ、商店街店舗支援事業を順不同で伺ってまいります。今、区内に産後２週間、１か月後健診を受けていらっしゃる方がどれぐらい受けておられるか把握をしておられたら、説明を求めました。","respondent":"高山健康課長","answer":"産後の初期段階における母子に対する支援を強化し、妊娠期から子育て期にわたる切れ目ない支援体制を構築するといった趣旨の事業と認識しています。","id":"exchange-073"},{"speaker":"西村委員","kind":"質問","question":"この平成２９年度に創設された産婦健康診査事業は、産後ケア事業につなげる入り口として、産後鬱対策の導入としても重要な事業だと考えます。今、区内で産後１か月以内の母親にアプローチできる事業はあるか、どのようなものがあるのか伺います。","respondent":"柏木品川保健センター所長","answer":"産後１か月以内に母親にアプローチしている事業ですけれども、産後２週間から約１か月の間に、産後全戸電話相談を実施しております。これが委員ご指摘の１か月以内に母親にアプローチできるものと考えています。","id":"exchange-074"},{"speaker":"西村委員","kind":"質問","question":"改めまして、助産師からのお電話があるということで伺いました。どのような勧告か、また、広域連携についても勧告が出されていますが、導入にあたってどのような課題があるのか伺います。","respondent":"高山健康課長","answer":"やはり都市部においては、どのようなことがクリアできれば、こうした支援の事業がより行き届くのかといった観点で勧告があったものと考えております。","id":"exchange-075"},{"speaker":"西村委員","kind":"質問・要望","question":"これは要望ですが、宿泊事業、宿泊型の利用期間の延長の要望をさせてほしいと求めました。次に、商店街店舗支援事業を伺わせてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"今年度は商店街核店舗支援事業という事業がございまして、来年度、商店街ブランド開発支援事業という形でレベルアップを図っております。委員おっしゃるとおり、一定のグループであれば助成の対象にしていこうということで、来年度から実施するものです。","id":"exchange-076"},{"speaker":"西村委員","kind":"提案","question":"提案ですが、アイデアフルな起業家の方たちの知恵で、地域課題解決型の取組みを区として支援することはできないでしょうか。ご意見を伺いますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"西大井創業支援センターのいわゆる地域課題への貢献という部分です。","id":"exchange-077"},{"speaker":"西村委員","kind":"質問","question":"他区の方に伺うと、本当にきれいなセンターを立ち上げていただいておりますので、大変期待をしております。この特色のある３つの創業支援センターを取り巻く今後の展開ですとか、この３つの連携の取組みがあれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"先ほど言った今年の２月で３つの創業支援センター、全て工事が終わりまして、実際に運営を開始したところです。全部で２４０人がコワーキングスペースに、企業が入ってありますので、いろいろな部分で相互に連携をしていこうというところで進めているところです。","id":"exchange-078"},{"speaker":"西村委員","kind":"質問","question":"２４０人もいらっしゃるということで驚きました。こちらは女性の起業に特化しているということで、女性の起業支援の効果と課題をどのように区は捉えておられるか伺います。","respondent":"遠藤商業・ものづくり課長","answer":"女性の起業支援の難しさですが、インキュベーションマネジャーが丁寧に説明をさせていただいているところがあろうかと思います。起業家として自信を持ってやっていけばいいという方々も多く見られるのかなというのが、事業者などと話をしていると出てくるところです。","id":"exchange-079"},{"speaker":"西村委員","kind":"質問・要望","question":"関連企業に同じような業態で就職をするというふうなところに方向転換をするのも、ある種、女性起業の特徴ではないかなというふうに思っております。ぜひともそのような就職支援、起業から転換していくというふうなところの支援にも今後力を入れていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"若林委員","kind":"質問・要望","question":"広報物、こういったものの工程というのは、どういう工程をたどって最終的に区民の目に触れていくのかということを教えてほしいと求めました。うがいというのは正しいうがいの仕方をしたことによって、口腔の中の状態がどのようになるのかということをお話しほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"１０日ぐらい前に入れられる場合もありますけれども、やはりいち早く変更して区民の方にお知らせできるのはホームページが早いという形になります。除去する効果はどうかというご質問に対するお答えとしてはどうかと思いますが、今、うがいの効果は以前と変わってきています。","id":"exchange-081"},{"speaker":"若林委員","kind":"質問・要望","question":"対策本部もあると思いますので、そういうところでしっかりと一日も早く、いい方法があれば着手をしていただきたいなというふうに要望をします。マルなのかバツなのか三角なのか、１回ご見解を説明を求めました。","respondent":"鷹箸保健予防課長","answer":"ああいった通知が出たという部分は承知しておりますので、うまくそこのバランスがとれるといいのかなと考えています。答弁になっておりませんが、以上です。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"伺いたいのが、しながわ健康プラン２１で、リプロダクティブ・ヘルス・アンド・ライツの視点はないと思います。いかがか尋ねました。","respondent":"高山健康課長","answer":"リプロダクティブ・ヘルス・アンド・ライツの考え方を位置づけてはとのご提案かと思います。その趣旨といいましょうか、考え方においては、既に計画の中には入っているというふうには考えております。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"伺いたいと思いますが、望まぬ妊娠の相談を、品川区では、どこでどのように受けられているでしょうか。件数とかも含めて把握をされているのか、その推移はどうなっているのか、伺いたいと思います。","respondent":"柏木品川保健センター所長","answer":"私ども保健センターでは、当然相談があれば、専門機関と連携して相談に乗っていくという体制をとってあります。専門機関を紹介した場合も、紹介しておしまいではなく、その後も保健センターのほうで、相談者に寄り添った形で引き続き対応しています。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"さらに望まない妊娠という状況で、しかし、もうどんどんおなかは大きくなっていくという追い詰められるような状況になっていくと思うのです。どうしよう、ＳＯＳを出せる相談体制が必要なのではないかと思うのですが、いかがか尋ねました。","respondent":"柏木品川保健センター所長","answer":"当然、相談があれば、そこは専門のところ等と連携をしながら対応していくということを答弁をさせていただいたつもりです。その体制ですが、窓口を全部保健センターに整備というよりは、やはり全庁的に連携をとりながら対応していくことがいいだろうと考えています。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう方を相談に応じますよという体制、そういう保健所としての姿勢を示すということが求められていると思うのですけれども、いかがでしょうか。こういう状況をなくすために、区としては、どのような対策が必要と考えるかお聞きしたいと思います。","respondent":"柏木品川保健センター所長","answer":"その次には、やっぱり身近な方が気がついてあげられるような状況があれば、本当ならばそれが一番だとは考えてあります。改めて保健センター等で相談いただける体制もありますので、そういう部分は、いろいろな場所を通じて周知をしていきたいと考えています。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が相談を受けたのが、この確認機関のところにお願いをしたら、３万円かかるよ、１万円かかると。こういう方はほかにもいらっしゃるのではないかと思いますので、仕組みとしてつくってほしいと求めましたが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"月次支援金だとか、一時支援金を申請している場合ですと、引き続きの支援をしていただけるかという形になっているところです。どうしても駄目だというところ、ビジネス・カタリストという制度を使いまして、専門家の派遣という形で対応させていただいているところです。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それを相談して初めて分かるのではなくて、区としてそういうことをやっているということで周知してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"渡部委員","kind":"質問","question":"３０５ページは販路拡大支援事業のところで商業の件で伺うのと、２９１ページは環境学習交流施設のところで少しお伺いをしていきますが。例えばこの据置き１２か月、７年返済のところを、その辺の考え方だけ説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"条件変更になりますけど、ちょっと企業の信用格付が下がってしまうようなところもあって、なかなか踏み切れないところもあります。かつ、１年間の支払猶予といいますか、企業には引き続きご辛抱いただければなというところで考えているところです。","id":"exchange-089"},{"speaker":"渡部委員","kind":"質問・要望","question":"その在り方も、これからどうなのですか、状況を教えていただきたい。何か変更があったり、また企業側からの要望があったり、その辺の流れとかがあれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"実質的に展示会ができないという状況がありまして、非常に少ない数字だったところです。ビッグサイトでやる予定になってありますが、引き続きこちらのほうを続けて、積極的にやっていきたいというふうに考えているところです。","id":"exchange-090"},{"speaker":"渡部委員","kind":"質問・要望","question":"いわゆるＣＯ２だとか、いわゆるそういうものも環境教育の中に入っていて、そういうものに力を入れてほしいなと思います。６年前だったか８年前だったか忘れたのですけれども、どんどん盛り上げていってほしいと思うのですが、どうか尋ねました。","respondent":"河内環境課長","answer":"エコルとごしは５月に開設予定ですが、区内に生息する鳥類や植物、昆虫類を含めました常設展示なども取り入れているところです。所管部署ともいろいろやり取りしながら、どのような形で、どういう体制でやっていくかというようなところを検討すべき事象に捉えているところです。","id":"exchange-091"},{"speaker":"渡部委員","kind":"質問・要望","question":"紙１枚もらうと、その場は確認をするのですけれども、それは大体ごみになってしまうのです。できれば筆記ができたりみたいなもの、環境学習交流施設というところであれば、そういうもののご用意もしてほしいなという要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、２９７ページ、収集運搬作業全般についてお伺いします。この分担金の増額につきまして、その理由をお伺いしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"一部事務組合で清掃事務所を持っているのですが、やはり随分前につくった清掃事務所は大分老朽化をしているというところがあります。〔「工場」と呼ぶ者あり〕 清掃工場ですけれども、大分老朽化をしているというところがあります。そういうものも高騰している部分、こういったところが背景になって、毎年分担金が今のところ上がっているという状況です。","id":"exchange-093"},{"speaker":"湯澤委員","kind":"質問","question":"清掃一部事務組合管理者の山崎江東区長からも、対策を考えるというふうに伺っております。その対策とは何とか、お尋ねしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"それから清掃工場のほうもそうですけれども、こういった部分のところを総合的に見て、手数料改定を進めていく予定です。少し歳入がまた増えれば、分担金の金額も下がってくるというところは考えられるところではないかと、このように思います。","id":"exchange-094"},{"speaker":"湯澤委員","kind":"意見","question":"根本にあるのは、先ほどもご答弁にありましたように、工場の老朽化かと思います。現在のごみの量であれば、工場を減らすという議論も出てくるのかなというふうに考えますけれども、それに対する本区のお考えをお知らせくださいとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"これは一部事務組合のほうでの基本的な清掃工場の計画というものがあります。これに則って進めているという面がありますので、やはりいろいろ意見をしていこうと、このように考えております。","id":"exchange-095"},{"speaker":"湯澤委員","kind":"質問・要望","question":"２３区の考え方がそれぞれありますし、対応も１つにはならないと思いますが、議論していただくことを要望させてほしいと求めました。そして出店の見込みが２,４００店というふうになっておりましたが、利益はどのぐらいを想定しているのか、そちらをお知らせください。","respondent":"品川品川区清掃事務所長","answer":"そこの自治体では大体１０ぐらいなのですけれども、人口規模を考えると、品川では大体２０ぐらいではないかなという試算でお出しをしています。そういった中で、どのようにやっていくかというところも、今後、業者選定をしまして進めていきたいと、このように考えております。","id":"exchange-096"},{"speaker":"湯澤委員","kind":"質問","question":"こちらのリユースの事業に関しましては、持込みというふうにお聞きしていますけれども、取りに来ていただく、そういったものに関しても、リユースの需要があるのではないかと思うのですけれども、そちらも今後は検討されるのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"粗大ごみとして出された中でリユースできないかというところで進めていきたいと思います。とにかく今は回収した粗大ごみのリユースを進めていく中で、もう少し視野が広げられるかどうかというところも今後考えていきたいと考えています。","id":"exchange-097"},{"speaker":"湯澤委員","kind":"確認","question":"マンション組合の方が、ごみの中を確認することで、こういった火災事故を最小限に抑えられているのではないかなというふうに思います。本当になるべく少なくあってほしいと思うのですけれども、分かれば２３区ではどうなのかということと、お考えをお知らせください。","respondent":"品川品川区清掃事務所長","answer":"そういった対策も１つあるのではないかなというようなことは、清掃事務所の中でもいろいろと議論はしています。今後こういった周知を徹底していって、なるべく火災のないようにやっていきたいと、このように思っております。","id":"exchange-098"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ぜひ区民のごみ出しへの意識向上に取り組んでいただきたいと思うのですけれども、最後、ご答弁ほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"品川区は廃棄物減量等推進員という者が区内に５００人近くおります。随時こういった啓発活動を進めて、こういった火災等、事件がないように周知もしていきたいというふうに考えております。","id":"exchange-099"},{"speaker":"松本委員","kind":"質問","question":"私からは、３０１ページ、品川ビジネスクラブ助成金、それと武蔵小山創業支援センターについて伺います。品川区がこの品川ビジネスクラブに助成をする理由、意義について、お伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"やはり１点、連携協定を平成２５年に結びまして、あと運営の部分と事業の一部という形で助成金を渡して一緒にやらせていただいているです。","id":"exchange-100"},{"speaker":"松本委員","kind":"意見","question":"別に会員とかを区内に限っているわけではないということかと思うので、では、区内のものづくり産業等の振興発展にどう実際に寄与しているのかというところをお願いいたしますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"その中で、区内の事業所に対して何ができるかということで、いろいろ考えていただいて事業などを行っていただいている。私どもも当然一緒に相談しながらという形になりますけれども、そこの部分が一番大きいのかなと考えているところです。","id":"exchange-101"},{"speaker":"松本委員","kind":"質問","question":"本来的には、ＳＨＩＰとは別に考えて、どういうふうに区のビジネスの創出に寄与しているのかということを考えていくべきかなと思います。こういったところで考えていくと、品川ビジネスクラブ発で、区内で新しい新規のビジネスがスタートしたというふうな事例は実際にはあるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"品川区内だけでビジネスというのはなかなか難しいところがありまして、法人として品川区に登記をされるということはあろうかと考えています。","id":"exchange-102"},{"speaker":"松本委員","kind":"質問・要望","question":"その中で、あともう１つ、副賞で実証実験をＳＨＩＰでやってもいいですよというふうなものもあるかと思います。ぜひ区内の産業の発展に寄与していただきたいというふうに思っているので、毎年どういった実証実験が行われているのか、お尋ねします。","respondent":"遠藤商業・ものづくり課長","answer":"実際に受賞した方に対する支援はいろいろありますので、その中の１つというふうに考えているところです。飲食店などでお声がかかったというような、そのような話があるという部分で、いろいろな形でやらせていただいているです。","id":"exchange-103"},{"speaker":"松本委員","kind":"質問","question":"平成２７年からもう既に落ち込みが始まっていて、平成２７年度と令和２年度を比較すると、会員の会費がもう半減以上しています。区の持ち出しというか、この辺りの会員の増強、ここについて区として何かしら対策はとられているのか伺います。","respondent":"遠藤商業・ものづくり課長","answer":"会員数としては、実は平成２６年の段階で１０６人だったのですが、現在１９４人と会員自体は増えているような形になっています。品川ビジネスクラブとしての課題になっているというところがございまして、そこら辺については、私どもも常に申しています。","id":"exchange-104"},{"speaker":"松本委員","kind":"質問","question":"これは私、令和２年度の品川ビジネスクラブの決算書を見ると、１,０００万円以上の受託料が区から払われているというふうに出てくるのです。これは何のお金なのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そちらにつきましては、区のほうで委託をした事業がございまして、ですので、指定管理料や補助金とも別という形で受託していただいたというものです。","id":"exchange-105"},{"speaker":"松本委員","kind":"質問・要望","question":"この補助金が出て結構もう長くなると思いますので、一度こういった事業の見直しということも要望して、私からの質問は終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"おくの委員","kind":"質問","question":"そこで、サーマルリサイクルについて伺いますけれども、これは焼却するということですから、多くのＣＯ２を出す処理方法です。温暖化対策としては、もちろん可能な限り避けるものだと思いますが、この点はいかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"平成２０年度当時、そういったところを考えれば、そういった利点をもとにして現在のところ進めている点ではあります。ただ、現状のところとしては、サーマルリサイクルで進めている状況をやっていくということが最適ではないかというふうに考えております。","id":"exchange-107"},{"speaker":"おくの委員","kind":"質問","question":"それからもう１点、このサーマルリサイクルについて伺います。世界でも使われていない「リサイクル」という言葉でわざわざ呼んでいるのでしょうか、この点もお伺いいたします。","respondent":"品川品川区清掃事務所長","answer":"そういったごみとか、不燃ごみとかそういったものを何かに変えていくというところでの考え方かというふうに思っております。そして、燃やすことによって何かを生むことができるという意味から、「リサイクル」というような言葉を使っているかというふうに考えております。","id":"exchange-108"},{"speaker":"おくの委員","kind":"質問","question":"焼却ではなく、本来のリサイクル、文字どおりリサイクルをやるべきなのではないかという考え方もあるのだと思うのです。この点は、品川区としては、どのように考えていらっしゃるのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"２０２１年６月にプラスチック関係の法律が変わりまして、今年の４月から施行という形になります。それから再生の仕方等を、どうするかというところも現在検討しながら、製品プラスチックの回収に向けて考えていっているところです。","id":"exchange-109"},{"speaker":"おくの委員","kind":"質問","question":"廃棄された後になっても、その製品の適正なリサイクルや処分について、物理的または財政的に生産者自身が一定の責任を負うべきだと。そういう考え方について、品川区自身はどういうふうにお考えか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"今回の法律、プラスチック全体にかかる法律になります。そういった流れで進めてきているところですので、区がやるべきところはやっていきたいと、このように考えております。","id":"exchange-110"},{"speaker":"おくの委員","kind":"質問・要望","question":"区のほうからも国に対しても、こういう考え方を主張していってほしいと求めました。最後に、これを申し上げまして質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問に入ります前に、ものづくり創造センターについて伺いましたけれども、委員会のほうに報告はされたのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"ものづくり創造センターの歳入がなくなったというところでございまして、使用料収入が入らないということで、こちらのほうから落としているだけでございまして、物自体はまだあるという状況です。","id":"exchange-112"},{"speaker":"大沢委員","kind":"確認","question":"確認だけさせていただきましたので。２０１４年１月に施行された産業競争力強化法においては、地域における創業を促進するため、品川区の認定状況についてお尋ねします。","respondent":"遠藤商業・ものづくり課長","answer":"当区は認定されているというふうに認識しております。","id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"では、創業支援事業計画を策定しているということですけれども、現状、品川区の開業率はどれぐらいになっているのか。そして、目標値をどのくらい定めていらっしゃるのか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"すみません、資料として、今、手元にないのですけれども、まだ開業率というところでは、特に目標値は定めていなかったような認識をしています。","id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"目標値を定めていない、なぜ定めていないのでしょうか。国もそれに対しての支援策を出しているわけなのですけれども、目標値を出すご予定はあるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"来年度、様々な形で調査費用などもいただいているところですので、委員ご指摘の部分も踏まえて検討していきたいと考えております。","id":"exchange-115"},{"speaker":"大沢委員","kind":"質問","question":"大きなものを、区内５か所ある創業支援センターを、そこら辺の創業に対する意識の違いがある方たちにどのように紹介されているのか。取組みを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"武蔵小山創業支援センターの場合は女性というところがありますけれども、例えば、ＳＨＩＰをご案内するような形をとっております。西大井創業支援センターはまだ動いたところですが、西大井創業支援センターがそのもっと手前といいますか。","id":"exchange-116"},{"speaker":"大沢委員","kind":"質問","question":"この会社の寿命、起業に対する寿命というか、それについて課長、あるいは区の職員の方たちは、どのように考えていらっしゃるのか。そして、廃業にならないために、どのようなフォローアップ、取組みを行っているのか、それをまず説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"事業承継支援事業というものをやっておりまして、基本的に廃業につながる可能性はあるかと思うのですけれども、そうではなくて。いろいろな形で企業の支援と、廃業の支援というのもちょっと変なところですけれども、今後困らないという形を第一に考えて進めているところです。","id":"exchange-117"},{"speaker":"大沢委員","kind":"質問","question":"廃業の支援ということでありますけれども、起業に関する様々なデータがある。２３年から３０年が会社の寿命だとなるものが書いてありますけれども、これは男女問わず、平均でどれくらいになっているのか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"実際に立ち上げてから廃業までの平均年数は把握していないところです。先ほど２３年から３０年というお言葉がありましたけれども、少しずつ早まっているというような話は全般的に聞いているところです。","id":"exchange-118"},{"speaker":"大沢委員","kind":"質問・要望","question":"何となくで、創業するということは、みんな人生をかけているわけです。やはり人生をかけるわけですから、この事業をやっていただきたいと思うのですけれども、ご意見をください。","respondent":"遠藤商業・ものづくり課長","answer":"「何となく」という表現、大変失礼いたしました。マスコミ等の報道あるいは雑誌などを読んでいる中で、傾向としてということで認識しています。","id":"exchange-119"},{"speaker":"大沢委員","kind":"質問","question":"設備資金はさほどのものではないのですけれども、運転資金がなかなか出づらいような状況があるということを聞いているのですけれども、そこらのところの実態は把握されていますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"運転資金、通常ですと、３か月をめどにという形で借りていただくお話が多いのかなというふうに認識しています。売上に対しての３か月分ですので、私どもでは、そういう部分で特に顕著にというふうなことは確認できていないところです。","id":"exchange-120"},{"speaker":"大沢委員","kind":"質問・要望","question":"チェーン店ではなくて個々の飲食店の皆さんは、品川区の食を支えているというお話を伺ったことがありました。様々、しっかりとした事業計画が成り立つような資金計画もフォローアップしていただきたいと思うのですけれども、いかがお考えになりますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"私ども経営にかかわる窓口は、現行でも拡大して実施しています。困っている事業者の方がいらっしゃれば、その部分も含めて、細部にわたり、こちらのほうでご支援させていただければと考えているところです。","id":"exchange-121"},{"speaker":"つる委員","kind":"提案","question":"バナナペーパーを採用したらどうですかということをあわせて提案させていただいていて、バナナ繊維２０％配合の名刺というふうに認識をしております。","respondent":"河内環境課長","answer":"環境省のサステナブルファッションというところに出ておりますが、再生原料など、素材を選択することが非常に重要だというふうな認識です。","id":"exchange-122"},{"speaker":"つる委員","kind":"提案","question":"先日の一般質問で、そういうグッズを作ったらどうですかという質問をしたわけでありますけれども、これはこれで非常にいいことだなと思います。それから一般質問での提案の拡大についても、ぜひあわせてご見解をいただきたいとの意見を述べました。","respondent":"河内環境課長","answer":"１つは、木材の継続的な持続的な使用につながってくるというところで、もう新陳代謝が悪くなりましてＣＯ２の吸収量も鈍ってまいります。","id":"exchange-123"},{"speaker":"つる委員","kind":"確認","question":"私も東京都の担当のところに確認してみたところ、これは２０１５年度当時もそうなのですが、私も正にそういうご相談を受けております。都にも既に確認しているので答えは難しいと思うのですけれども、あえて伺いますが、ご答弁ほしいと求めました。","respondent":"河内環境課長","answer":"一方で、そういった資金の融通については、なかなか難しいところはあるのですが、２点ほど、私どもの区で取り組んでいることがあります。都とも連携いたしまして、１件１件丁寧に対応しながら、そういった案件が１つでもなくなるようにということで進めているところです。","id":"exchange-124"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に、もったいないレシピの動画配信について、これは一般質問で求めさせていただきました。そういうものをぜひ参考にしていただきたいというふうに申し上げましたが、区として、最後にご答弁ほしいと求めました。","respondent":"河内環境課長","answer":"なぜかといいますと、エコルとごしのＳＮＳ、ホームページなどを活用いたしまして、動画などを、積極的に周知を行いたいと考えています。１本当たりの時間、実施するイベントなどでは実際に召し上がっていただけますように工夫を重ねていきたいというふうに考えているところです。","id":"exchange-125"},{"speaker":"小芝委員","kind":"質問","question":"私からは、２９１ページの環境学習交流施設管理運営費と、商店街地域力向上事業について質問します。ほかでも広報活動をされてきたと思いますが、これまでの広報活動の取組みを教えていただけますか尋ねました。","respondent":"河内環境課長","answer":"そこの方にいろいろなチラシ、あるいは中身についてご説明申し上げながら、こういったものを進める予定です。３月中には、若年層から高齢者の方に広くご活用いただいておりますＬＩＮＥですが、これを活用いたしまして、ご周知、ご案内をする予定です。","id":"exchange-126"},{"speaker":"小芝委員","kind":"質問","question":"エコルとごしに入場する初年度の目標数値といいますか、年間で大体どのくらいの人数を予測されておりますでしょうか。今後、５年後、１０年後に向けて、その数、どのように推移していくことを目標にしているのか教えてほしいと求めました。","respondent":"河内環境課長","answer":"年間３万人を見込むのが妥当かなというところで、今、開設を進めているところです。ＵＤトークや、様々な工夫をしながら、努力を重ねながら利用者の数を増やすよう努めていきたいというふうに考えているところです。","id":"exchange-127"},{"speaker":"小芝委員","kind":"質問","question":"ご丁寧な説明ありがとうあります。年間３万人としているそうですが、そういったイベントだとか講座、その辺りのイレギュラーな部分での考え方を教えてもらいたいのですが。","respondent":"河内環境課長","answer":"公園の利用者の方の憩いの場、交流の場といたしましても利用を促進していきたいと考えております。多様な関わり方があるかと思いますが、学習だけということではなく、地域の方に愛されますように、こういったことを進めていきたいという考えです。","id":"exchange-128"},{"speaker":"小芝委員","kind":"質問","question":"そういう中で、これまでどおりの宣伝では、なかなかアプローチしにくい世代があります。宣伝が行き届くよう、ＳＮＳを総動員した広報活動の促進をお願いしたいと思いますけれども、そこを改めてお答え願えますか尋ねました。","respondent":"河内環境課長","answer":"広報、情報発信担当というようなポストも設けまして、こういったことを計画的に進めてまいりたいと考えています。ツイッター、インスタグラムなども、網羅しながら情報の発信につきまして積極的に取り組んでいきたいというふうに考えているところです。","id":"exchange-129"},{"speaker":"小芝委員","kind":"質問・要望","question":"オープン直前に、１時間とかで２時間とか、そういった短い時間帯での枠で拡散させていくということも１つの手ではないかなと思います。その辺り、どのようにお考えか尋ねました。","respondent":"河内環境課長","answer":"既存のフォロワーを多く持たれているところとの連携というところも大事かと思っています。そういったところの連携や、様々な連携の中で、情報発信を隅々までというような思いの中で進めてまいりたいというふうに考えているところです。","id":"exchange-130"},{"speaker":"小芝委員","kind":"提案","question":"さらに広めていく上で、区内に本社を置きます企業との連携が、またさらに施策の相乗効果を生み出すものと考えております。私もこれまで、昨年の決算特別委員会などで提案をさせていただきましたけれども、連携についての取組みについて教えてほしいと求めました。","respondent":"河内環境課長","answer":"ライメックス技術を応用いたしました三菱鉛筆というような辺りと連携を視野に進めてまいりたいというように考えているところです。国内企業との連携によりまして、双方高め合いながら、エコルとごしの機能も生かして進めてまいりたいというように考えているところです。","id":"exchange-131"},{"speaker":"小芝委員","kind":"質問・要望","question":"続きまして、商店街地域力向上事業についてお伺いいたします。今年の当初予算では１７件を見込んでいるそうですが、まず、この予算での１７件という見込みを出しましたその理由を教えていただけますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"今年度の実績見込みなどを勘案いたしまして、若干、２件ほど計上したと。感染症対策事業につきましても、引き続きやっていく部分があるというところで、プラスで計上せさせていただいたです。","id":"exchange-132"},{"speaker":"小芝委員","kind":"提案","question":"所轄の警察の方も一緒になって、月に１回、地域を２時間ほど時間をかけて回っているところもあります。ときには警察などと連携して取り組んでもらうような事業展開を提案させてほしいと求めましたが、その辺りのお考えを教えていただけますでしょうとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは、商店街の今後の生き残りというところでも、住民との連携は非常に大事かと思っているところです。様々な方法があろうかと思いますので、今後も研究していきたいというふうに考えています。","id":"exchange-133"},{"speaker":"小芝委員","kind":"質問・要望","question":"先ほど、エリアサポーターの活用ということもありましたけれども、先ほども話しましたとおり、商店の方々、町会とのつながりも当然あるわけです。三位一体となって地域を回っていただく、それが、ぜひ前に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"大倉委員","kind":"質問・要望","question":"その中で、この事業が進んでリユースが品川区内で進めばいいなという思いで伺わせてほしいと求めました。リユースとして、年間２,４００点程度の粗大ごみをということで、ごみの削減効果としては、どのぐらいを試算されているのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"１つは、今考えているところは、これは事前に粗大ごみの登録をしていただいて持っていくという仕組みであります。いろいろなパターンが考えられるかなとは思いますが、現在のところは、区に歳入という形で入れてやるというところを想定をしています。","id":"exchange-135"},{"speaker":"大倉委員","kind":"確認","question":"この辺も決まっているのかどうかも含めて、分かれば教えてください。ここは希望する区民に提供するということで、「区民」と書いてあるのですが、区在住の方ということでいいのか確認をさせてほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"やはり効率性等も考えれば、そういった仕組みをつくっていきたいとは考えているのですけれども、検討していきたいというふうに思っております。","id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"制限について伺えればと思うのですけれども、１人なのか、世帯なのかということが決まっていれば教えてください。これをしないと、それを転売目的に利用する方なども出てきてしまうのかなというところがあったので、その点について伺わせてください。","respondent":"品川品川区清掃事務所長","answer":"その後、こういったやり方についても制限をかけるかどうかというところは、やっぱり考えていかなければいけないところだというふうに思っております。","id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"本人確認とかも必要になってくるのかなと思うので、今後の検討で様々していっていただけるということなので、そういうことも意見として述べします。その辺、様々な課と連携をして進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"私は、３０３ページ、中小企業活性化事業費についてお聞きしたいと思います。区内の中小事業所の経営状況の実態を、今、どのように把握されていますか、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"昨今の原油高だとか、あるいは物が入ってこないというところでの苦しさがあるというところが大変な状況なのかなというふうに感じているところです。一定、区内も含めましてですけれども、効果が出ているのかと感じているところです。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"そして、品川区内に経営困難企業はどれぐらいあるというふうにお思いでしょうか。これも把握されているでしょうか、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"なかなか返せないだろうというところでの区の支援策ですけれども、来年度、１回の返済金額を減らすというような形のスキームになっているところです。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"今の借換融資についてもちょっとお聞きしたいのですが、既に融資されている額に関係なく、必ず借換融資を受けられるのでしょうか。そして、品川区の借換融資で一体何社まで助けられる、そういう予算措置というのはしてあるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"基本的に返さなくてはいけない部分がありますので、そのときの売上だとか、今後の事業の展開だとかという部分はあろうかと思います。それほどの金額が乗るといいますか、計上しているものではございませんので、現在の融資の予算の中で十分対応できるかなと考えているところです。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"今、お話をお聞きしたとおり、結局、金融機関によっては、この経営内容では駄目ですよということがほとんどではないですか。何社かは大丈夫ですけれども、あとは金融機関でどういう返事をするか分からないから、私どもでは責任は持てません」ということなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"産業ですので、福祉とは違う観点が正直あろうと考えているところです。今後、もう事業が成り立たないという部分まで税金を使って支援するのかというのは、考え方としてあろうかと思っているところです。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"毎月の額を例えば３０万円ずつ返済するならば、それを２０万以下にしてもらうとか、そういうことは区でお願いできるのではないでしょうか。このままいったらみんな大変ですからと、そういう対応はしているのですか、するつもりはありませんか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは３年間無利子で、その段階で１回、３年間無利子という形にできます。１年間据置きという形になり、返済期限が１０年という形になりますので、返済期間も延びるというふうな形になっているところです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"しっかりお聞きして、アンケートでも何でもいいですから、声を聞いてほしいと求めました。それが、こういう場所に置かれたら、その気持ちがなえてしまうのではないか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"まずは、そういうところを見ながら、今後の拡大等も検討できるところかどうかも考えてやっていきたいというふうに思っております。こういったところも利用していただくというところも１つあるかということで、いろいろな方法を出して、このように考えております。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで多くの子どもたちにも、多くの大人の皆さんにも、この気持ちを、リユースする気持ちを植えつけています。私は、物の大切さという教育も兼ねて、もっと近場で皆さんが利用しやすい、そういう立地も考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした下で、２０５０年、ＣＯ２ゼロに向けて、地方自治体の役割発揮が求められています。できることをやるという姿勢でなく、２０５０年、ＣＯ２ゼロに向けて、どのような取組みが必要かという姿勢が必要だと思いますが、いかがか尋ねました。","respondent":"河内環境課長","answer":"その中で、区としてできることとできないこと、いわゆる区民の方、企業の方との連携の中で進めるべきものも大変多いというようなところです。は手のつけられるところから取り組むとともに、意識の向上なども含め進めてまいりたいというふうに考えているところです。","id":"exchange-146"},{"speaker":"のだて委員","kind":"質問・要望","question":"まず半減にしていくというところでやっていっていただきたいと思うのですけれども、これまで行ってきた取組みの分析はどうなっているでしょうか。うまくいっているという分析かどうか伺いたいと思います。","respondent":"河内環境課長","answer":"丹念に対応しながら、先ずは隗から始めろでございまして、やっていきたいというふうに考えております。そういったものを生かしながら進めてまいりたいというふうに考えているところです。","id":"exchange-147"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＣＯ２排出削減には大きく寄与してくるところで、結局、自治体の取組みが相殺されてしまうということにもなってしまう。ＣＯ２ゼロに向けて、こうした姿勢を改めることを自治体としても求めるべきだと思いますが、いかがか尋ねました。","respondent":"河内環境課長","answer":"関東圏に電力を供給するＪＥＲＡですが、石炭火力の低減によりまして排出係数を低減するという計画になっているように認識しております。社会情勢に伴いまして排出係数が変わってまいりますが、適宜、その影響を低減することができるというふうに認識しております。","id":"exchange-148"},{"speaker":"のだて委員","kind":"質問","question":"脱炭素電力にしていくことで削減していくということですので、そういう意味では、やはりこの石炭火力を廃止していく、そうしたことが、区の取組みをさらに進めていくためにも重要だと思うのですけれども、改めて伺います。","respondent":"河内環境課長","answer":"インベストメントではなくダイベストメントといいまして、投資を控えるようなことで、主に海外の商社の石炭火力からの脱退も相次いでいるところです。そうした風潮を受けまして、区としても進行方向についてしっかりと考えてまいりたいというふうに考えているところです。","id":"exchange-149"},{"speaker":"のだて委員","kind":"質問・要望","question":"自治体としても国に要望もしてほしいと求めましたし、やはり区内のＣＯ２排出量、それぞれの排出割合を伺いたいと思います。２０５０年、ＣＯ２ゼロに向けて重要だと思いますが、いかがか尋ねました。","respondent":"河内環境課長","answer":"家庭におきましても、そういったものを進めることによりまして、こういった提言に向かって進めてまいりたいというふうに考えているところです。割合はまだこれから検討してまいります。","id":"exchange-150"},{"speaker":"のだて委員","kind":"質問","question":"区の排出量の割合を聞いたのですけれども、ご答弁がなかったので、それは今度でいいです。部門別、具体的に計画を進めていくというところで、これから検討していくということですけれども、そうした考えがあるのかどうか伺います。","respondent":"河内環境課長","answer":"部門別に進めるかどうかは今後の検討事項ではありますが、そういったものの削減に向かって取り組んでまいりたいというところです。数値につきましては、すみません、棒グラフしかないものですから、具体的な数字がお出しできませんでした。","id":"exchange-151"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＣＯ２ゼロに向けて重要だと思いますので、やってほしいと求めましたし、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"高橋（伸）委員","kind":"質問","question":"初めに、２９１ページ、環境学習交流施設とＺＥＢ普及支援業務委託についてお伺いいたします。そこで、まず、エコルとごしのＺＥＢの概要と、セールスポイントについてお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"８５％の削減というところで、ＺＥＢは４つランクがあるのですが、上から２番目に位置する都内公共建築物では初となる高いランクのＺＥＢ建築物です。","id":"exchange-153"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"省エネ、創エネの工夫点が本当によく分かりました。この区有施設の面、また、民間の普及促進についての取組みもあわせてお聞かせほしいと求めました。","respondent":"小林施設整備課長、河内環境課長","answer":"所管課と連携を図りながら、まずはエネルギーの削減にしっかり努めてまいりたいというふうに思っております。１０年後の目指す姿として掲げられているところですので… 対象ですが、ＺＥＢ化も検討いたしております民間事業者、デベロッパー、設計事務所など、実施を想定しています。","id":"exchange-154"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、２８９ページ、太陽光発電・蓄電池システム設置助成についてお伺いいたします。昨年度の助成件数と、これから得られた課題は何かをお伺いしたいと思います。","respondent":"河内環境課長","answer":"当該パネル設置は、補強可能の場合か、あるいは新築かに限られているところがあります。多くの申請の方が新築となっているところが課題として捉えるべき問題というふうに考えております。","id":"exchange-155"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次に、２９１ページ、低公害車買換え支援事業についてお伺いいたします。脱炭素に向けた取組みが進む中、この低公害車はどのようなものが対象になるのか、まずお伺いしたいと思います。","respondent":"河内環境課長","answer":"こちらの対象車種ですが、窒素酸化物や硫黄酸化物などの大気汚染物質排出量の少ない車、今まで取り扱っているディーゼル車ですが、そのほか環境負荷の少ない自動車といたしまして、燃料電池車、電気自動車、ハイブリッド車などがこの対象となっているものです。","id":"exchange-156"},{"speaker":"高橋（伸）委員","kind":"質問","question":"現状、区内には、利用可能ないわゆる充電スタンドはどの程度あるのでしょうか。把握しているのであればお答えをお願いしたいと思います。","respondent":"河内環境課長","answer":"こちらにつきましては、カーディーラー、また大型小売店、ホテルなどを中心といたしまして、令和４年２月末現在ですが、１９か所２５基の状況です。令和４年５月に開設いたしますエコルとごしにつきましても、これを備えており、充電が可能な状況となっておるものです。","id":"exchange-157"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次に、電気自動車なのですけれども、化石燃料を使わない点は、脱炭素の面で優位な点は分かりますけれども、ガソリン車の燃費にあたるようなエネルギー効果は本当に優れているのかどうなのか、どのようにお考えなのか尋ねました。","respondent":"河内環境課長","answer":"燃費効率の比較についてです。プラグインハイブリッド車につきましては１.８前後と言われておりまして、脱炭素の有力な取組みになると考えられているものです。","id":"exchange-158"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、２９３ページ、節電啓発、国産間伐材有効活用事業助成についてお伺いします。今後も森林がＣＯ２吸収力を持続していくためには、この鍵となる子どもたちへの啓発について、どのように対応するのか説明を求めました。","respondent":"河内環境課長","answer":"こういった森林の整備も含め、ＣＯ２削減に向かって役立てていくことが重要というふうに考えているところです。子どもたちには、そういったところも含めまして、しっかり啓発を進めてまいりたいと考えているところです。","id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次に、２９１ページ、アスベスト対策事業についてお伺いいたします。確認などをすることが重要と考えておりますけれども、区の対応は、どのように行われているのかお伺いしたいと思います。","respondent":"河内環境課長","answer":"解体現場のパトロールなどを実施していますが、令和３年度から、全ての解体改修現場を対象といたしまして実施しています。現時点で３００件超実施済みです。","id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"意見","question":"最後に、２９５ページ、普及啓発事業で、エコルとごしで、これからワークショップをやったりという中で、清掃の普及啓発にはすごい重要だと思うのですけれども、今後の展開をどのようにお考えになっているかお知らせくださいとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"今後、エコルとごしのほうで、映像のシステムとか、そういったところが大変長けている施設ですので、こういったところを利用しながら、清掃のごみ出しの分別だとか、リサイクルだとか、そういったところも啓発のために使っていきたいと、このように考えております。","id":"exchange-161"},{"speaker":"塚本委員","kind":"確認","question":"そういう中で、有益な事業というふうに思っていますけれども、１つだけ確認をさせてください。いわゆる信用保証料等が経営変化対策資金２０２０等のときは、そこについて、どのようになるのか確認をさせてください。","respondent":"遠藤商業・ものづくり課長","answer":"金額がかかっていないという部分ですけれども、１点目に今お話しいただきました信用保証は、今回こちらのほうでは区として予算化していないです。","id":"exchange-162"},{"speaker":"塚本委員","kind":"意見","question":"３０５ページのＤＸ・デジタル技術活用推進事業ということで、プレス発表のほうでは、こういう認識が書かれておりました。例えば、近隣区と比べて後れているとか、そういったことなのですけれども、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"中小企業全般にわたりまして、確かにＤＸが進んでいないというところで、プレスの部分では我が区という形の言い方をさせていただいているところです。中小企業全般にわたってなかなか、分かっているのだけれども取り組めないというような状況が現状です。","id":"exchange-163"},{"speaker":"塚本委員","kind":"質問","question":"これは新規の事業ということで伺っております。今までの事業との違い、こういったことについてお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"全８回を予定しておりますけれども、その方に８回受けていただいて、企業の中でのＤＸを進めていただくという部分。具体的に私の会社で進めたいのだけれども、具体的に相談に乗れるような体制をとりたいというところの今回の新しい新規事業という形です。","id":"exchange-164"},{"speaker":"塚本委員","kind":"質問・要望","question":"この全８回の講習会というのも、どういうところをターゲットにするか、内容とかもいろいろ変わってくるのだと思うのです。区が新しい事業を始めるにあたって、その企業のＤＸ化による業績の最大効果みたいなものを求める上で、そこについて説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"今の真ん中のところですか、２段階目のところからＤＸに持っていくというところを対象にして講義などをやっていきたいなと思っているところです。","id":"exchange-165"},{"speaker":"塚本委員","kind":"提案","question":"いろいろな提案もあって、１つお聞きしたいのは、どのようにこの環境学習交流施設の中で実施していくのか。どういうスペース、どの部屋を使うのですかみたいな具体的な話でもあるのですけれども、教えてほしいと求めました。","respondent":"河内環境課長","answer":"水族館との連携の特別展示企画を予定しておりまして、１階にありますコミュニティラウンジ、こういった特別展を持ちたいと考えています。それから、公園に根差す講座につきましても、力強くそういったところも進めてまいりたいというふうに考えているところです。","id":"exchange-166"},{"speaker":"塚本委員","kind":"確認","question":"講座もコミュニティラウンジなのでしょうか。ちょっと細かいですけれども確認させてください。","respondent":"河内環境課長","answer":"地域交流室という部屋が別に設けられておりまして、そちらを優先して使っていただきたいというふうに考えております。同じく３階にあります多目的スペース、１階で、もちろん多目的スペースで行う特別展示も今後企画していくところです。","id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"では、そこは今度、ＳＨＩＰみたいな形で利用される人と料金をどうやって分けるのかと。１０％とか、特別日は５０％割引とかやっているけれども、そこら辺の感覚を教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"にぎわいというところで様々なイベントなどができるような形になるのかなというところで、そういう方向で、中身をどうするか今検討しています。","id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問","question":"平日使っていただくときは、例えば、ＳＨＩＰを使っていらっしゃるような方々が小ホールでもいいですよ。平日と土日で、逆に土日のほうがぐっと安いのか、そこら辺のところの感覚を教えてもらいたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"そこの部分の検討経費という形になってきまして、近隣の状況だとか、あとはいわゆる周りの方、区民の方の利用だとか、そういう部分も含めて、今回、検討委託という形で計上させていただいたです。","id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すごくそこはいいのだけれども、そうではなくて、もっと前向きに取り組むときの費用があるではないですか。そうなると、そういうところに何か手を打てるような準備をぜひしていただきたいと思うのだけれども、そういうこともあわせて答弁をいただきたい。","respondent":"遠藤商業・ものづくり課長","answer":"今後いろいろ設備資金など、いろいろな融資の形があります。そういう部分で、区としてどういうことができるか、いろいろな案が出てくるかと思いますので、研究をさせていただければというふうに考えてあります。","id":"exchange-170"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは教育の話になってしまうのだけれども、スチューデント・シティとかファイナンス・パークとか、学年でやっているではないですか。そういう感じのものをぜひ子どもたちに、そういうものでやってほしいなと思うのだけれども、最後にそれだけ伺います。","respondent":"河内環境課長","answer":"木材の利用の補助事業で、今回、青梅のほうに、１８組の親子と行くツアーを企画いたしましてご参加いただいたところです。そういったところの特徴を活かしながら進めてまいりたいと考えているところです。","id":"exchange-171"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":130719,"voices":385}},{"id":"r04-20220311-3","meetingId":"r04-c-budget","date":"2022年3月11日","dateIso":"2022-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を159件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村委員","kind":"質問","question":"長くなってしまいましたが、このような訓練を受けて、地元の方たちからいただいた課題を３点伺います。町会と福祉事業者が持っている要支援者情報をどのように統一していくのか伺います。","respondent":"山本防災課長","answer":"区では避難行動要支援者名簿の作成をしておりまして、ご本人様の同意が得られている場合には、防災区民組織等に情報共有を図っているところです。","id":"exchange-001"},{"speaker":"西村委員","kind":"確認","question":"有事に限られた役員数での要支援者の安否確認が大変だということ、また、その他消火活動と同時になってしまうということを懸念しておられました。災害の程度にもよりますけれども、福祉事業者から安否確認の連絡をもらっても対応できるのかとおっしゃっておりました。","respondent":"山本防災課長","answer":"来年度の避難行動要支援者事業の中で、災害発生時の支援における防災区民組織、検討していきたいと思っているところです。引き続き、区と、それから地域福祉関係者で連携を強めながら、避難行動要支援者の支援体制の強化に努めていきたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"西村委員","kind":"提案","question":"これはご提案ですけれども、多胎児家庭も確認して、これは私自身も研究しながら考えているところです。区のご見解を説明を求めました。","respondent":"山本防災課長","answer":"現在区では避難行動要支援者の名簿、今年度から自助の促進をするためのリーフレットというものを新たに導入して、通知をすることといたしました。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"１点好事例、またご報告させていただきたいのですが、要支援者安否確認訪問用バッグというものがとてもよかったです。カーブミラーなど様々通報できると思いますが、河川の通報はできるのでしょうか、伺います。","respondent":"溝口道路課長","answer":"今回、４月から本格導入する、しなみちレポートの住民通報システムの件ですが、河川といいますか、河川に即した、沿った形で道路があると思います。そういったところも一応区のほうで、私どもが管理しておりますので、併せて今回通報していただけるかと考えているところです。","id":"exchange-004"},{"speaker":"西村委員","kind":"確認","question":"これまでは通報があった場合、電話でやり取りをされていて、一つひとつ地図を開いて確認されていたと思います。手間が大幅に省ける取組みになるのではないかと思いますが、３点伺わせていただきます。","respondent":"溝口道路課長","answer":"どのような対応をしていくのかという対応経緯が、その方に分かるような形で流せるということが１つの大きなシステムの利点です。対応していただいて、補修が終わったとか、そういったものも返していきたいというふうに考えております。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問","question":"１か月レポートのような形でホームページにアップをされているような地域もあるのですけれども、通報があって対応されたかということが報告されるのか、お伺いさせてください。","respondent":"溝口道路課長","answer":"今回導入するシステムにつきましては、住民から投稿いただいたもの、そのすぐ下に、私どもが受け付けましたというものをまず返します。その後対応状況等、どのように区のほうで処理されたのか、一目で分かるようなシステムになっているものです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"１点目に、道路・公園等占用費について、八潮地区の停電についてお伺いします。品川区において、東京電力に対してどのような対応をしていただいたのか、お伺いいたします。","respondent":"稲田土木管理課長","answer":"その日の６時４分に全域送電が完了したという状況ですが、それから今後の対応、そのような立場でやってきました。設備改修も今、順次やっているところですが、その辺もしっかりとやっていただくようにということで、指導のほうをしております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"この皆様に答えていただきましたアンケート結果が、人道橋の設置においてどのように活かされるのか、お伺いいたします。財源はどうなっているのか、お伺いいたします。","respondent":"鈴木都市計画課長","answer":"昨年１２月に行ったアンケート調査ですが、国の支援を受けながら、その中で必要な事業効果を計る指標を確認するためのアンケート調査を行ったです。今ご説明した都市再生整備計画の中で、国からおおむね４５％程度の支援、ちょっと調整していきたいと。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区の予算もここに入ってくると思うのですけれども、国の予算、併せて東京都の予算、活用していただきながら、ぜひ進めてほしいと求めました。公衆便所については要望をいただいておりまして、かねてから要望していますが、ちょっと今の検討状況をお知らせほしいと求めました。","respondent":"高梨公園課長","answer":"今ご案内がありました新浜川公園ですが、都市再生整備計画の中での再整備ということで考えているものです。そのほかの住民の声も聴きながら、皆さんの声を聴いて改修計画に活かしていきたい、このように考えているところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"当初、この令和４年１月に素案に対する意見を募集し、また３月、ガイドライン取りまとめというふうに伺っておりました。これからの八潮地域を担っていく若い方のお声を聴いてほしいということの要望を続けてまいりましたが、また、今後のスケジュールをお知らせください。","respondent":"鈴木都市計画課長","answer":"やはり地域の方、１２月１１日には、幼稚園あるいは保育園のお子様をお持ちの若い世代の方を対象にしたワークショップを実施しています。できるだけ早い時期にというところで、来年度早々にも、できるだけ早いスケジュール感を持ってガイドラインを取りまとめていきたいです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、備蓄物資購入について伺います。この低たんぱく米等ということで、そのほかに何が新しく備蓄物資の中に含まれているのか、お知らせください。","respondent":"平原防災体制整備担当課長","answer":"次年度新たに導入する備蓄物資の予定ですけれども、今、委員ご指摘のとおり、低たんぱく米を新たに導入することとしたところです。まだ難しいような方向けに軟らかい食品、かなりカロリーの高い煎餅のようなものですけれども、そういったものの導入も予定しております。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"液体ミルクが正式な備蓄品ということで、私もかねてから、これを備蓄するようにということで要望しておりましたので、大変ありがたく思います。どのような仕組みで活用されるのかということを確認させていただきたいということと、この液体ミルクに関しては協定を結んでいたかと思います。","respondent":"平原防災体制整備担当課長","answer":"こちら私どものシステムがありますサーバーを管理している部屋、年中空調が効いておりますので、そういったところに入れるというものです。なお、東京都との間では、２日目、３日目の物資については東京都から導入を受けるということで、そのような話合いが進んでいるところです。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問","question":"３４１ページ、３４３ページ、３３５ページのＰａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。１点目に空き家等対策事業、居住支援事業についてお伺いいたします。","respondent":"竹田住宅課長","answer":"居住支援として区で実施している制度、居住支援として、住居の確保に配慮が必要な方の民間住宅探しを支援する制度を今年度からスタートしております。","id":"exchange-013"},{"speaker":"横山委員","kind":"提案","question":"空き家活用の提案書の中に、母子世帯向けのユニークで先駆的な事例なども入れていただきますよう要望いたします。しなみちレポートについてお伺いいたしますとの意見を述べました。","respondent":"竹田住宅課長、溝口道路課長","answer":"ひとり親の抱える問題は住居だけではなく、多岐にわたっていると考えております。居住支援協議会、ぜひご協力をいただいて、住みやすいまち品川の実現に向けて力を尽くしてまいりたいと考えております。そういったものにつながる内容が多くありましたので、これにつきましては有効だというふうに考えて、４月から本格導入をしていくものです。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"有効性が確認されているということと、ぜひ試行、公園の試行のほうも引き続き続けていただきたいと考えています。３点目に、Ｐａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。","respondent":"高梨公園課長","answer":"規模による調査についてですが、まずは一定、その施設の建築が可能な大規模な公園を見繕って調査を開始したいなと考えています。中に建設できる建物の規模が限られてまいりますので、または水辺等の特色のある公園から調査を開始してまいりたい、このように考えているところです。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"なかなか体を動かしたりですとか、全体的な部分というところにも派生させていただいて、調査研究を進めていただきたいと考えています。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"３２５ページ、３２７ページ、それぞれ伺いたいと思います。解体工事を行うに当たっての説明会では、どのような対策が講じられるのか丁寧に説明をしてほしいと求めましたが、いかがか尋ねました。","respondent":"小林施設整備課長","answer":"本格的な解体工事を行う前に実施をしまして、その手法につきましても、近隣の皆様方の家に拡散させないような方法で進めることとしております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"西大井南について、まちづくりニュースは何号まで出ているのか、伺いたいと思います。そして、この事務局を支援する東京建物株式会社ですが、この事務局とどのような内容の協定書を交わしているのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"令和２年の、今ご紹介のあった８月に、どのようなまちに進めていくかということで検討されているところです。補助２０５号線という都市計画道路と、広さは約１.６haが対象ということで、検討されているところです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど伺ったのは、事務局とどのような内容で協定書を結んでいるのかと伺いましたので、改めてご説明ほしいと求めました。この協議会について、何を目的にしていると、品川区は指導、支援する関係になるのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"地域の方が主体で検討されて、その状況のご報告があるときがありますので、そこを教えていただいていると。どのようなまちに進めていこうかということの、区としては支援していく、そのような立場だと認識しています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、協議会の総会や会議に品川区は何回出席したのかと伺いました。現状、この協議会に何人の地権者が参加しているのか、そして参加企業はどこか伺います。","respondent":"多並都市開発課長","answer":"加入者としましては、約３８％の方が出席されているということで、約２９軒の方が加入されているということをお聞きしています。関連する企業としましては、東京建物株式会社、また、コンサルとしては、久米設計というところが関わっているということでお聞きしているところです。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"効果が出てくると思うのですけれども、なので、原踏切の件ですが、どうにかもう今のうちから考えていただきたいと思うのですけれども、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"その中で、首都直下および南海トラフと同時に富士山が噴火したらどのようになるのでしょうかという質問をしました。対策等、区でできる対策等はしていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"栗原河川下水道課長、稲田土木管理課長、溝口道路課長、鈴木都市計画課長、森木密整備推進課長、長尾建築課長、竹田住宅課長、山本防災課長","answer":"西大井五丁目付近の下水道工事ですが、地域の浸水被害を軽減するために必要となります下水道管の整備を、東京都下水道局が実施したものです。… シェアサイクル、西大井駅周辺にです。現在２００ｍから３００ｍの範囲で３か所ほどあるのですけれども、利便性を… そこにつながる２０５号線、しっかり２９号線の進捗状況を踏まえて、しっかり検討していきたいというふうに考えているところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"２年連続でゼロというものに予算をつけていくということは、Ｂ、Ｃなどとついていたではないですか。だけれども、これ、それがあったらもうＣや廃止というように、私はなると思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"事務事業評価の項目といたしましては、あと費用対効果の効率性、この辺は安全・安心の機能ツールというところで満たしているのかなというところです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"令和４年度の実績を見てから、また質問をさせてほしいと求めましたので、よろしくお願いします。ですから、私は噴火一本でこれからも伺っていきたいと思いますので、今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田委員","kind":"提案","question":"それから３２９ページ、都市開発費、広町地区整備検討、３３５ページ、緑化活動支援事業で、屋上緑化等について伺います。広町地区の土地区画整理事業について、昨年１１月３０日の建設委員会の資料を確認いたしましたとの意見を述べました。","respondent":"多並都市開発課長","answer":"土地区画整理事業につきましては、建設委員会の中でも、事業計画の案ということでご説明させていただきました。都のほうが協定を結んで、それで担保していくということで、区としては聞いているところです。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"まだこれから値段を決めるということですけれども、先ほど質問した中で、そのような値段を決めるのもＵＲに全部任せてしまうのでしょうか。ぜひその辺について教えてほしいと求めました。","respondent":"多並都市開発課長","answer":"保留地につきましては、９,７０１m2ということで書かせていただいております。それをまた第三者で見るということで、そのような形で公平性があるということで、区としてもそのような認識です。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"助成をするなら、その先の仕組みも一緒に構築すべきだったのではないでしょうか。それについて伺います。","respondent":"多並都市開発課長、高梨公園課長","answer":"広町についてお答えします。そのような観点で考えているものなので、区が関わるというよりは、そのような形でやっていきたいと思ってあります。公園課といたしましても、屋上緑化をしていただいた後の、その継続といったところは、非常に大きな課題であるというふうに感じております。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"屋上緑化で、この方は多分お金を求めているのではないです。ＣＯ２削減と言っているときに、区内であっても緑が果たす役割は大きいと思うのですけれども、その辺についてはいかがお考えか尋ねました。","respondent":"高梨公園課長","answer":"こういった形でまた養分のある土に生まれ変わるであるとか、窓口で対応する中で丁寧に説明をしていきたいと、このように考えているところです。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望にとどめます。そのようなことについて、どこにどのように注意を呼びかけていらっしゃるのか、現状を伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"日頃から反射材等を使って事故防止に努めてもらいたいということと、そのような事故の発生状況等の話をしながら、安全教育等を実施しています。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"何ですか、電動キックボードでしたか、何かそのようなものもいろいろ、便利な分危ないことも出てきています。広くご家族への呼びかけとか、そのようなことも含めてやってほしいと求めましたが、改めてちょっと見解を伺います。","respondent":"川口交通安全担当課長","answer":"そのような事故防止に努めるように、いろいろと検討していきたいと思います。高齢者を対象とした、これをまた区でも、どのような形で区民の方々に周知できるかというところも併せて検討していきたいというふうに考えております。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後ちょっと時間がないので、要望だけしておきます。これは要望だけにとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"木村委員","kind":"質問","question":"私からは３０９ページ、下から７行目、駅周辺等放置自転車対策事業から質問いたします。説明を求めました。","respondent":"川口交通安全担当課長","answer":"これが１,０８４台ということで、６,９２０台が今年の１月３１日までの台数で、この撤去の状況は増えているという状況です。引き続き広報啓発に努めて、また、自転車駐車場をご利用いただくという啓発活動を引き続きしていきたいというふうに考えております。","id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"やはり撤去台数ですか、本当に毎日毎日撤去をするわけですから、よろしくお願いします。そのようなものについて、わざと路上に放置をした行動を取ることが考えられますが、このような前例というものはあったのか尋ねました。","respondent":"川口交通安全担当課長","answer":"放置自転車に対するお尋ねです。今のところ、その撤去に対する返還等のバランスがありますと、少なくとも何割かはそのような状況もあるのかというふうには考えております。","id":"exchange-033"},{"speaker":"木村委員","kind":"質問","question":"海外では、ロンドンやパリにおいては既に１００％の無電柱化を達成しておりますが、救助の妨げになるケースなどもあるとお聞きいたしました。本区においても、この区道約３２７kmのうち、約２３km、約７％しか、まだこの無電柱化が進んでいないということをお聞きいたしました。","respondent":"溝口道路課長","answer":"無電柱化につきましては、令和２年度に無電柱化推進計画というものを品川区はつくって、今、無電柱化の整備を進めているところです。地中の中に電線を入れていかなければいけない、そういったところでどうしても工期がかかってしまう、そういったものが今の状況です。","id":"exchange-034"},{"speaker":"木村委員","kind":"質問","question":"本区の無電柱化事業は現在どのように進んでいるのか、一説には、現在とこれからの本区の工事の進行状況はどのようになっていくのでしょうか。説明を求めました。","respondent":"溝口道路課長","answer":"委員ご指摘の令和元年度に基本方針というものをつくりまして、令和２年度に推進化計画をつくっています。来年度から具体的に進めていきたいというところで、来年度予算を取って、無電柱化に向けて優先順位をつけながら現在整備を進めているところです。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"それから３３９ページ、３４５ページ、防災対策総合推進費について伺います。先ほど横山委員からの質問に対する答弁で、何平米ぐらいを想定して、何平米以上のところというふうに想定されているのか伺います。","respondent":"高梨公園課長","answer":"規模についてですけれども、平米数で絞って、１万平米以上などというような基準では考えてございません。池田山公園、東品川海上公園等、複数の公園を今調査対象として考えているところです。","id":"exchange-036"},{"speaker":"松本委員","kind":"質問","question":"北谷公園ですか、あそこの規模は１,０００平米を下回っているということで、かなり小さい規模になっていました。まだこれから調査・検討の段階だと思うのですけれども、そういったテーマの方針というものが、もし今の段階で何かありましたらお願いいたします。","respondent":"高梨公園課長","answer":"可能性を見いだしていきたいというふうに考えてありますので、その中で区としてもしっかり方針を探していければなというふうに考えてあります。","id":"exchange-037"},{"speaker":"松本委員","kind":"質問","question":"総務課の款でもお伺いした自動販売機との関係で聞きたいなと思っているのですが、平成３０年の大阪府北部地震で、改めて注目を集めていると。これ、実際に十分な耐震性を有していないブロック塀というものは、どのくらいあるというふうに理解すればよろしいのか尋ねました。","respondent":"長尾建築課長","answer":"ブロック塀の安全化の件で、平成３０年度に行った調査の中で、今ご紹介いただいた延長１０５kmほどというところが把握できたところです。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"ブロック塀等の倒壊で１名死亡、２８名負傷というような想定になっています。現状届出制もないので把握できていないと思うのですが、１回自動販売機についても調査をされたほうがいいと思うのですけれども、いかがか尋ねました。","respondent":"山本防災課長","answer":"地域防災計画の中で転倒防止対策の強化というところは記載をしていますが、具体的な対応というところは今後考えていきたいと思っているところです。今ご提案ありました調査というところも、研究等を進めていきたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"では具体的にどうするのかというところになってきていて、民間というか、区民の方からの通報を受けるというような手段もあると思います。そのようなやり方もあると思いますが、区民の皆さんからのお力を使うというようなやり方については、いかがお考えか尋ねました。","respondent":"山本防災課長","answer":"区民からの通報です。１つ効率的な方法かと思いますので、どういった仕組みでできるのかというところも含めまして、いろいろ研究等を進めていきたいと思ってあります。","id":"exchange-040"},{"speaker":"小芝委員","kind":"質問","question":"私からは３２３ページ、地域交通検討経費、コミュニティバスについてお伺いいたします。その辺り、打開策についてお考えがありましたら、教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"基本的に先ほどご紹介いただいたように、３分の１程度まで落ちるというところで、車椅子の方が乗ると７名程度の人数しか輸送できないです。ご提案いただいた考え方というのは１つあろうかと思うのですが、その１つの考え方として、さらに警視庁との協議を進めていきたいです。","id":"exchange-041"},{"speaker":"小芝委員","kind":"確認","question":"確認のほうさせていただきました。一般の車両が駐停車することを防いだりとか、こういったバス停の前での白線の表示というものはされるのかどうか、お答え願えますか尋ねました。","respondent":"鈴木都市計画課長","answer":"あるいはタクシーですとか、そうした一時的な駐停車を注意していただくという注意喚起を込めて、そうした白線を整備していくと。運行開始までに整備していくです。","id":"exchange-042"},{"speaker":"小芝委員","kind":"質問","question":"次に、バスの収支率について伺います。３年目の収支率が５０％以上かどうかで、そのほかの収入も含まれてくるのではないかと思われますけれども、この収入の考えについて説明を求めました。","respondent":"鈴木都市計画課長","answer":"収支率を考える場合の収入の部分につきましては、やはり大きくは運賃収入というところでございまして、それ以外のところとしましては、やはり広告料ですとか、そうした費用も見込んでいくというところになろうかと思います。","id":"exchange-043"},{"speaker":"小芝委員","kind":"質問・要望","question":"私はシルバーパスもぜひ金額換算した上で、この収入に組み込んでもらいたいと考えますが、どうでしょうか。５０％の数値目標をもっと柔軟に評価していただきたいと考えますが、その辺り、２点についてお答え願えればと思います。","respondent":"鈴木都市計画課長","answer":"実際は、具体的には、この３年間の中でその辺の考え方を、運行実績を見ながらしっかり整理していきたいです。やはり５０％というところでスタートしたいというふうには考えてありますが、これも、しっかり検討していきたいです。","id":"exchange-044"},{"speaker":"小芝委員","kind":"質問・要望","question":"ぜひそういった事情もしんしゃくしてほしいと求めました。この２８日から試行運行が始まる予定ですけれども、そういった考えというのがあるのかどうか、ちょっと確認をしたいと思います。","respondent":"鈴木都市計画課長","answer":"利用者あるいは周辺の方へのアンケートというものはしっかり実施して、利用者、いかに多くの方に乗っていただくかというところにつなげていきたいというふうに考えてあります。","id":"exchange-045"},{"speaker":"小芝委員","kind":"意見","question":"３年目の収支判断に向けまして、試行錯誤を繰り返していくことが必要と考えます。その上でフィードバックを行い、適宜改良を重ねてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"２０１９年にも、対応いただくというような視点はどうでしょうかというようなことも、提案させていただいておりました。会派から提案があって、このしなみちレポートの拡大ということで、公園のほうにも拡充していくということをすごく大変評価しているところでありますとの意見を述べました。","respondent":"溝口道路課長","answer":"これにつきましては東京都と連携して行う関係で、品川区としては、予算をかけずに試験運用を行ってきているところです。道路課のほうで取っている５００万円弱の予算で、今回のしなみちレポート、そういったものが行えるということになっているものです。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"その場で何かがあれば教えていただくというようなこともできるのかなと思いますので、その辺り、愛称と公園へのＱＲコード掲示について説明を求めました。","respondent":"溝口道路課長、高梨公園課長","answer":"今回、道路のほうを先行して、本格導入ということでしなみちレポートという形で今回出させていただいているところです。本格運用する際には、しっかりと区民の方に親しまれるような名称… は試験運用ということで、４月１日付の広報しながわをはじめ、ホームページで広報していきたいというふうに考えてあります。","id":"exchange-048"},{"speaker":"つる委員","kind":"確認","question":"本会議でも確認させていただきましたけれども、Ｐａｒｋ－ＰＦＩの推進の中の運用が、目標年度が令和１３年度となっている。９年、１０年先の話になってしまうのかなというところで、この辺の選定についての候補についてもあれば説明を求めました。","respondent":"高梨公園課長","answer":"事業者の考え、来年度検討の中で、このように考えてあります。もう１点、荏原地域の公園の中での事業性等についてもヒアリングするなど、取組みを進めてまいりたいというふうに考えてあります。","id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"２０１６年の予算特別委員会のときに、５月２４日、いろいろな施策に展開したらどうでしょうかという提案もさせていただきました。はせられるような、そのような公園の展開もぜひお願いしたいのですが、ご答弁ほしいと求めました。","respondent":"高梨公園課長","answer":"もしくはその模したものだけすればといったものではないとも考えておりまして、しっかりその公園においては説明も必要なのかなと考えています。平和を担当する部署とも連携しながら、取組みをさせていただければと考えております。","id":"exchange-050"},{"speaker":"つる委員","kind":"提案","question":"２０１９年の１定では、桜などについての記念植樹についても提案をさせていただきました。１本でも多く品川区内に植えていただきたい、駅に植えていただきたいという思いがありますので、この桜についての品川区の取組みを説明を求めました。","respondent":"高梨公園課長","answer":"自らの人生のイベントごとに、その桜の思い出がともにあるようなものだと考えています。その思い出、その思いが未来永劫生き続けられるようにという思いを込めて、しっかりこの事業を進めてまいりたいと考えております。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３３３ページ、３３５ページ、Ｐａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。この一番最後の工程となる第２工区、このにぎわいゾーンでこれから工区が始まるに当たって、何か変わった点や改善点があったら説明を求めました。","respondent":"溝口道路課長","answer":"立会川緑道につきましては、委員ご指摘のように、令和元年度から４工区に分けて工事を進めてきて、来年度最後の工事になるところです。","id":"exchange-052"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続いて３２５ページ、不燃化特区支援事業についてお伺いいたします。令和７年度までに、現在の現状、進捗状況をお知らせほしいと求めました。","respondent":"森木密整備推進課長","answer":"例えば従前居住者用住宅に移っても構わないとか、あるいは、区の事業への協力をしたいというような方も出てきているところです。そういった声を丁寧に聴きながら、こういった機会を逃さずに事業を進めてまいりたいというふうに考えているところです。","id":"exchange-053"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ここは本当に長屋で、南西の風が吹いたときには、旗の台小学校だけではないですけれども、もう学校側にも恐らく火の粉が行くと思うのです。いわゆるハーモニカ通りのところの、大体どのぐらい、今何割ぐらいの方に対して交渉しているのかということもお知らせほしいと求めました。","respondent":"森木密整備推進課長","answer":"先ほど申しました戸別訪問につきましては、なかなかお会いできない方を除いて、全部戸別訪問させていただいているところです。そういった方々のまとまりで、まずはちょっと考えていきたいと思っているところです。","id":"exchange-054"},{"speaker":"高橋（伸）委員","kind":"提案","question":"続きまして、３３３ページ、みんなに愛される公園づくりに関連して、質問させてほしいと求めました。予算の中で、私たちの会派からはインクルーシブ公園というものも提案していますが、どのようにお考えになっているのか教えてほしいと求めました。","respondent":"高梨公園課長","answer":"約３０個のアイデアを取り入れて整備をいたしましたけれども、遊具の取替え等についても、展開をしていきたいというふうに考えてあります。今年度設計作業を行っておりますけれども、そちらのほうでインクルーシブ遊具を設置ということで、現時点では考えているところです。","id":"exchange-055"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひとも、これからも要望しますので、インクルーシブ公園への展開よろしくお願いいたします。これは２０１７年の都市公園法改正によって新設された制度だと思うのですけれども、Ｐａｒｋ－ＰＦＩに関しての説明を、まず最初にお伺いいたします。","respondent":"高梨公園課長","answer":"法上では、公募設置管理制度ということで位置づけをされておりまして、公園利用者の利便性の向上に資する公園施設の設置と。今まであった公園施設の設置管理許可の許可期間は１０年間ですが、公園施設の中に建物を建てることができるといったようなものがあります。","id":"exchange-056"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この北谷公園は２０２１年の４月に開園したということで、私もこれ見たのですけれども、時代を先駆けるような公園だと思います。何というのですか、ちょっと同じような質問になるかと思いますけれども、そこをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"今のはやり廃りだけではなくて、内部の検討だけではなくて、地域の声も聴きながら検討を進めてまいりたいなというふうに考えているところです。その事業性といったところもしっかりと把握をしながら、進めてまいりたいというふうに考えてあります。","id":"exchange-057"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今年の１２月にはオープンするという話も伺っている中で、何というのですか、何かそのような声はいただいているのですか。それだけお分かりになれば、ひとつ確認させてほしいと求めました。","respondent":"溝口道路課長","answer":"個別の商業ビルの建設の件で、特段道路についてということはありませんが、開発環境指導要綱にのっとった形での歩道状空地とか、そういったところのお話はいただいているところです。","id":"exchange-058"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すみません、突然に。もしそのような声があったら、ぜひいろいろと検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問","question":"私はその声を２回の一般質問で紹介してきましたし、４定や１定に出された請願は、その反対の声そのものです。この点をお伺いいたします。","respondent":"多並都市開発課長","answer":"第２地区についてですけれども、まずは地域の方が準備組合の中で地域主体でまちづくりを検討していただき、昨日の３月１０日に決定したものです。地域の今のまちづくりを早く進めたいと、その中で進めたですので、それを含めた審議で適切な手続きを進めているという認識です。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"区は、準備組合に対して指導助言しているというふうに説明するのですけれども、具体的にはどのような指導助言をしているのか伺いたいと思います。このような思いを尊重するために、具体的にどのような指導助言をしているのか伺いたいと思います。","respondent":"多並都市開発課長","answer":"そのときに、その中で皆さんでしっかり検討していただきたいなと思っているところです。法令で定めのある補償の中で対応できるということで、適切な対応をできるように、その際によく確認しながら適切な対応ができるように。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問・要望","question":"このような都市計画手続は一旦中止すべきではないかと私は思うのですけれども、この点いかがでしょうか。伺います。","respondent":"多並都市開発課長","answer":"これまで検討いただいて、ここに今、このような形でご提案いただいて手続きを進めているところです。今後の活性化につながり、また安全なまちになるように、しっかり支援させていただきながら進めていくべきと考えるところです。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問","question":"これでもって権利が保護されているというのは、言えないのではないですか。この点伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"田中委員","kind":"確認","question":"その中で区は、準備組合はまちづくりに賛同する方々が集まる組織と答弁されていますが、この認識は正しいでしょうか。伺います。","respondent":"多並都市開発課長","answer":"この組織の考え方といたしましては、今後住むまちをどうしていこうかということを検討するために集まった方々の集まりですので、そのようなまちづくりを検討することに賛同する方が集まっているというふうに認識しているということでお答えさせていただいたものです。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問","question":"では、次の質問をします。区としての補助金はどのくらいと見込んでいるのかということはちょっと伺いたいのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"今度は法令に基づく組合ということで、組合の設立に向けて、これから地域の方でご検討いただくところです。今後そのような形で整理されて、区もしくは都のほうに提出されてくると、そのような説明をさせていただいたものです。","id":"exchange-065"},{"speaker":"田中委員","kind":"質問","question":"では、今は区としての補助金がどのくらい出るかも分からない状態の中で認可をしているということで間違いないか尋ねました。","respondent":"多並都市開発課長","answer":"組合設立および事業計画の申請があって認可するものですので、まだ現時点では認可しているものではございません。今後、認可するものというふうにご理解いただければと思います。","id":"exchange-066"},{"speaker":"田中委員","kind":"確認","question":"補助金がどのくらいかという金額も見込んで、これから認可するのですよね。確認させてください。","respondent":"多並都市開発課長","answer":"事業計画の中に資金計画があって、その補助金がその中に入って、それを基に事業計画として認可しますので、今後それが含まれて示されると。入ってくるという理解をいただければと思います。","id":"exchange-067"},{"speaker":"田中委員","kind":"質問","question":"では、認可するときには補助金を大体どの程度出すかということは示されるという認識でいいでしょうかということと、先ほどの準備組合の考え方ですが。そのことについてどのようにお考えか尋ねました。","respondent":"鈴木都市計画課長、多並都市開発課長","answer":"ただ、当日の委員会の中では、その賛成・反対意見も含めて、細かく丁寧にご説明をして、会のほうを進行させていただいたです。それから都市計画審議会のスケジュールは、広報にも周知していますし… 補助金については、事業計画の中に補助金が入ってくるです。","id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問","question":"それから３４５ページ、それから３４９ページ、３０９ページの駅周辺等放置自転車対策事業を伺いたいと思います。平成３０年に導入されたドローンですけれども、どういった性能のドローンを所有しているのか、そういった機能があるのかをお尋ねいたします。","respondent":"山本防災課長","answer":"こちらにつきましてはライセンス、職員のほうが今５名取得しておりまして、こちらのほう、月１回程度の訓練を実施しています。夜間のほう、赤外線カメラがありますので、夜間の撮影もできる仕様になってあります。","id":"exchange-069"},{"speaker":"湯澤委員","kind":"質問","question":"そのように地区ごとに１台の、５台同時に飛ばせるような体制になれば、いかがでしょうか。災害から７２時間は、瓦礫の下にいらっしゃる生存者などの発見にもつながるのではないかなと思うのですけれども、こちらについてご意見を伺います。","respondent":"山本防災課長","answer":"今その１台で、今後、運用方法等も検討していきたいというふうに考えてあります。事業者のほう今３社と結んでございまして、必要に応じてそちらのほうにご協力をお願いする予定です。","id":"exchange-070"},{"speaker":"湯澤委員","kind":"質問・要望","question":"平時において、防災課との合同練習を可能ならば行っていくべきではないかなと思いますが、いかがでしょうか。練習場所や時間についても、あらゆる状況を想定して様々に行っていくべきと考えますが、ご見解を説明を求めました。","respondent":"山本防災課長","answer":"それから平時の訓練ですが、こちらも協定の内容に、訓練等も共同で実施ができる内容となっているところです。それから様々な状況での訓練ですが、今後様々な状況で実際に対応ができるよう、訓練のほうも充実させていきたいと思ってあります。","id":"exchange-071"},{"speaker":"湯澤委員","kind":"提案","question":"これは提案になるのですけれども、避難所訓練の際にドローンを飛ばしていただくなどすると、波及効果があるのかなというふうに考えます。今後の訓練メニューに入れていただくことなども検討していただけないかと思いますが、ご見解を伺いますとの意見を述べました。","respondent":"山本防災課長","answer":"訓練のほう、いろいろな方に参加いただけるように、充実したメニューというものを区としても考えているところです。協定事業者も、そちらのほうの連携強化という意味も含めまして、そういった訓練での活用というところは積極的に考えていきたいと思ってあります。","id":"exchange-072"},{"speaker":"湯澤委員","kind":"質問","question":"一般質問でも取り上げさせていただきましたけれども、明日行われる予定ではありますが、区民の防災意識向上にもつながると考えております。コロナ禍でも楽しく行える、そういった企画も増やしていくべきと考えますが、ご見解をお伺いします。","respondent":"山本防災課長","answer":"アイデアを聞く機会というものはたくさんあるのですけれども、それ以外の区民の方の意見を聞く機会というと、なかなかないのが現状です。区の啓発活動も含めまして、訓練も含めまして、今後どういった機会が提供できるかというところは考えていきたいと思っているところです。","id":"exchange-073"},{"speaker":"湯澤委員","kind":"意見","question":"私自身も利用しているのですけれども、平日の朝の７時や８時台になりますと、多くのダンプカーやトラックが止まっております。この２６号線は都道ですけれども、区民の思いを区でできることはないのかと考えていますけれども、区のご見解をお知らせくださいとの意見を述べました。","respondent":"川口交通安全担当課長","answer":"その活動は、１つの組についてはあそこを専従で回しているというところの回答をいただいているところです。特に通勤通学の時間帯、このような時間帯にもシフトした、引き続きの取締り活動をするように要望していきたいというふうに考えております。","id":"exchange-074"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そこに対して注意を促せば、少しは解決していくかもしれません。警察に対しても、区民のためにぜひとも強く要望していただきたいと思うのですけれども、その辺に関してもう一度ご答弁いただけますか尋ねました。","respondent":"川口交通安全担当課長","answer":"そのような対策、交通管理者に対する対策も併せて、警察と併せて連携をした協力要請をしていきたいというふうに考えております。例えばその駐車車両に迷惑性とか、あと移動の緊急性があれば、その辺のところを併せた広報を区としてもやっていきたいというふうに考えております。","id":"exchange-075"},{"speaker":"湯澤委員","kind":"質問・要望","question":"時間がありますので、駅周辺等放置自転車対策事業についてお伺いします。この件は、武蔵小山駅に限定して、ちょっとお伺いしたいと思うのですけれども、自転車対策の成果についてお伺いいたします。","respondent":"川口交通安全担当課長","answer":"それぞれ全体では６,９２０台という中で、今年の１月３１日現在で２,０８８台と、プラス３８２台です。今４０％台にまで上がっておりますので、また引き続き、駅周辺の放置自転車を防止するための広報啓発を進めていきたいというふうに考えております。","id":"exchange-076"},{"speaker":"湯澤委員","kind":"質問・要望","question":"やはりそういったところというのは、どうしてもこれをなくしていくには、もう利用者のマナー、それしかないのかなと考えています。そういったことをしていかなければいけないのかもしれないので、そういったところもしっかりと注視してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"結局それに巻き込まれるということが多くて、そちらのほうの指導もぜひしていただきたいなと考えていますが、いかがでしょうか。警察であったりという、そのような方々とのコラボも可能なのではないかなと思うのですが、その辺はどう考えられていますか尋ねました。","respondent":"川口交通安全担当課長、鈴木都市計画課長、平原防災体制整備担当課長、五十嵐災害対策担当課長","answer":"今回事業を開始するわけですけれども、実際の事業の開始に当たりましては、その際には歩行者が安全に横断できるような形で運用していく予定です。… 自転車活用推進計画、平成２８年に国のほうが自転車活用推進法を定めまして、公布しまして、東京都、国が昨年計画の改定を行ってあります。全体的に… 今回のは、備蓄品の管理とともに一括で構築するようなものでございまして、そういったものを令和４年にやらせていただきたいと考えています。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"今ご答弁いただいた、区民の皆さんへのＰＲをぜひしっかりやってほしいと求めました。そして近隣との自助、共助ということがあると思いますので、進めていただくようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"３４３ページ、３４５ページ、この３点を順不同でお聞きしたいと思います。居住支援協議会において、住宅支援要配慮者に対する具体的な施策展開のための協議などは、今後どのように行われていくのか尋ねました。","respondent":"竹田住宅課長","answer":"令和４年度予算では、居住支援協議会の支援委託費の中に、セーフティネット住宅の調査経費として１５３万円を計上しています。今後の見通しですが、国や都の補助金を受けられるように制度のほうをＰＲ、および進めていきたいと考えております。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"住宅確保要配慮者への施策の拡充として、家賃低廉化の補助を活用した住宅確保要配慮者のための居住支援策が可能となる制度の活用を求めてきました。実施要綱などの策定などを進めるなど、実効性ある家賃低廉化助成を進めていただきたいと再度要望いたしますが、区のご見解を説明を求めました。","respondent":"竹田住宅課長","answer":"こちらの制度をどのように品川区で導入していくかということの調査経費として、今回令和４年度予算のほうに計上します。居住支援協議会のほうでもご議論いただきまして、品川区でどのように実施していくことが一番理想的で効果的なのかということをご議論いただいて。","id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ、そのように調査をしていただきながら進めていただきたい、このように思います。その軽減策も併せて考えていく必要があると考えますけれども、その点について、区のお考えはどのようにお考えか尋ねました。","respondent":"竹田住宅課長","answer":"家賃や設備の改修だけではなくて、それ以外の、ハード面以外のソフト面の支援も必要だというふうに考えております。東京都は指定居住支援法人として、そういったソフト面を支援する会社を３５社ほど指定していますので、こういった支援法人の活用も考えながら。","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問","question":"昭和４５年以前の住宅となりますと、築５０年以上になると思います。計画的なメンテナンスだけではもたないのではないかと考えますが、その点、区のお考えを説明を求めました。","respondent":"竹田住宅課長","answer":"それに基づきまして、予防保全的な維持管理や、耐久性の向上に資する改善等を計画的に実施しております。で、その役割を終えるまでのトータル費用を削減していくことも重要だと考えておりますので、両方を並行して考えていきたいと考えています。","id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"決算特別委員会、予算特別委員会等でエレベーターの設置を要望してきましたけれども、日影の問題などでなかなか話が進まないのが現状です。計画策定を来年度の調査というところを考えていただきたい、このように思いますが、区の方針などを説明を求めました。","respondent":"竹田住宅課長","answer":"委員ご指摘のとおり、日影の既存不適格により、エレベーターが設置できない状況になっているという課題を抱えていることは認識しています。区営住宅全体を考えながら、各個別の住宅についても適切な時期に建て替えをすべく、検討していきたいと考えております。","id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"増設する前の既存駐輪施設の利用割合は８５.１％となっていましたけれども、２０１７年度増設後の利用割合はどのような状況でしょうか。この駐輪施設、３階建てになっておりますけれども、築年数と当日利用、定期利用の利用割合も併せて説明を求めました。","respondent":"川口交通安全担当課長","answer":"現在、令和３年度ですけれども、こちらにつきましては５４０台で８４.８％が全体となっております。こちらにつきましては、昭和６１年６月に当時の自転車駐車場整備センターが設置いたしまして、これは築３５年という形になっております。","id":"exchange-085"},{"speaker":"こんの委員","kind":"質問・要望","question":"駅周辺の環境が大きく変化するという予測から、駅周辺の放置自転車対策の強化が、今後さらに求められると考えております。既存のこの３階建ての駐輪場については、上の階への利用促進を図る取組みを、何か取り組んでいらっしゃることがありましたらお知らせください。","respondent":"川口交通安全担当課長","answer":"現在係員を１名増員いたしまして、その上のほうに自転車を駐車する際のサポート、こちらのほうを１人設けております。将来的な整備検討につきましては、今後の周辺地域のまちづくりも絡めた状況で考えていきたいというふうに考えています。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"３２３ページ、航空機騒音測定委託に関わって羽田新ルート、３２６ページ、都市開発費、超高層再開発について伺います。巨額な税金を入れるのですから、小山三丁目第１・第２地区再開発の補助金額について聞きますと、現時点でお答えするものはないとのことでした。","respondent":"多並都市開発課長","answer":"その内容が試算という形で、準備組合の中で検討されているということですので、その内容の説明をさせていただいているものだと思います。最初のほうのご説明をしますと、その見込みのというものは、準備組合の中で検討している内容ですというご説明になります。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"その額でいいので教えてください。都市計画決定されているわけですから、見込みで教えているのに、これはちょっと大問題だと思いますけれども。","respondent":"多並都市開発課長","answer":"今の見込みというお話ですけれども、要するに準備組合と民間組織の中で検討されている資金計画の試算というところだと思います。そのときは民間事業者が今検討している資金計画の見込みを、今検討されていますということで、そこの経過をお話ししたと思ってあります。","id":"exchange-088"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと伺いたいのですけれども、区として減便中の一時中止すら国に求めないということでよろしいのでしょうか。伺います。","respondent":"多並都市開発課長、鈴木都市計画課長","answer":"先ほどと重なりますが、資金計画というものは、民間の事業者の中で検討しているのをずっと続けている段階です。したがって、その検討している段階では変動するものですので… これはご紹介いただいたとおり、事前の教室型説明会を含めて、私は全て出ましたが、そうした話がなかったということは事実です。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問・要望","question":"固定化回避検討会で早急に具体的な方策が示されるよう求めると言っておりますが、１０年のスケジュール感だと理解してよろしいでしょうか、伺います。国の固定化回避の方策が導入されるまで、区民には騒音被害や落下物墜落事故への不安は我慢していただくという考えなのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"この運用が開始して、これは継続して固定化回避に向けた検討は行っていただきたいということで、国のほうが行っているわけです。やはり継続して行っていただきたいということは、これまでも、今後もしっかり国のほうに伝えていきたいです。","id":"exchange-090"},{"speaker":"安藤委員","kind":"質問・要望","question":"もうシミュレーターを使っているのですから、区として今すぐこのルートについて明らかにするよう国に求めていただきたい、少なくとも。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"具体的なルートを決めての検証はまだ行われてないという回答でございました。引き続き、早急な検討結果を求めてまいりたいです。","id":"exchange-091"},{"speaker":"渡部委員","kind":"質問・要望","question":"３１５ページの都市計画道路に入るのでしょうか、一般質問でもさせていただきました、昨日中途半端になってしまいました。例えば私たちは１０月の第４週にやっていたのですが、もうそれに完璧に取って代わるような形になっていくのかというところもお伺いしたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"医療救護訓練を実施したいと考えておりまして、ではどこでヘリコプターを使うのかということは、今東京都と検討しています。子ども向けの訓練としては、小山台小学校で親子参加型の訓練ということを、現在検討を進めているです。","id":"exchange-092"},{"speaker":"渡部委員","kind":"質問","question":"本当に、せっかくそれだけ大きなものがあるわけですから、何かそこで様々なことをして、人に出てきてもらう。だけれども、なぜこのようなときにこれほど混んでいるのだろうというときは混んでいる、もし分かれば説明を求めました。","respondent":"稲田土木管理課長","answer":"それで、その後この調査を実施しましたけれども、まだ調査を実施して荏原警察署にこのデータ等の話をしているという状況だそうです。調査は実施したいということを言っておりますので、区、いろいろと考えていきたいなと考えています。","id":"exchange-093"},{"speaker":"渡部委員","kind":"質問・要望","question":"１つだけ、渋滞にはまってしまうのでというような一般質問の内容だったのですけれども、もう常にお願いはしておきたいと思います。まず、この調査自体が何なのかと、それをどのように活かしていけるのかということをちょっとお話しいただきたいです。","respondent":"高梨公園課長","answer":"近隣区であったり、東京都とも連携を取りながら、そういったお示しをする冊子を取りまとめていきたいなと思います。見て魅力のある、概要版を含めた冊子作り、計画づくりということに努めてまいります。","id":"exchange-094"},{"speaker":"渡部委員","kind":"意見","question":"ただ、冊子になればなるほど、持ち歩いてほしいと思うのです。よろしく願いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは、３４５ページ、防災関係組織経費、そして３４９ページの応急活動対策費、これ全般について質問します。要は組織の課題、そういった要望、そういったものの配布があったのか説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"訓練アンケートについてなどのお尋ねですが、予定していた訓練を中止された自主防災組織には、アンケートは行っておりません。なお、自主防災組織の活動率については、把握しておりません。","id":"exchange-096"},{"speaker":"松澤委員","kind":"質問","question":"だからこそ、このソフト面の強化、これを考えていかなくては、課題の解消につながらないのではないでしょうか。昨年しながわ防災学校、これにつなぐとご答弁がありましたけれども、ほかにも行っているものがあるのか説明を求めました。","respondent":"山本防災課長","answer":"区では区民消火隊など、１０年以上活動された方への感謝状の贈呈を防災フェアの中で実施したり、また。引き続き自主防災活動の啓発などを行いまして、より多くの区民の方に知っていただく機会を提供していきたいというふうに考えてあります。","id":"exchange-097"},{"speaker":"松澤委員","kind":"質問","question":"みんなでつくり出す防災動画というのですか、要はケーブルテレビ品川を巻き込んでもいいと思っています。そういったものに興味を持ちやすい、そういった考え方にシフトするべきだと思いますけれども、ご見解を説明を求めました。","respondent":"山本防災課長","answer":"非常に効果的だというふうに考えてありますので、今後の啓発方法の１つとして、具体的に考えていきたいと思っているところです。それからオフライン、それぞれ組み合わせながら、より効果的な啓発方法というものを進めていきたいというふうに考えてあります。","id":"exchange-098"},{"speaker":"松澤委員","kind":"質問・要望","question":"何かそのようになって面白さが本当に増すと思っていますので、やってほしいというわけではなくて、ぜひ活用してほしいと求めました。地区防災訓練で周知、そしてまた行動を起こしていかなければならないと考えますが、ご見解を説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"平成２９年から「集まれ、親子防災体験」を実施し、ゲーム感覚での訓練を新しい取組みとして導入しております。４５年ぶりに実施する東京都・品川区合同総合防災訓練に、各地区総合防災訓練の参考となるような新しい訓練コンテンツを取り入れる予定です。","id":"exchange-099"},{"speaker":"松澤委員","kind":"確認","question":"多分都か国だと思うのですが、そういったところを整備すると認識しておりますが、ここを確認させてください。この避難所への、要はＷｉ－Ｆｉの整備、これは進んでいるのか、避難所に導入する計画なども説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"これは、こちらのサービスの実施について提案を受けまして、災害時における活用という観点からも整備を進めてまいりました。区内での基地局の整備も進んでおりまして、災害時に避難所でＷｉ－Ｆｉを利用する環境は整ったところであり、現在活用の詳細を詰めている段階です。","id":"exchange-100"},{"speaker":"松澤委員","kind":"質問","question":"何か防災に関することを１つ入れるとか、そのＷｉ－Ｆｉの機能を確かめる、こういった取組みはどうでしょうか。ご見解を説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"地域によりましては、このような先進的な取組みを、他の地域でも参考となるように共有してまいりたいというふうに考えてあります。で、先ほど説明させていただきました地域ＢＷＡによるＷｉ－Ｆｉにつきましては、事業者のほうにも確認を進めてまいりたいと思います。","id":"exchange-101"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひその活用の確認をしていただいて、どうすればそういったうまい利用というのですか、ぜひ前向きに検討していただきたいと思っています。品川区における消火栓の水利の設備状況、これだけ最後に説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"品川区における水利、貯水槽ですけれども、４０トン以上のものでいきますと、現在区内に１３３か所、こちら区の管理のものですが、整備させていただいておりまして、消防庁からお話を聞くところによりますと、水利は充実しているというようなご回答をいただいているところです。","id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"３２３ページ、これは総務費のほうで、八潮地区まちづくり事業のほうで行われるという質疑がありました。そういった成果はどのように関係して、それでどのような役割を果たす、関わっていく状況なのか尋ねました。","respondent":"鈴木都市計画課長","answer":"八潮の担当が設置されるというところとの関係性ですが、まさに今も進められているというところで、ガイドラインの作成を目指しています。地域コミュニティの継続した検討ですとか、ある意味将来にわたっての八潮の在り方等々についても幅広く検討されるですので、連携をして。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そして先ほども少しありましたが、この計画策定の後、自転車関連の区の事業はどの方向に向かっていくのでしょうか。何というのですか、幅広くつかむ担当の設置を求めますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"それから、計画期間のほうは、基本的には２か年をかけて、学識経験者を入れた検討委員会を設置して、２か年をかけて策定を進めていきたいです。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この計画がきちんと制定されて、自転車事業政策がさらに進んでいくことを要望したいと思います。どのようにつないでいくのか、その辺を想定しながら、都市再生整備計画は策定へ進められているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"ひいては地域の安全性が高まっていくというのは、ふだんの暮らしやすさにつながっていく、安全・安心につながっていくと。令和６年から５か年をかけて人道橋、安全・安心の方向性としては、同じ方向を向いて進んでいくです。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"意見","question":"この都市再生整備計画、その中の人道橋の新設等は、本当に地域の方々の非常に大きな期待があります。ぜひ、きちんとした形で進めて、計画の実現、できるだけ早く実現していただけるようにお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-106"},{"speaker":"若林委員","kind":"質問・要望","question":"特に医師会等、また薬剤師会、その２つの動きについて確認をさせてほしいと求めました。いわゆる医療関係団体への連絡がどのようにされるのかということの確認、また、そこについての課題があればお知らせほしいと求めました。","respondent":"山本防災課長","answer":"体制等ですが、震度５強以上の地震があった場合には、それから薬事コーディネーターが区役所のほうに自動参集するという仕組みになってあります。","id":"exchange-107"},{"speaker":"若林委員","kind":"確認","question":"今の情報通信機器が動くかどうかというところで、医師会と薬剤師会の会の中では、その情報通信機器というものがどのようになっているのか確認させてください。","respondent":"山本防災課長","answer":"医師会、薬剤師会の内部の情報通信機器というところは、これ専用のものを準備しているということは区では把握してございませんので、一般の電話等で対応するものというふうに理解をしているところです。","id":"exchange-108"},{"speaker":"若林委員","kind":"質問・要望","question":"その確認はされていないというところで、ご要望や要請をされているという中で、そういった通信手段を今模索しているのですと。緊急の課題の１つではないかなというところで、区の支援の仕方等、ご認識があればお知らせほしいと求めました。","respondent":"山本防災課長","answer":"緊急時の情報の連絡手段というところで、こちらは非常に重要だというふうに考えてあります。医師会、薬剤師会のお声を聴きながら、区の体制というところはしっかり考えていきたいです。","id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"様々な意味での区の支援をいただきながら構築していただきたいなと、このような強い要望をしますので、どうぞよろしくお願いいたします。今年の１月２２日でしたか、震度５強の地震があったときに、近年の実績や来年度の取組みについてもお知らせをほしいと求めました。","respondent":"山本防災課長、長尾建築課長","answer":"平時においても、防災課、それから健康課、保健所等と災害利用の協議等は今進めているところです。今後内部の連携だけではなくて、外部の機関との連携強化というところもしっかり進めてまいります。相談件数としましても、その中には助成に関わるご相談も１０件以上いただいておりますので、来年度もしっかりと対応していきたいと考えております。","id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"人命を守るためのがけ・擁壁、またコンクリートブロック塀の安全化についても、力強く進めていただければと要望します。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区として、東京地裁による調布市の外環道シールドトンネル掘削工事差止めの決定をどう捉えているか、伺います。この工事差止め決定が、リニア新幹線工事にどう影響するのかについても伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"東名のジャンクションから発進している２本のほうの工事が中止で、残りの５本につきましては、区は把握しています。ＪＲ東海に引き続き安全に工事していただき、また、住民の不安払拭に向けて努力していただきたいというふうに考えてあります。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"リニア新幹線の工事も、気泡を添加剤にする点で同様の工法ではないかと思うのですが、伺います。気泡で埋めるということで書かれておりますけれども、その点では同じ工法となるのではないか、説明を求めました。","respondent":"中道まちづくり立体化担当課長","answer":"それを検討いたしまして、地域の方に説明会を開いて、今回の決定では中止にならなかったというふうに認識しております。ですので、同じ気泡シールドですけれども、そうした過程を踏まえて、今現在外環道では３本の工事が開始されているです。","id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"話も聞いていただいて、つかんでいただきたいなと思うのですけれども、その点についても伺いたいと思います。品川区としては関係ないこととするのではなく、ここをしっかりと教訓として学ぶことが必要ではないかと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"今外環道の様々な対策というものを注視したり、または確認したりしながら、今後の施工にどう結びつけていくかというところを検討しています。ＪＲ東海に対して、安全に工事を計画・施工するよう、努めてまいりたいと考えています。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"土木の専門家として検証していただきたいと思うのですけれども、検証してほしいと求めましたが、いかがでしょうか。ＪＲ東海が安全と言っているので信じますということでは、区民の安全は守れないと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"その真上のボーリング調査が１か所もないですが、事前に土質の状況を調べるというところで、ボーリング調査というものを実施します。１９本、全部確認して、同じものだということは確認しています。","id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それはやっていただきながら、地域ごとの教室型説明会をぜひ区として求めてほしいと求めましたが、いかがでしょうか。町会長たちも地域ごとに、みんながやってくれと求めたということでしたけれども、それにもどう応えていくのか伺います。","respondent":"中道まちづくり立体化担当課長","answer":"調査が終わった後の説明会ですけれども、時期につきましては、まだＪＲ東海からの報告はございません。ＪＲ東海から、今までの説明会での配慮をしながら、地域ごとにオープンハウス型説明会をやっていきたいというふうに聞いてあります。","id":"exchange-116","title":"町会・自治会支援"},{"speaker":"大倉委員","kind":"提案","question":"３１１ページ、しなみちレポート、３４５ページ、防災訓練、３０９ページの自転車安全利用指導員業務委託について伺います。様々、やはり多くの方に参加してもらう訓練というところで、課題を解消していこうというご提案なのかなと思いますとの意見を述べました。","respondent":"川口交通安全担当課長、五十嵐災害対策担当課長、溝口道路課長","answer":"自転車を利用される方の交通ルールの遵守や、また利用マナーの向上、こちらを求める声が大きくなっております。指導員を配置して… 東京都でも様々な広報媒体を持っていますので、そことも連携して周知させていただきたいなと考えております。臨時バスを３本ほど… しなみちレポートの件です。そういったことが大事だと考えていますので、また、できる限りできるように調整していきたいというふうに考えているところです。","id":"exchange-117"},{"speaker":"大倉委員","kind":"質問・要望","question":"多分経年で、お話を伺うと経年で劣化していく中で揺れてくるということもあるかなと思いますが、ぜひ調整をお願いしたいと思います。雨の日はどのようにされるのか教えていただきたいということと、ぜひしていただきたいなと思いますので、その点についてご答弁をお願いします。","respondent":"川口交通安全担当課長","answer":"当然そのときには、晴れている日以上に当然慎重な運転が必要だということも、併せて指導するような形を取りたいというふうに考えているところです。","id":"exchange-118"},{"speaker":"芹澤委員","kind":"質問・要望","question":"３１７ページ、時間があれば３４９ページの防災体制整備費、伺っていきます。今把握されている範囲ですか、どれぐらいの割合が実際に感震ブレーカーを設置されているとお考えなのか、まず説明を求めました。","respondent":"山本防災課長","answer":"区では平成２８年度から設置助成を始めておりまして、今年度１月末時点で合計４７３件、助成をしています。それから割り返すと大体３.５％の普及率というところではありますが、どう把握していくかということが１つ課題だというふうに認識しています。","id":"exchange-119"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私としては、まずこの目標値を達成するまで、しっかりとエリアを絞って補助していくべきなのだろうと。今年度からですか、どういったもの、やり方について説明を求めました。","respondent":"山本防災課長","answer":"当然その地域におきましても、ソフト面での延焼防止というところの必要性はありますので、今後その対応等は考えていきたいと思っているところです。こちらを年間２回、それから区の広報紙、ホームページでの周知を行っているところです。","id":"exchange-120"},{"speaker":"芹澤委員","kind":"質問・要望","question":"これは事前に伺ったところによると、１月とか、その年度の経費の問題というものもあると思うのです。ご見解を説明を求めました。","respondent":"山本防災課長","answer":"リーフレットの配付時期ですが、今年度につきましては７月、それから１１月の２回実施したところです。確かに１１月ですと、７月に配付したばかりというところで、より多くの方に周知が行き届くようにやっていきたいというふうに考えてあります。","id":"exchange-121"},{"speaker":"芹澤委員","kind":"質問・要望","question":"次に、空き家対策についてお伺いいたします。このように活用したらどうですかというようなマッチングを始められるというふうに伺っていますが、年度でもらうのかをまず説明を求めました。","respondent":"竹田住宅課長","answer":"業者の契約形態ですが、単価契約を考えておりまして、１件提案していただいたら幾らというような形で契約していこうと考えております。新年度に入りましたら、すばらしい提案をしていただけるような業者をプロポーザル方式によって審査しまして、決定していきたいと考えています。","id":"exchange-122"},{"speaker":"芹澤委員","kind":"提案","question":"歩合制というのですか、提案ごとにとなると、そこに対してどういったお考えがあるのかお聞かせください。２０１５年から始めて、１件も活用されていないのだというようなお話があって、ご見解を説明を求めました。","respondent":"竹田住宅課長","answer":"なかなか難しいと思いますので、まずは１つの空き家に対して１つの提案をしていただいたという段階でお支払いをしたいと考えております。公共的な活用に助成をしている事業ですが、そこに結びつくように、様々な工夫をしていきたいと考えております。","id":"exchange-123"},{"speaker":"芹澤委員","kind":"質問・要望","question":"同じようなというか、大体空き家というものは同じレベルの大きさだったりするものが多いですから、それがやはり使い回しになって。最後もう１個、やはり補助を考えていくべきではないかと思っていまして、建て替えについてもぜひ補助をご検討ほしいと求めました。","respondent":"竹田住宅課長","answer":"１点目、２つとないと考えていますので、それぞれの土地の特徴に合ったご提案をしていきたいと考えています。報酬のほうも、それから建て替えについてのご提案ですけれども、こちらについては検討していきたいと考えております。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"４１年前に建てられたビルですが、品川区には、今何棟ありますか、教えてください。そして、もし分かるなら、そのうち倒壊や崩壊の可能性が高い危険度の高いビルは何棟ありますか、説明を求めました。","respondent":"長尾建築課長","answer":"もう９割ほどの耐震化が完了しておりまして、戸数でいいますと１万７,０００戸ほどが、木造住宅で耐震化が進んでいない状況になっております。そのようなカテゴリーでの調査はしておりませんので、ちょっと実態の統計値としては把握していないところとなっております。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"それこそ死傷者がたくさん出てしまう、そのようなことに関して、どのようにお考えでしょうか。なぜそちらのほうに関しては、これは２７年前にこのような事故があったら、少しでも進めておかなければいけなかったのではないか尋ねました。","respondent":"長尾建築課長","answer":"東京都のほうですけれども、事業所系のビルではないのですが、病院だったり、私立の学校であったり、そういったところに対しての支援もしております。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"そのぐらい、私は区で責任を持って調査すべきではありませんかと思うのですが、いかがですか。これは予算は国でも何でもお願いして、きちんと予算を組んで調査すべきだと思うのですが、その辺についてもう一度ご見解を説明を求めました。","respondent":"長尾建築課長","answer":"現時点では、国や都の中で、そういった中高層の事業所系のビルに対しての耐震化の支援の補助制度といったものがない状況です。今後の課題としては検討していきたいと考えておりますが、そこの部分に注力しつつ、課題として研究していきたいと考えております。","id":"exchange-127"},{"speaker":"須貝委員","kind":"確認","question":"診断の方法だって、４１年前に建てられたビル、それは区で確認できるはずです。そのようなものを私は学者に聞いて、実際にどうなのですかと。","respondent":"長尾建築課長","answer":"非常にこう、概略の数字にはなるかと思いますが、区内の建物の状況というものは確認できるかと考えております。安全であるとか、危ないとか、そういったところはなかなか判断できないところだと考えております。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問・要望","question":"その町会、自治会もそうですが、その住民の方にある程度教えてあげるべきではないですか。２７年間、ほとんど手をつけていない状態というのは、私はいくら何でもちょっとひどいのではないですかと。","respondent":"山本防災課長","answer":"各町会ごとで様々な備蓄等、また、防災資機材の整備というものを進めているところです。地域というところが共助の要というふうに考えてありますので、引き続き各町会等の支援等をさせていただきたいというふうに考えてあります。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問・要望","question":"３４３ページの区営住宅管理費に関連して、３２９ページ、補助２９号線道路について伺います。区としても、この区営住宅の入居者に求めている連帯保証人を廃止することを求めますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"平成１８年度から、個人の連帯保証人、あるいは法人の連帯保証人を選択できる制度となっています。本制度を導入して以来、個人の連帯保証人、あるいは法人の連帯保証人をいずれも見つけられず、区営住宅への入居ができなかったケースはございません。","id":"exchange-130"},{"speaker":"のだて委員","kind":"質問","question":"やはりこうした姿勢が、区としても必要ではないかと思いますが、いかがでしょうか。区営住宅の入居に際して、連帯保証人が妨げになっていないという認識なのか、伺います。","respondent":"竹田住宅課長","answer":"それから家賃保証のほうを選ばれた方が１０名で２７％となってございまして、圧倒的に個人の連帯保証人を選んでいる方が多いという実情です。現在、区としましては、現行の制度を維持していきたいと考えております。","id":"exchange-131"},{"speaker":"のだて委員","kind":"質問・要望","question":"区営住宅、公営住宅だからこそ、こうした視点が重要だと思いますけれども、いかがでしょうか。区としては、この利用者の１万円負担も大変だと思っていないのか、伺います。","respondent":"竹田住宅課長","answer":"本制度は平成１８年度から導入して、いずれも見つけられなかったというケースはございませんので、妨げになっているとは考えてございません。それから、保証料については、必要な経費だというふうに考えてあります。","id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"この低所得者の方が生活をしていく上で、年間１万円としても、これはやはり結構大変な額になるのではないかなと。ぜひ、区としても廃止してほしいと求めましたけれども、この連帯保証人の廃止について検討したことはあるのか伺います。","respondent":"竹田住宅課長","answer":"区では、東京都の動き、国の動き等を見まして、常に現行制度が適切かどうかということは検討しています。検討の結果、現在は連帯保証人は必要という結論になっているところです。","id":"exchange-133"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域住民が提訴した、補助２９号線の事業認可取消しを求める裁判は、５月にいよいよ判決となる大詰めとなっています。伺います。","respondent":"鈴木都市計画課長","answer":"委員にご紹介いただいた詳細のところは、私当時は担当をしておりませんでしたが、認識していなかったというところだと思います。都のほうにも確認する機会というか、そうした機会もなかったのではないかです。","id":"exchange-134"},{"speaker":"のだて委員","kind":"質問","question":"区も知らなかったというところで、専門家の知見を踏まえずに、区内、２９号線は３.５km、３.５kmにわたって住民の生活を壊す道路を進めるということは問題だと思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"実際に阪神・淡路大震災では、広幅員の道路が焼け止まり、燃え広がることがなかったという事実も発生しています。延焼遮断帯というものは防災性の効果が非常に高いという認識のもとで、都と連携して、木密地域の防災性の向上を今積極的に行っているです。","id":"exchange-135"},{"speaker":"のだて委員","kind":"確認","question":"専門家の意見を聞かずにやっていた、この延焼遮断帯構想ですから、その防災性についても疑問が生じるところです。シミュレーションについてもお話がありましたけれども、都議会では、地域全体の安全性を確認したものでもないということが明らかです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"大沢委員","kind":"質問","question":"品川区国民保護計画、それと３１１ページ、時間があったらシェアサイクル事業について伺いたいと思います。もう一度考える１つのツールとして、私は今日この質問をさせていただきたく、質問項目に挙げさせていただきました。","respondent":"五十嵐災害対策担当課長","answer":"区市町村などが相互に協力し、文民の立場において、住民の避難や救援措置等を行うことをいいます。なお、武力攻撃事態等における国民の保護のための措置に関する法律、通称国民保護法により、具体的な措置が規定されております。","id":"exchange-137"},{"speaker":"大沢委員","kind":"質問","question":"その中で自治体などが実施する国民保護というか、保護措置というものは、これも具体的に何を指すのか教えてください。今度品川区に移ります。","respondent":"五十嵐災害対策担当課長","answer":"国民保護措置には５つございまして、そのうちの１つ、実際に避難する住民の誘導などを行います。区は、都の実施する救援措置に協力するとともに、その一部を実施することになります。","id":"exchange-138","title":"町会・自治会支援"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、ここで今都ということ、東京都と品川区の実際の役割の違いというものがあると思うのですけれども、そこのところはどうなっているのか説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"２つ目の住民避難の救援に関する措置につきましては、救援に関する措置の実施主体となって、そして医療提供などを行っております。その他３つの措置がありますが、都は広範囲にわたる応急措置の実施や、区は具体的な区民などに対する措置を実施することとなります。","id":"exchange-139"},{"speaker":"大沢委員","kind":"質問","question":"では、国民保護に関わる事態が発生した場合、区はどのような体制で臨まれるのか。はっきりとした情報というか、はっきりとした知識がないものですから、そこのところを明確に、答えるよう求めました。","respondent":"五十嵐災害対策担当課長","answer":"国が武力攻撃事態や緊急対処事態に係る事態の認定を実施するまでの間は、そして災害対策本部体制において、当面の処置を実施する体制を確立します。なお、国民保護対策本部および緊急対処事態対策本部の体制は、実態として災害対策本部に準ずる体制で対応することとなります。","id":"exchange-140"},{"speaker":"大沢委員","kind":"質問","question":"そもそも災害とやはり有事というものは別なように感じるのですが、そこのところは１つの組織でしっかりと対応できるのでしょうか。、答えるよう求めました。","respondent":"五十嵐災害対策担当課長","answer":"体制の件でさらにお尋ねです。国民保護計画で実施する、避難者の生活の支援、災害時の対応とほぼ同一の対応になるからです。","id":"exchange-141"},{"speaker":"大沢委員","kind":"確認","question":"ほぼ同一の対応、それでももう１回確認しますけれども、同一の対応で十分組織として機能するわけですね。","respondent":"五十嵐災害対策担当課長","answer":"そのように理解しております。","id":"exchange-142"},{"speaker":"大沢委員","kind":"質問・要望","question":"有事、これはもういとまがないわけですから、そこのところはスムーズにしっかりと組織が進むようにやっていただきたいと考えています。ましてや私たちの生命、財産を守る重要なことですので、そこのところはしっかりと断言できるぐらいの答弁をほしいと求めました。","respondent":"滝澤災害対策担当部長","answer":"生活支援、災害の復旧に関することは、全く災害対策本部と同一です。他自治体からの避難民の受入れというような業務が追加されますので、そのようなときは柔軟に組織を拡充して対応していきたいと思います。","id":"exchange-143"},{"speaker":"大沢委員","kind":"質問","question":"近くに行けば、川崎にも火力発電所があります。そこのところは想定をされていて、それに対する対処の方法、危機感というものは持たれているのか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"大井火力発電所に関するお尋ねです。重要施設である大井火力発電所が攻撃された場合の措置についても規定されております。","id":"exchange-144"},{"speaker":"大沢委員","kind":"質問","question":"規定をされている、規定はされているのだ、今聞いて分かる。どのように規定されているのか、簡単でいいから説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"事態が発生した場合に対処するためのパターンを６パターン、品川区では用意しております。それに応じて対応しています。","id":"exchange-145"},{"speaker":"大沢委員","kind":"質問","question":"細かいことは、機密に関することなのでこれ以上は伺いません。私今手元にあるのが、ホームページには平成１９年のものが載っていたりして、この令和２年の最新版というものはいかがなっているのか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"申し訳ございません。確認して修正したいと思います。","id":"exchange-146"},{"speaker":"大沢委員","kind":"質問","question":"載っていないのです。なるべくなら速やかに、お手隙などと言ったらちょっと表現が悪くなりますけれども、なるべく早急に変えていただくことを望んで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"塚本委員","kind":"質問","question":"先ほど大倉委員のほうからもちょっと質問がありましたけれども、復旧するというのですか、ご相談をいただくことがあります。そうすれば、そこのところというのはどうなのでしょうかということをお伺いしたいと思います。","respondent":"稲田土木管理課長","answer":"年に４回、この間は１２月８日にやりまして、そのような注意喚起を行っているです。引き続き、そのようなところを、各企業徹底してやってもらうようにしたいと思います。","id":"exchange-148"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、きちんとやってもらえればしっかり戻るのだという、このような認識でよろしいのか尋ねました。","respondent":"稲田土木管理課長","answer":"そのようなことをしっかりやってもらえれば、きちんといくと思います。そのようなところを指導していきたいと思います。","id":"exchange-149"},{"speaker":"塚本委員","kind":"質問","question":"次に３４９ページ、この冬、老朽木造住宅の火事が大変多く発生しているというように感じております。本当に木密地域等で起こっているのですけれども、特に荏原地域の老朽木造住宅での火災の発生状況、そして主な出火原因等について説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"第２位、第３位の火災原因は品川区と同じですので、品川区の傾向としては、電気火災が多いことが特徴と言えます。不具合がある家電製品は使用を控える、差しっ放しの電気コードはコンセントから抜いて、変形などがないかチェックするなどの対策が必要と思われます。","id":"exchange-150"},{"speaker":"塚本委員","kind":"質問","question":"今対策というものもちょっとお伺いしましたけれども、電圧がかかり過ぎるのか、少し値段は高いですけれども。そういった器具等の活用によって、もう一重の漏電火災等の対策強化、考えられることについてお伺いいたします。","respondent":"五十嵐災害対策担当課長","answer":"現在様々な電気火災に対応する器具等が、出回っている状況です。やはり生き物と同じように、どこか不具合が出ている場合もありますので、火災に至る場合があるということになります。","id":"exchange-151"},{"speaker":"塚本委員","kind":"質問・要望","question":"そのようなことを受けての質問をちょっと平成２８年に取り上げて、平成３０年に、支援物資受援体制再構築ということをやっていただきました。こういったものがそれぞれうまく連携してというのですか、輸送されるというようなことについて、ちょっと確認をさせていただきたいのですけれども。","respondent":"平原防災体制整備担当課長","answer":"令和４年度から行う予定となっておりますが、平成３０年に品川区が行いました支援物資の再構築、そこから配送するというものが一つあります。次年度の事業ではそれを一体化して、災害時にそれを転用して、災害時にも輸送する体制を強化するというようなことを前提とした事業です。","id":"exchange-152"},{"speaker":"塚本委員","kind":"質問・要望","question":"しっかりと災害時に、求めるところに求める量を届けられるというようなことで、体制を組んでいただけるということでよろしくお願いしたいと思います。簡単に確認をさせていただきたいと思うのですけれども、生物、戦略策定というものはそのようなものなのかというところでの確認をお願いいたします。","respondent":"高梨公園課長","answer":"来年度の調査の中で、区民への意識調査等も考えてあります。区民の方々がどういったことを考えているのか、そういったところを把握しながら考えていきたいと、このように考えております。","id":"exchange-153"},{"speaker":"塚本委員","kind":"意見","question":"ぜひ、そういった区民のいろいろな活動もきっとあるのではないかと思いますので、そういった際にはしっかり対応できるような形でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-154"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私からは、最初に公園管理というか、公園について、みなとが丘ふ頭公園について伺いたいと考えています。使いたいなと思っているのですが、それは前にもお話ししたから、その状況がどのような状況なのかということを教えていただきたい。","respondent":"高梨公園課長","answer":"まとまった面積を有しておりまして、スポーツ施設等を設置する公園としては非常に適性がある、魅力的な公園であると思っているところです。","id":"exchange-155"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはどうしてそのようなことを言うかというと、もう１回それをどこかで、品川のこちらのほうでは海に面しているところがないわけです。品川区は海に面したところをそれぐらい、ぜひそのような気合でチャレンジをしていただきたいと思うのだけれども、ぜひその辺の見解を説明を求めました。","respondent":"高梨公園課長","answer":"現在は、先ほど申し上げたような東京都の見解ではありますけれども、一部利用も含めた、今後のみなとが丘ふ頭公園の区利用の可能性については、積極的にというか、継続して東京都とは協議してまいりたい、このように考えております。","id":"exchange-156"},{"speaker":"石田（秀）委員","kind":"提案","question":"様々そのようないろいろな提案をしていくし、地域の中でそのような提案が、人気があるというのです。ぜひこのようなことをいろいろ考えていただいて、そのようなことができないかなと思うのですが、その辺の見解をとの意見を述べました。","respondent":"栗原河川下水道課長","answer":"それから舟運事業者、港湾局、それから海上保安庁などと検討を進めてまいりたいと考えています。引き続き地域の皆様と、どういったイベントをすることで水辺をにぎわすことができるかということは、しっかりと検討してまいりたいと考えています。","id":"exchange-157"},{"speaker":"石田（秀）委員","kind":"提案","question":"それで提案はいいのですけれども、私は代表質問でもやったのですが、そのプロポーザルで選択をするときに、補助金の話を入れてほしい。ただ提案してくださいといろいろなお願いをするよりは、まず、そこから提案したほうがいいということは代表質問でもやったのだけれどもとの意見を述べました。","respondent":"竹田住宅課長","answer":"そういったものを活用できるように、事業採用の検討をしていきたいと考えております。様々な方がいらっしゃいますので、いろいろなタイプの方にご提案しまして、１件でも多くの空き家が解消するように努力してまいりたいと思います。","id":"exchange-158"},{"speaker":"石田（秀）委員","kind":"意見","question":"今の話は住宅課だけではなくて、障害者福祉課とか、いろいろなところで建て替えをしてくれてもいいわけです。そのようなものの事業から入っていくということも必ず必要だと思いますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-159","title":"町会・自治会支援"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":131726,"voices":371}},{"id":"r04-20220314-3","meetingId":"r04-c-budget","date":"2022年3月14日","dateIso":"2022-03-14","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"芹澤委員","kind":"提案","question":"私からは、３６７ページの電子図書館、あとは３５３ページ、文化財保存活用事業、３６１ページの地域の歴史・文化学習についてお伺いいたします。この電子書籍の貸出しについて評価をお伺いしたいと思いますとの意見を述べました。","respondent":"吉田品川図書館長","answer":"それで、今のところ毎月、貸出し数などは、大体５００件程度のところを推移しているようなところで進んでおります。利用者の声としましては、便利であるという意見もあるところで、まだコンテンツが少ないというような評価も受けているところです。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問・要望","question":"そもそも電子書籍化されていないものもたくさんあるかと思いますので、ここは見極めながら、ぜひ活用を進めてほしいと求めました。区立図書館と同じシステムにできるのか分かりませんが、学校図書館に対してのデジタル図書・電子書籍の導入について、ご見解を説明を求めました。","respondent":"吉田品川図書館長","answer":"校内におけるインフラ、ネット環境につきましては、十分整備されていると認識しているところです。端末を見る、それからデジタル教科書などとの兼ね合い、この辺の区のスタンス等の対応についても考慮すべき関係があると思います。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"こちらもデジタル化について伺いますが、予算プレス発表の中で、地域資料のデジタル化が予算化されているかと思います。予算をつけていただきたいと思っていまして、ぜひ保存するというのに予算をつけてほしいと求めましたが、ご見解を説明を求めました。","respondent":"有馬庶務課長","answer":"いわゆるスライドで保存しているものが非常に多いということで、最近、認定したような文化財はほんの少しだけデジタル化ということになっております。内部でも検討し始めたところですので、そのような方向で、また今後検討していきたいと考えております。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"確認","question":"どうやって写真に残すのか、ぜひそこは、どこをデジタル化していこうかというのは確認してほしいと求めました。ご見解を説明を求めました。","respondent":"有馬庶務課長","answer":"その中では、ためる、つなぐ、いかすというような視点で文化財の活用をしていきましょうということがあります。しっかり伝承していかなければいけないと考えておりまして、また今後、全体的にどうしていくかということも検討していきたいと考えております。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問・要望","question":"続きまして、地域の歴史・文化学習についてお伺いします。お伝えを様々されていらっしゃるかと思いますが、この文化・伝統を教育していくというところの意義を、まずお聞かせほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"その場合、知識だけではなくて様々な体験活動を通しながら認識を深めていく。そういった、日本人としての大切な学習だと認識しております。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問","question":"手紙についてお伺いしたいと思います。やられていない学校もあるかと思うのですが、まず内容と、あとどれぐらいの学校が手紙の文化振興に取り組んでいらっしゃるのかを説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"主に７月・１２月に実施しまして、暑中見舞い、また年賀状を書いて、実践的に取り組んでおります。まだ、今後予定している学校もありますので、再度周知してまいりたいと考えております。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問・要望","question":"買わずに、「こういうふうに書くんだよ」と、やり方だけ教えているところもあると伺っています。お金がかからず出せるというような、教育委員会で統一的な後押しをしてほしいと求めましたが、ご見解を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"手紙やはがきの指導は大変重要なことだと捉えております。まだ予定している学校もありますし、無料で２枚、さらに推進していきたいと考えています。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"３６５ページ、３６５ページ、学校地域連携推進経費に関連いたしまして校則についてお伺いいたします。多様な性を認め合うことを学ぶ機会が持たれていることと思いますが、さらなる理解促進のため、今後の展開を伺います。","respondent":"矢部教育総合支援センター長","answer":"人権のポスター等でも、子どもの作品から、ジェンダーに関わる内容も出てきてありますし、学校も、制服の男女差のないよう、配慮はあります。様々な人と多様な関わりをした中で成果が出てきていると思いますので、ますますこちらを推進してまいりたいと考えております。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"今、中学校の公民科の授業で行っているとのご答弁を頂きました。小学生や、また保護者に対しては、どのようなことが行われていますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"トイレの活用などで個別に対応する場面がありますので、学校の中で共有するということで、個別に話をする場合はあります。全体への話につきましては、小学生は、発達段階に応じて、いろいろな人がいるのだということを理解させる内容になってあります。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区行動計画推進会議の提言については、どのように受け止めていらっしゃいますでしょうか。併せて、現在、学校トイレやプールなどの更衣室、健康診断を受ける際の配慮についてどのようにされているのか伺います。","respondent":"矢部教育総合支援センター長","answer":"各学校が子どもたちにアンケートを取ったり、生徒会で話し合ったり、または地域や保護者の意見を聞いて進めている学校があります。それぞれ各学校で、今、ジェンダーに関わる配慮をしています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"２０２０年３月の予算特別委員会の総括質疑でも、「馬とのふれあい事業」を取り上げて推進を要望してまいりました。その後どのような検討をされたのか、お伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"「馬とのふれあい事業」につきましては、今年度、コロナ禍ではありますが、７校が実施しております。今後も、子どもたちの様子を指導主事が見に行っておりますが、大学の先生にもよくお話を聞いて、効果的な活用をさらに進めてまいりたいです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"新年度もぜひ継続して、お願いしたいと思います。もう一歩深い、この事業の強化を図っていただきたいと思うのですが、ご見解をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"効果の検証をして、それから次に、どうやったら子どもたちにさらにいい教育ができるかという活動を検討してまいりたいと考えています。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"続きまして、がん教育推進授業、がん教育についてお伺いいたします。品川区におけるがん教育の目的を改めてお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"今後、自らの生活習慣を特に中心に見つめ直しながら、長く自分の体と健康を守っていくために必要な教育だと認識しております。時間は僅かですが、そのきっかけとなる５０分間と考えております。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"４月より定期接種としての積極的勧奨が再開されることになりましたが、教育現場ではどのように子どもたちに伝えていくことができるのでしょうか。お伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"昨年は８年・９年と、両方を指導したところです。３学期の指導ですので１月の第１校目、１月末の学校から、ＨＰＶワクチンのパンフレットの内容の範囲で周知したところです。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"少し時間がありますので、校則について伺います。中学校３年生、９年生が、お伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"子どもたちの声につきましては、生徒会での内容や、あとアンケートを取ったりということで、少しずつ進んです。学校によって差はありますけれども、さらに子どもたちの声を反映できるような形を推進してまいりたいと考えています。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、教職員人材育成経費についてお伺いいたします。学校保健と保健所が連携しながら進めていただきたいのですが、小・中学校における現在の取組の状況と、教育委員会のご見解をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"そのようなことに対応できるよう、相談の実施方法や医療機関との連携、受診支援に向けた取組のことと理解しております。必要であれば教育総合支援センターの教育相談室、また、かかりつけの医者の相談も可能であるのではないかと考えております。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"部活動での外部講師としてプロスポーツのチームや選手に指導に来ていただくというようなことをお願いしたいと要望いたしますが。一般質問の再質問におきまして、運動習慣の継続についてお伺いいたしました。","respondent":"矢部教育総合支援センター長","answer":"体育科の校長が検討するということで連絡が入っておりますので、子どもたちにできることが何かを考えて、地域との連携を図ってまいります。学校ではポスターを掲示したり、または自由に子どもたちが取れる場所に置いたりして、周知を図っているところです。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目に、市民科・各教科充実経費についてお伺いいたします。能力と適性、やりたいことと好きなことというのが違う児童・生徒がいる場合には、どのような指導を行っているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"２点目の、そして、私たちができそうな階段を用意するということかと思います。そのようなことで、少しずつステップを上げて、子どもたちにできる限りの目標設定と実現をかなえていきたいというのがスタンスです。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"専門的働きかけを行っており、個別的・専門的な働きかけの中で、子どもたちの才能の芽を生み出すということもあります。家庭復帰した子どもたちの才能を伸ばすための環境を、学校全体で整えていただきたいと要望いたしますが、教育委員会はどのようにお考えか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"子どもたちが活躍する場は学校だけではございませんので、様々な機関との連携は必要かと存じます。要保護児童の連携の協議に出たり、または関係課であれば自殺防止対策委員会に出たり、今後とも努めてまいりたいと考えております。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは要望だけになるのですけれども、小学生が３３.３％、中学生が３５.３％増加しています。４点目に、教材教具等経費についてお伺いいたします。","respondent":"工藤指導課長","answer":"必要性等に応じながら、まさに教育課程の実現に向けた協議については、学校事務も参画しながら行っているところです。そういったことを、私ども教育委員会としても、学校という組織を全教職員でどうマネジメントするかというのは引き続き校長等に指導してまいります。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"３５５ページ、就学援助費、３５７ページ、生徒指導対策等経費について、新入学学用品入学前支給と、中学校の校則について伺いたいと思います。今年４月の小学校１年生・中学校１年生も引上げの対象に加えてほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"こちらの金額の変更ですけれども、数年に１度、状況を見まして、金額の精査を行っているところです。令和３年度中に、４月以降、令和５年度入学の方と考えています。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"プレス発表は今年の２月ですけれども、この引上げが必要だと考えた時期はいつ頃なのか、伺いたいと思います。今年の予算で引き上げるわけですから、今年の小学校１年生・中学校１年生も対象に加えることは、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"予算の金額を引き上げる時期ですけれども、こちらは来年度、令和４年度予算を編成する過程の中で検討し、予算要求したものです。令和２年度にご審議いただいて、令和３年度に執行する金額をお認めいただいておりますので、そのとおり執行しているものです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"同時に、女子生徒やその親に話を聞くと、スカートとズボンのどちらがよいかと聞くと、どちらも身につけたいとの声も伺います。希望に合わせて両方を選ぶことができるように、就学援助の金額を引き上げてほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"こういった、それぞれ今ご紹介いただいたような事情に関しまして、支出の多い・少ないに関しては様々なご事情があると考えています。１つの理由で、１つのものについて金額をアップするということは考えてございません。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"１つの理由で金額アップは考えていないというご答弁の意味がよく分からないのです。どちらか選べるようになったわけですから、とても教育的ではないと思いますが、改めていかがか尋ねました。","respondent":"勝亦学務課長","answer":"多様な考え方や価値観、感覚は、当然尊重されるべきものだと考えていますけれども、あくまでこういったものは、ある程度、自由意思や選択によるものかと考えますので、経済的な支援をここに関してのみ行うということには当たらないと考えております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"多様な価値観を尊重するのであれば、なぜ金額の引上げができないのか、改めてその理由を伺いたいと思います。改めてこの点はいかがか尋ねました。","respondent":"勝亦学務課長","answer":"例えば今頂きました性自認の問題ですけれども、性自認は当然、尊重されるべきものだと考えますけれども、１つの個性や特性になろうかと思います。そちらの性自認に関してのみ経済的な支援をするという部分については、平等の観点からも当たらないかと考えているところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひその主体性を大事にしていただきたいと、強く要望したいと思います。教育長より、ツーブロック禁止の禁止が全校で進むように働きかけてほしいと求めましたが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"校則だけではなく、時代の流れからも多様性を認めていく時代だということは、学校にもこれから共有していきたいと考えております。実態によっても違いますので、これからも見直しは働きかけてまいりますが、しばらくお待ちいただきたいと思います。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"様々な講師をお招きしますけれども、その各講師の授業を受けたい児童・生徒は、ある程度、本人の要望や希望はかなうのでしょうか。以上、お伺いします。","respondent":"工藤指導課長","answer":"当日につきましても、また児童・生徒は興味のある講師の方を選びながら、できるだけたくさんの方々からお話を聞くことができるようにしています。","id":"exchange-027"},{"speaker":"くにば委員","kind":"提案","question":"本日私が提案するのは、しながわドリームジョブの講師としてのＹｏｕＴｕｂｅｒの起用です。児童・生徒たちの過去の要望アンケートでＹｏｕＴｕｂｅｒが入っていたことはあったのか、その点を説明を求めました。","respondent":"工藤指導課長","answer":"講師として、児童・生徒のアンケートの中には、やはりＹｏｕＴｕｂｅｒというものもあったという学校があることは認識しています。それだけに特化していることではないですけれども、やはりマッチングがうまくいけば講師としてお呼びすることもあるというところではあります。","id":"exchange-028"},{"speaker":"くにば委員","kind":"意見","question":"話題のネタとして、私としては募集してくる方はいらっしゃると思いますし、ＹｏｕＴｕｂｅｒの方々にとってもニーズはあると思います。そのような様々な募集方法などを活用し、ＹｏｕＴｕｂｅｒを募集することは可能だと思いますけれども、ぜひ、その点、ご見解を説明を求めました。","respondent":"工藤指導課長","answer":"やはり学校地域コーディネーターが横の連携をして、地域を越えて、もちろん依頼しているという状況もあります。可能性を育む上では非常に重要であると考えていますので、またコミュニティ・スクールと教育委員会と連携しながら研究してまいりたいと考えています。","id":"exchange-029"},{"speaker":"くにば委員","kind":"意見","question":"２００９年頃からインターネットで例えば生放送をしたり、このような憧れの職業になるというのは、想像もしていなかったと思います。しながわドリームジョブの講師へのＹｏｕＴｕｂｅｒの起用の可能性等について、説明を求めました。","respondent":"工藤指導課長","answer":"もちろん、そのようなことは私どもも認識していますので、やはりそういう意味では様々な職業について知るというのは大事だと考えています。今後とも様々な職業の方にコンタクトを取り、マッチングをしながら、引き続きこの取組は充実させていきたいと考えています。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問","question":"現在の各学校の行事で撮影した写真の児童・生徒への販売や配布方法はどのようにしていますでしょうか。紙焼き写真やデータは両方ともニーズがあるとは思いますが、これら様々なニーズに応えるために、学校としてどのように配布していますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"写真業者も、これまでの紙で配って掲示してそれを選ぶ手法をやめて、別にデータでの提供を始めているところです。保護者がそれぞれ閲覧して、購入した写真は後日、紙の写真として送られてくるです。","id":"exchange-031"},{"speaker":"くにば委員","kind":"質問","question":"今初めて伺いましたけれども、写真のデータ販売のサイトを使っている。そのような形で、デジタルデータで配布、そのような実施が可能ということを踏まえまして、卒業アルバムのデータ提供についてお伺いいたします。","respondent":"勝亦学務課長","answer":"こういった部分につきまして、ご紹介いただいたような多様なニーズや選択肢はあってもよろしいかとは考えてあります。写真データを公開するという考え方は、そういった部分に配慮しながら、様々なニーズに応えながら選択肢を増やしていけるように考えております。","id":"exchange-032"},{"speaker":"くにば委員","kind":"意見","question":"そのプライバシーという部分、先ほどのデジタルデータでの写真の販売というか、そのようなものが可能なのであればクリアできる問題かと思いますので、ぜひともご検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちへの影響を考え、区教育委員会として、ゲノム編集トマト苗の無償提供を受けないでほしいと強く求めますが、見解を伺います。ゲノム編集食品に関しても使用しないこと、可能な限り避けることを追加してほしいと強く求めますが、見解を伺います。","respondent":"勝亦学務課長","answer":"現時点で具体的なお話を頂いておりませんので、寄附の受ける・受けないについては、現段階ではお答えできかねることかと考えています。ゲノム編集食品についても同様の考え方を取れるのかと考えています。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"見解を伺います。ぜひオンライン参加もできるよう検討してほしいと求めますが、見解を伺います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"昨年度から各学校に、１人１台端末といったものが整備されてあります。Ｚｏｏｍに関しましては有料のプランということで、今、学校にアカウントを配付しています。 コロナ禍において、初めに決めている計画がどんどんずれてしまいまして、学校で各保護者に対応しているような状況です。今後、コロナが終息するなどして、安定して日程が決まりましたら、また検討させていただきたいと思います。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"現在、外部講師を招いて、子どもの権利条約や性教育を実施している学校が幾つかあると、保護者などから伺っています。性教育については、以前、区教育委員会から、東京都の性教育の手引に沿った性教育を行うと伺いました。","respondent":"矢部教育総合支援センター長","answer":"弁護士からの虐待に関わる事案も含めて様々あるのですけれども、件数までは把握できてございません。市民科や社会科等で内容を周知できるようになってありますので、特段、取り立てて全校でこども基本条例についての周知はまだしてございません。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"この助成制度について対象となるよう、区教育委員会として強く求めてほしいと要望しますが、見解を伺います。区教育委員会として各学校の騒音状況を調査していただき、助成対象が広がるよう求めてほしいと求めますが、見解を伺います。","respondent":"勝亦学務課長","answer":"今、羽田の新飛行ルート等については国が対策を行っているので、現段階ではこちらの機構で補助を行う予定ではないと聞いてあります。支援の対象となっておりますのは、図書や楽器といったものに、一校当たり２００万円頂けるという助成です。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"改めて伺います。伺います。","respondent":"勝亦学務課長","answer":"基本的には、学校名を挙げていただいておりますけれども、測定値の基準を超える学校は出ていないところです。今、お子様の声という部分がございましたけれども、それはどのような形で聞いていけるのかは研究していきたいと考えております。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"その測定結果はどこで確認することができるのでしょうか。区教育委員会で対応できる場があるのであれば、私立学校に通う子どもとその保護者も対応可能と周知してほしいと要望いたしますが、見解を伺います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"こちらは、学校の環境衛生基準というところで基準が定められてあります。結果について大きく公表しているという形ではございませんけれども、そのような形で結果報告は受けているものです。 私立のお子さんの相談についてです。教育総合支援センターでは、１８歳まで対応していますので、そのような内容でございましたら教育総合支援センターの所管です。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"保護者などからは、騒音の問題について、きちんと測ってほしい、計測してほしいといった要望も届いております。ぜひ、そのところについて伺いたいのですが、いかがか尋ねました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"騒音測定の結果公表についてです。こちらは法令に基づいて実施しているものですので、今後、どのように区民の方にお伝えしていけるか、検討してまいりたいと思います。 私立のホームページです。内容を確認しまして検討します。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問","question":"私からは、３５９ページの上から８行目、学校支援費の中からの質問をいたします。いじめに対しての話し合う会だと考えていますが、何がどう違うのか、そこを説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"今年度は２回行いました。委員は５名でございまして、それぞれ学識、経験、法律、心理、福祉の方々をお招きして協議しております。","id":"exchange-041"},{"speaker":"木村委員","kind":"質問・要望","question":"理事者の皆さんも、いじめというものを減らすことはできても、なくすことは、無理ではなくても大変難しいと思われているのではありませんでしょうか。実際に接していませんので、どのようないじめがあるのか、現在のいじめについて軽くお知らせください。","respondent":"矢部教育総合支援センター長","answer":"誹謗中傷、仲間外れなど、またＳＮＳによるものなどの項目があります。","id":"exchange-042"},{"speaker":"木村委員","kind":"意見","question":"私はいじめの根絶は無理でも、減らすことには可能性があるようにも思います。今の学校のいじめに対する対策というものが、どのようにあるのか、もう一度説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"年間３回、子どもたちから生活アンケートを取っておりますし、またはＨＥＡＲＴＳの支援もしております。子どもたちが自分たちで、いじめに遭っている子どもたちの相談に乗ろうというようなチームをつくって対応しているところもあります。","id":"exchange-043"},{"speaker":"木村委員","kind":"意見","question":"かといって、それを見て見ぬふりもできませんし、何らかの対策が必要であります。東京２３区が１つになって、同じ対策で、子どものいじめ問題というものは進んでいるのかどうか、これも説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"タブレットのなかった時代は０件だったのですが、今年はもう１７件まで行っていまして、子どもたちの様々なツールとして利用されております。学校のいじめを察知するアンテナも高くなってきたと認識しております。","id":"exchange-044"},{"speaker":"木村委員","kind":"質問","question":"これは先ほど言いましたけれども、東京２３区、横並びで同じようないじめ対策というのでしょうか、そういうことが行われているのかどうか、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"失礼いたしました。品川区は、特に私は他の自治体にもおりましたけれども、特に強力に強化して、いじめ対策を進めていると認識しております。","id":"exchange-045"},{"speaker":"木村委員","kind":"意見","question":"厳しい社会に出るためにも、学問とともに、長い人生の１ページ、やはり強い心を身につけることができると私は思っています。間違った考えでしたら、前もって謝りをいたしますけれども、その点についてお考えを説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"本区におきましては、９年間で困難に負けず生き抜く力を持つことを重点の一つとして教育を進めております。時には相談したり協力したりすることも含めて、自己肯定感が高まるようにして、心を強くしてまいりたいと思います。","id":"exchange-046"},{"speaker":"木村委員","kind":"質問・要望","question":"次に、３６１ページの市民科・各教科充実経費の中の、マナーキッズ教室からの質問です。これからの子どもたちには、現在の厳しい社会を生き抜くためには、どのようなことが求められているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"現在は世界中で、コロナ対応や自然災害、国際紛争などが大きな問題となっております。品川区で学んだ市民科や英語を中心とした学びを活かしまして、他者と協力して持続可能な社会を築いていただきたいと願っております。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問・要望","question":"そこで伺いたいのですが、入学前の希望申請関係書類を各ご家庭にお送りする際、校区外部評価についても触れられているのでしょうか。資料を充実させるという観点から、きっちり校区外部評価についても周知してほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"こちらの中で、各学校一校一校について紹介してございまして、ホームページや学校の特色、教育目標などを紹介しています。学校だより等々、そういった学校案内からホームページを見ていただくと、そういった広い情報にはたどり着けるものかと考えています。","id":"exchange-048"},{"speaker":"松本委員","kind":"質問・要望","question":"これはやはり、各学校のホームページのトップページに、しっかりと「学校評価」という記載をしてほしいと求めました。その点を、できれば周知してほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"いろいろな学校を比較するに当たって、それぞれの学校独自の項目や表現がばらつきますと、比較検討する際に非常に見にくいものになるかと考えます。そういった意味では、分かりやすいホームページの、統一感を持った伝え方、表現の仕方等、努めてまいりたいと考えております。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問・要望","question":"やはり、できるだけ選択する際の情報をしっかりとご提供していただくように要望いたしまして、次の質問に移りたいと思います。この移転によって、まだ１年たっていないのですけれども、貸出し数に変化はありましたか尋ねました。","respondent":"吉田品川図書館長","answer":"昨年の７月に移転しました関係で、８月分の貸出し数の比較をいたしたところです。２０２０年８月は８,１４４点、２０２１年の８月は８,４８３点という形で、移転したことによって全体的に伸びている状況です。","id":"exchange-050"},{"speaker":"松本委員","kind":"質問・要望","question":"晴海のほうですか、また新設されると伺っていて、全国的には図書館が増えていると伺っております。かなり大きな要望になりますけれども、ご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"吉田品川図書館長","answer":"大体歩いて１０分程度で行けるところに図書館を整備できればというところで、今のところ、昭和の時代から進めてきたところです。施設をまた新しく造るということについては、なかなかすぐには対応できないところもありますので、今後研究してまいろうと思います。","id":"exchange-051"},{"speaker":"松本委員","kind":"質問","question":"それで、例えば小山台からすると、図書館はすごく遠くて、実は近くに、目黒区なのですけれども、目黒本町図書館は逆に数分なのです。こういった周辺区との連携を、特別区でも考えてもいいのではないかと思いますが、ご見解を伺います。","respondent":"吉田品川図書館長","answer":"現在、区同士の連携というのはないのですけれども、都の図書館を通しまして、蔵書のやり取り、貸し借りのほうは進めているところです。","id":"exchange-052"},{"speaker":"西村委員","kind":"質問","question":"３６３ページ、マイスクール運営費から、不登校について伺ってまいります。２月、ある区内の中学３年生のクラスでは、コロナの影響で、生徒数がクラスの半分、場合によっては３分の１程度になる日もあったと伺っています。","respondent":"矢部教育総合支援センター長","answer":"基本的には学校で対応していると理解しておりますが、顔を見せ合ったりすること、お話ししたりすることまではできていると聞いてあります。様々、お子さんや家庭によって、対応を変えているところです。","id":"exchange-053"},{"speaker":"西村委員","kind":"質問","question":"家庭のみと、様々いらっしゃると思いますが、この中でも活動がメインのマイスクール八潮を希望される保護者・児童・生徒が多いように思っています。行きやすさがあるのかと考えていますが、マイスクール八潮が人気の理由、教育総合支援センターの所感を伺います。","respondent":"矢部教育総合支援センター長","answer":"マイスクール八潮は小・中学生を対象としているところに大きな特徴がありますし、委員ご指摘のとおり、活動メイン、学習も授業も行いますけれども、行事やスポーツ、音楽といった、子どもたちが実際に表現する活動が多くなっているところも人気かと理解しています。","id":"exchange-054"},{"speaker":"西村委員","kind":"提案","question":"ご提案ですが、社会的自立の支援ときっかけづくりのために、マイスクール八潮のオンライン版のような実施ができないかと考えています。フリースクールなど、民間施設やＮＰＯなどと積極的に連携し、多様な教育機会を確保できないか、ご提案させてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"ほかの人材の活用ですが、地域の方ですとか専門家ですとか、マイスクールにもぜひ連携して進めてまいりたいと考えております。ただ、敏感なお子さんたちも保護者も多いので、その辺りは十分、周知、理解していただいて進めていく予定になります。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問・要望","question":"保護者の方に様々伺いますと、子どもの不登校をきっかけに仕事を辞めるというお母さんもいらっしゃいました。不登校の児童・生徒にどのような家庭学習のサポートをしているのか、現状と、感じておられる課題を伺います。","respondent":"矢部教育総合支援センター長","answer":"一方で課題を感じているのは、そもそもタブレットを開くのも嫌だ、またはキーボードのローマ字入力が難しい。様々これまでも学校から家庭に案内してきたところですので、よい事例につきましては、校長会や教務主任会とも情報を共有していきたいと思っています。","id":"exchange-056"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほど申し上げた文部科学省の通知にも書かれていたことで、もう一点、お願いさせていただきたいのが、保護者支援です。保護者に対して、また保護者に寄り添った支援の充実が求められるとありまして、お感じになられていらっしゃる課題と所感を伺えたらと思います。","respondent":"矢部教育総合支援センター長","answer":"なかなか家庭への支援は、訪問もしておりますけれども、電話や通信手段を使ってのことがどうしても多くなっているようです。一部、アウトリーチということで、指導員が学校を訪問して別室をお借りして指導しているという実態があります。","id":"exchange-057"},{"speaker":"つる委員","kind":"提案","question":"８３運動経費、３７５ページ、通学安全確認業務等委託について伺っていきたいと思います。この間、様々な委員からも、市民科を通じた、命を学ぶ、命の授業等が提案等されていましたとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"生命尊重については、大変重要な教育内容であると考えております。学校や教職員からのニーズもあると思いますので、具体的なご案内を頂ければ検討させていただきたいと思います。","id":"exchange-058"},{"speaker":"つる委員","kind":"提案","question":"これは、品川区の教育相談士や子ども育成課、これは２０１９年１２月現在ですから、今の子ども家庭支援センターにつながる番号かと思うのです。教育委員会として学校に対する支援という視点では、今どういうふうになっているのか説明を求めました。","respondent":"勝亦学務課長","answer":"アカウントを１人ずつお配りしておりまして、クラウド上に個々人のデータを保存できる領域を確保しています。小学生でしたら中学校に入ってから新しい端末に落としていただく、またはご自宅でパソコンから保存していただくといった対応が取れるものです。","id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう児童・生徒に対応いただくということが、今、非常に求められているのかと思います。２０１８年１０月からはＨＳＣ、２０１９年１月からはＨＳＰのことについて、現状を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"自分の特性に気づきにくい、本人も分からないところもあるかと思いますので、保護者と相談しながら対応していくということです。様々なお子さんへの配慮については、特別支援教育を中心に、研修の中で触れていきたいと考えています。","id":"exchange-060"},{"speaker":"つる委員","kind":"意見","question":"今、最後の部分は学校側の対応ということかと思うのですが、研修については、特別支援教育の研修とご答弁いただきましたけれども、これはいわゆる普通学級といいましょうか、その担任の先生たちも当然、その研修の対象という認識でいいか、ここだけ、１点ご答弁くださいとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"若手教員を中心に、特別支援教育は、１つの単元の中に入ってありますので、多い・少ないはありますけれども、そういう中で、特別支援にかかわらず、通常の教員にも伝えていきたいと思います。","id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"３０人クラスであれば６人ぐらいはいらっしゃるというところで、ぜひこの辺りの研修の強化、また推進をお願いしたいと思います。１５秒しかないので、要望で終わりたいと思いますので、反射材のご協力を仰げるような形の声かけを求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"予算特別委員会、一般質問でも一貫して取り上げ、要望してまいりました。今回、ＨＰＶワクチンの積極的勧奨が再開されることになった今、今後のがん教育の中で、ＨＰＶワクチンはどのように取り扱われていくのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"令和２年度より、全ての中学校・義務教育学校の後期課程におきまして、がん専門医による指導を実施しております。がんの専門医による指導の中で、８年生を対象に、今般家庭に配布されるリーフレットの内容を周知いたしました。","id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"昨年の決算特別委員会での私の要望に対し、男子へのＨＰＶワクチンの啓発はしていないというのが教育委員会のご答弁でした。男女両性の基本的ながん予防の知識として共有すべきと考えますが、教育委員会の現在のご見解はいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"現時点におきましては、医学的な専門性を持って的確な指導をすることは難しいと考えております。今後も国の方針を踏まえつつ、保健所等と連携いたしまして、堅実に取組を進めてまいります。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、新型コロナウイルス感染症流行下の小・中学生の精神的支援についてお尋ねいたします。子どもの心を支え、支援する取組は、どのように現在、学校では行われているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"場所等を工夫しまして、オンラインを活用しながら、できる限り実施いたしました。子どもたちが楽しみにしている遠足や校外学習も、貸切りバスを活用するなどして実施しております。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"勇気づけ、今後の人生を生きていく上で、コロナ禍は大きな教育の機会として活かしていくことはできないのでしょうか。教育委員会のお考えを伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"コロナ禍におきまして、教育活動には幾つかの制約があり、思いどおりに生活ができないこともありました。さらに、タブレットが１人１台配付されたことは、新しい学習方法や主体的な学びを一層促進するものと考えております。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"意見","question":"子どもを励まし、支援し、勇気づけるような対応を、今後ともぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"おくの委員","kind":"質問・要望","question":"憲法第２６条、絵の具セットなどの無償化を求めますけれども、いかがでしょうか。これら学用品と同様に、教材費、修学旅行費などの無償化も求めますけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"今ご紹介がありましたように、憲法第２６条には、「義務教育は、これを無償とする」となっています。基本的には授業料の無償というのが、義務教育の無償の範囲と考えるのが適当と考えています。","id":"exchange-068"},{"speaker":"おくの委員","kind":"質問","question":"これらの費用、つまり法律に明記してある授業料と教科書以外の費用を、全て親の負担にしていて無償にしないのはなぜでしょうか。伺います。","respondent":"勝亦学務課長","answer":"無償の部分に関しましては、最高裁判所の考え方で、憲法第２６条の規定は、義務教育における授業料の不徴収の意味であると。その他一切の費用まで無償にすべく定めたものではないという考え方が示されておりまして、この考え方を踏襲するものです。","id":"exchange-069"},{"speaker":"おくの委員","kind":"質問","question":"そういう中で、品川区が、あえて有償にしている根拠は何かと、今伺ったのですけれども、その点、なぜなのでしょうか。もう一度伺います。","respondent":"勝亦学務課長","answer":"そういった、限られた、頂いた税金の中で、財政状況も踏まえて、限られた財源を有効に使うことが大事だと考えています。そういった教材費、修学旅行のお金等は支援していますので、それ以外はご負担いただくという形が適当かと考えています。","id":"exchange-070"},{"speaker":"おくの委員","kind":"質問","question":"負担をなくしていくべきではないかということで、私は無償を貫くべきではないかと申し上げているのですけれども、この点はいかがでしょうか。就学援助だけでは理由にならないと思うのですけれども、いかがか尋ねました。","respondent":"勝亦学務課長","answer":"無償化の考え方につきましては、そういった歴史的なもの、それぞれいろいろ考え方があります。自治体でも様々な考え方で無償化支援を行っているところでございまして、そういったものを踏まえて、現状の負担を頂いていると考えています。","id":"exchange-071"},{"speaker":"おくの委員","kind":"質問","question":"必要不可欠なものは無償にしない限り、無償教育ということ自体が成り立たないわけです。学用品や教材費等々についても、必要不可欠なものは無償にすべきではないかと私は思うのですけれども、その点はいかがか尋ねました。","respondent":"勝亦学務課長","answer":"教育課程の中においては必要なものかとは思いますけれども、一定程度、財産として残る部分もあるのかです。法律に定めていないから負担しないという部分の考え方ですが、１人１台ｉＰａｄを支給させていただいているようなところです。","id":"exchange-072"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、二重行政にならないように、そしてそれぞれの役割をしっかりやっていただくということでお願いしたいと考えています。今後も風評被害に配慮していただいてということでお願いしたいと思いますが、見解をまずお聞きしたいと思います。","respondent":"勝亦学務課長","answer":"放射性物質検査に関しましては、平成２３年から検査を継続してまいりました。こういった科学的根拠に基づく判断、制度的なものを広く今後も理解していただくような形で、安全安心な給食を提供していきたいと考えております。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"それから３７７ページにあります学校改築推進経費とありますけれども、今、改築の俎上に上がっていないという学校がどれだけあるのでしょうか。そして３６１ページの学校２０２０レガシー事業なのですが、なぜブラインドサッカーなのでしょうかということです。","respondent":"有馬庶務課長、工藤指導課長","answer":"できるだけこういうペースで今後も進めていきたいと考えていますので、停滞しているとは思っておりません。これまでも残りの学校を進めてきたわけですけれども、これについては… やはり対話による授業や学びが大事であると認識はしておりますが、タブレットがコミュニケーションを可能にする面というのはあると考えています。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"基金はそれだけ工夫されているわけですから、２０校あるのであれば、ご意見をお聞きします。もっと広げられないのか尋ねました。","respondent":"有馬庶務課長、工藤指導課長","answer":"学校改築の関係ですが、残りの学校も環境整備には努めております。改築の費用はかさみますので、その辺は重々検討して進めていきたいと考えております。あくまでもツールということで、必要な場面で必要に応じて使うというふうに考えておりますので、あくまでも手段であることを学校には指導しています。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"給食の放射能測定について、品川区教育委員会の基本的な考え方を幾つか確認させてほしいと求めました。必要な状況が発生すれば、必要な検査を行っていくというのが基本的な姿勢と理解しているのですが、それで間違いないか尋ねました。","respondent":"勝亦学務課長","answer":"委員がお伝えのとおりの考え方で間違っておりません。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"放射能汚染の危機は、東京電力福島第一原子力発電所だけではないという認識を共有できたかと思うのですが、もう一度確認させてください。それで、検査結果の変化についても、社会状況の一つとして注目して判断基準としていただきたいのですが、その点についていかがか尋ねました。","respondent":"勝亦学務課長","answer":"そのおそれがあるということで、１０年前、急遽始めたという経緯もあります。そういった事象で子どもたちの給食の安全といったものに関わるものがあれば、必要に応じて、様々な状況に応じて判断は必要かと考えております。","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そういう検査結果の中で、高い検査結果が出たりしたときも、社会状況の変化として捉えていただけるのか。私たちはぜひ捉えていただきたいと思うのですが、その点についても先ほど伺いましたので、改めてご答弁をお願いします。","respondent":"勝亦学務課長","answer":"別の場、機関等で放射能が検出されたときに、それを社会情勢の変化と見るかというお問合せかと思います。こちらについては、個別・具体的な事象を見た上で、総合的に判断する必要があるのかと考えております。","id":"exchange-078"},{"speaker":"吉田委員","kind":"質問","question":"ですので、いろいろな団体、別にどこか特定の団体である必要はないと思います。検査はこれからも続くと思いますので、それらもぜひ判断の基準としていただけることを強く主張して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、３６１ページのプログラミング教育についてお伺いします。どのような取組をされているのか、学校間での連携などもあるのか、お伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"小学校５年生の算数、６年生の理科、全校で取り組んでおります。このようなよい事例につきましては、教務主任会や自主校長会で共有しています。","id":"exchange-080"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それぞれ、よい取組に関しましては学校間で共有していただいて、学びにつなげていってほしいと求めました。教える側の教員については、どのような指導をされているのか、また新学習方法への負担などについて、どのように認識しているのか、お伺いします。","respondent":"矢部教育総合支援センター長","answer":"教員の研修につきましては、プログラミングの研修も行いますけれども、ロボットについては、担任がこれも指導しております。新しい教育課題に取り組む上では、将来の子どもたちのためですので、教員一人一人が頑張っていると捉えております。","id":"exchange-081"},{"speaker":"湯澤委員","kind":"質問・要望","question":"子どもが自宅で学習していても、教えてあげられない、どうしたらいいか分からないという保護者も多いと考えています。自宅学習に差がないような取組、また保護者に対しての何か取組があれば、教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"ほかのアプリ等を含めて、個人でも進めていけるものですので、有効活用されていると伺っています。さらに、学校では学校だより、またホームページによって、かなり分かりやすく、子どもたちの様子を捉えて発信しているように理解しています。","id":"exchange-082"},{"speaker":"湯澤委員","kind":"質問","question":"いずれ、個性を伸ばしていく重要なプログラミング教育において、区教育委員会では児童・生徒の学びをどういったふうに評価しているのか。それを教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"その論理的な思考は、プログラミングだけではなく、各教科、算数、数学も含めて進めているところです。発言も含め、子どもたちの説明や発表など、そのようなことを中心に評価をしています。","id":"exchange-083"},{"speaker":"湯澤委員","kind":"提案","question":"これは提案になるのですけれども、清水台小学校で、ぷよぷよのプログラミング特別授業が行われたかと思います。場合によっては将来なりたい職業といったものにもつながるかもしれませんので、専門家の活用も提案しますが、ご意見を伺いますとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"ぷよぷよをはじめ、出張していただく方とご相談した上で、実施できるところを検討していくということになるかと思います。ゲスト・ティーチャーをお呼びしたりしておりますので、学校とのニーズに合わせて、ぜひ来ていただきたいと考えております。","id":"exchange-084"},{"speaker":"湯澤委員","kind":"質問・要望","question":"マイスクールなどでも行われているのでしょうか。これを保護者へ配布やメールといったことをすることで、不安解消にもつながるのではないのかと思うのですが、ご意見を伺います。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"「教育のひろば」の冊子ですが、これにつきましては、保護者にも、生徒を通じて、世帯に届くように配布しています。そのほか、保育園や児童センターといったところにも全部配布しているという状況です。 不登校のお子さんですけれども、様々、興味関心が違いますので、実態に合わせて取り組んでまいりたいと考えています。","id":"exchange-085"},{"speaker":"こんの委員","kind":"質問","question":"３５７ページ、３６５ページ、学校地域コーディネーター経費についてお伺いしたいと思います。順不同でお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"特別支援教室などに来ている教員との連携する回、巡回相談員と学習支援員、この前の校長会でも説明したところです。一緒に学習支援員や介助員もいるところですので、日々、そのような指導に活かしています。","id":"exchange-086"},{"speaker":"こんの委員","kind":"質問・要望","question":"児童・生徒一人一人のキャリア発達を支援できるよう、個々に応じた教育環境の整備を、という要望もあります。このようなお声から、こうした当事者の方々の現場のご要望も踏まえて、今後の特別支援学級の運営においては充実を図るよう要望したいと思いますが。","respondent":"矢部教育総合支援センター長","answer":"教員のキャリアや力量アップについては、本当にどの場面においても大事なことだと考えております。特に、特別支援学級の教員にも研修会の場が何度もありますので、今のご指摘のところを踏まえた上で、研修を充実させてまいります。","id":"exchange-087"},{"speaker":"こんの委員","kind":"質問・要望","question":"現場での課題、ご要望等、用意していた時間では足りないほど大変に充実した時間となりました。１日４時間、週３日になっていると思いますけれども、勤務形態の考え方を教えてほしいと求めました。","respondent":"工藤指導課長","answer":"勤務形態は、週３日であれば４時間、週２日であれば６時間でありまして、そこで、それぞれの方が勤務形態を選択するというところでお願いしています。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"まさにそのとおりの声も伺っております。今後の勤務形態など見直すことも必要と考えられますが、区のご見解を説明を求めました。","respondent":"工藤指導課長","answer":"令和４年度には、学校支援地域本部の体制強化を含め、品川コミュニティ・スクールのさらなる推進のための検討会議を新たに立ち上げる予定です。その中で引き続き、研究・検討してまいりたいと考えています。","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問","question":"教職員人材育成経費に関連いたしまして、教職員の服務事故についてお聞きしたいと思います。近年都内でどれぐらい発生しているものなのか、残念ながら品川区でもあったと認識しておりますが、現状を説明を求めました。","respondent":"工藤指導課長","answer":"都教育委員会と区市町村教育委員会が連携して進めているところではありますが、今もって服務事故が根絶されていないという現状があります。使命感が求められておるというところ、私どもは日々、教職員に対して指導しておるところではあります。","id":"exchange-090"},{"speaker":"こんの委員","kind":"意見","question":"問題を起こした教員のみならず、不祥事は教員という１点で、もっと言えば区の教育行政の信頼にも大きな影響を及ぼすものと捉えております。服務事故の再発防止策、未然に防ぐ対策はないのか、現在品川区において何か取り組んでいる対策があればお知らせくださいとの意見を述べました。","respondent":"工藤指導課長","answer":"教員はその職責を十分に理解し、高い倫理感と規範意識をより一層高め、使命を全うすることが極めて重要であると認識しています。加えて毎月の校長連絡会で、服務事故による事例の校長への研修を行い、各学校では校長が講師となり、全教職員へ研修を実施しております。","id":"exchange-091"},{"speaker":"こんの委員","kind":"提案","question":"中には非常に特殊な性癖を有する事案も発生していますが、大抵は、どこにでもいるような人が問題を起こしているということもありました。服務事故の未然防止を、また教員の資質向上に向けた取組強化を提案いたしますが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"引き続き、繰り返し、知識だけではなく意識して行動するよう、教職員に対しては指導を徹底してまいります。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３７５ページ、学校運営費に関わってくるかと思いますけれども、学校でのコロナの検査について伺います。補正予算などでの答弁では、区内で２校しか申請していないということでしたが、現在の申請数は増えているのか、状況を伺います。","respondent":"有馬庶務課長","answer":"教職員対象の定期的な抗原定性検査の実施の状況ですが、小学校１校、中学校１校です。もう一校は中学校ですけれども、こちらは職員数で３名というようなことで、都から報告を受けているものです。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"２校の申請ということで、小・中学校での感染が広がってしまうということを防ぐためには検査が重要だと思うのですけれども、区の認識を伺います。学校での検査の申請が進まない理由は何か、伺います。","respondent":"有馬庶務課長","answer":"私どもで、今進まない理由を１つ考えているのは、多くの教員が２回目の接種を終わっているのではないかと推測しております。あるいは予約をしたという状況にあると考えておりますので、定性検査の週１回のものが進まない１つの要因ではないかと考えているところです。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"検査が、学校などで感染を広げないために重要ではないかということでお聞きしたので、そのことについてもお答えほしいと求めました。３回目のワクチン接種を実施していくというのは当然重要だと思いますけれども、密に子どもたちと過ごさなければならない、改めて伺いたいと思います。","respondent":"有馬庶務課長","answer":"今回の定性検査も、基本的には無症状の方での検査ということになっております。東京都は取り組んでおりますし、そういった意味では、最終的にはまた個人の判断というところにもよるものかと考えている次第です。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問","question":"新たなオミクロン株が出てきた中で、子どもでも発熱など、なかなか大変な症状が出るようにもなっています。やはり、検査をしっかり実施して、職員はもちろん、子どもたちの教育環境を守ることが必要だと思いますけれども、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"別に検査を拒んでいるわけではありませんので、定期的にやるかどうかというのはまた違うもので、そのときの状況によるものだと考えております。引き続き保健所等とも相談しながら進めていくものと考えております。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかり感染が拡大しないように進めていっていただきたいと思うのですが、これまで職員の方の感染者というのは何人いるのか、伺いたいと思います。少なくともオミクロン株が続いている限りは４月以降も実施すべきだと思うのですが、いかがか尋ねました。","respondent":"工藤指導課長、有馬庶務課長","answer":"教職員のコロナ感染の状況ですけれども、特にいわゆる第６波と言われている１月以降で申し上げますと、１月は３４名、２月は８８名、３月は先週末までで１４名という状況です。 定期的な抗原定性検査の４月以降の取扱いですけれども、これにつきましては、また東京都からの通知等を待ちまして判断していきたいと考えております。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区としても要望していただいて、区独自にもぜひやってほしいと求めましたけれども、いかがでしょうか。こうした行事などを実施していくためにも、１つの安心材料になるのではないかと思いますので、質問の答弁を。","respondent":"有馬庶務課長","answer":"今回の検査の結果で、まず２校という現実も踏まえながら、本当に要望があるのかどうかというところも見極めが必要かと思います。費用が一定程度かかってくるというところもありますので、その辺はまず東京都の動向を見てから判断したいと考えます。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"要望も確認してということでした。要望も実際、確認していただきたいと思うのですけれども、ぜひ検査を拡充してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"渡部委員","kind":"質問・要望","question":"ＰＴＡや保護者から要望があったことなのでしょうか」という質問に対して、一部の保護者からはというふうに、いろいろ書いてあります。もう一つ質問があって、「例えば振り分けられる土曜日授業の影響で、平日の授業が、６時間授業が７時間になったりすることはあるのでしょうか」。","respondent":"矢部教育総合支援センター長","answer":"来年度、令和４年度の土曜日につきましては回数の見直しを図りまして、第３土曜日を基本とした年８回の実施を考えております。１２月の時点では学校にも方向は説明していますし、委員のお話ですと、必要な情報についてはお伝えしなくてはいけないと考えております。","id":"exchange-100"},{"speaker":"渡部委員","kind":"質問","question":"やはり、地域に支えられてやるのがいいところではないのですか。そのためにみんな頑張っているのではないか尋ねました。","respondent":"中島教育長","answer":"これからも地域と共にある学校づくりに向けて、さらなる、また方策を考えていくべきものと捉えております。しっかりと反省して、地域との連携、信頼回復に努めてまいります。","id":"exchange-101"},{"speaker":"松澤委員","kind":"質問","question":"私からは、項目はないのですが、ハイブリッド授業というのですか。さきの決算特別委員会でも触れましたが、この現状と課題について、品川区はどう考えているか説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"そのような協力体制の中で、教員の働き方改革も含めまして、部活動を推進している事情があります。国も取り組んでいるということは承知していますので、関係課の連携と地域の連携をさせていただきまして、検討していこうと考えているところです。","id":"exchange-102"},{"speaker":"松澤委員","kind":"意見","question":"部活動に対する検討委員会といったものを立ち上げて、部活の種目に関しては、全中学生にアンケートを取る。状況の見極めを早くし、先ほど申し上げました課題の解決に向けていかなくては遅いぐらいではないかと考えますが、ご見解を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"委員がご指摘のとおり、国も推進していますので、各地の事例等の研究も含め、今ご指摘の旨、組織の中で検討していく必要は十分あると考えております。関係課と連携しながら進めていくつもりです。","id":"exchange-103"},{"speaker":"松澤委員","kind":"質問・要望","question":"区内中学生の誰もが参加できるクラブとして、ダンス、サッカー、ボッチャ、パソコン、将棋など、９種目挙げて、専門の指導員を招いております。例えばクラウドファンディング、返礼品は子どもの笑顔といった活動などもできるのではないかと思いますが、ご見解を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"渋谷区の例は他自治体の１つの事例だと考えております。品川区独自の地域に合わせたモデルというのを検討する必要があると考えております。","id":"exchange-104"},{"speaker":"松澤委員","kind":"質問","question":"指導継続を希望する先生たちともスムーズに関われる、そういった仕組みをつくれるのではないでしょうか。ご見解を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"国で教員の兼職についての通知が出ましたので、そのようなことも含めて、総合的に、どのような形で教員が関われるかというところも検討する必要はあると思います。","id":"exchange-105"},{"speaker":"松澤委員","kind":"質問","question":"コロナ禍においても、感染が広がり、各学校においてハイブリッド授業が行われていると思いますが、区内全体の現在の学校の状況を教えてください。例えばこれは、また準備期間が少ない中で急なハイブリッド型授業になったわけですが、先生たちの様子なども含めてお願いします。","respondent":"工藤指導課長","answer":"在宅している児童・生徒に配信する、いわゆるハイブリッドの授業配信というのも、各学校がそれぞれ取り組んでいるところです。このようなハイブリッド型の授業も含めまして、多くの学校で取り組んでいる、全校でできる体制にあるです。","id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"現場とオンラインの２つのチャンネルを１人の先生が見るというのは、何というのですか、目の前で見ている児童も見ないといけない。これに対して教育委員会はどのような対応をしているのか、要は先生を守るといいますか、そういった取組があるのか尋ねました。","respondent":"工藤指導課長","answer":"Ｔｅａｍｓ等でつながりますと、おうちの様子も映るということで、それは控えたいという保護者のお考えもあったりもあります。放課後にまた時間を取りまして、放課後につないで個別の対応をするというようなきめ細かい対応も、各学校が工夫して行っているところです。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"要は教育格差を埋めるとも言われる動画コンテンツの利点を活かすべきではないでしょうか。これが１点と、また子どもたちにもメリットがあるのではないかと考えますが、ご見解を説明を求めました。","respondent":"工藤指導課長","answer":"ＹｏｕＴｕｂｅ等でのＮＨＫの提供動画も確認することができますので、そういったものの課題に取り組むというような指示もしているところがあります。ＩＣＴ推進教員同士も、同じタブレット上のフォルダで共有できるような体制にして、情報共有には努めているです。","id":"exchange-108"},{"speaker":"松澤委員","kind":"質問・要望","question":"学校というのはやはりこの１年間は、学校はクラスターを起こさずに、本当に頑張っていただいていると私は思っております。だからこそ、学校がその変化に柔軟に取り組めるように、引き続き教育委員会を中心に、包括的に守りながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"私としては、そういう学習活動以外の教育活動・行事などへの活用は、令和２年度と比べてどのぐらい進んだか、また今後の展開はどうなのでしょうか。令和３年度内に使えるようになるのでしょうかというお声があるのですが、工事の進捗を確認させてください。","respondent":"勝亦学務課長、有馬庶務課長、矢部教育総合支援センター長","answer":"紙ベースから、例えばデジタルでご報告いただくというような形で工夫もできるのかと、いろいろ考えてあります。周知の仕方が十分でなかったかもしれません… 令和５年度予算については、現在では次の有力な候補校であることは間違いないと認識しています。地域への開放はいつからかということなのですが… 就学支援シートというのも、保護者の理解を得てお預かりしています。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどの資料を参考にしてほしいということを聞いていないと、その存在を分からない、それが活用できないということになってきます。東京都の臨床発達心理士等の、品川区教育委員会としての指導をしっかりしていっていただきたいのですが、その辺について確認します。","respondent":"矢部教育総合支援センター長","answer":"特に特別支援教室専門員に声をかけて、必要に応じて、書類を取れる構造になってあります。当然、これからも都の専門家や特別支援学校の専門家が見えた際には、ぜひ声をかけるようにこちらからも研修等で呼びかけてまいります。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"確認","question":"これまでも利用してきたので今後も指導に役立てていくということを確認できました。こういうことが書いてあってほしいというのを、その項目の日常的な見直しの機会というのですか、そういう会議体をつくることはいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"項目等については、これまでも適宜、的確かどうかというのは見直されてきていると思いますが、少なくとも区内の連携という意味では、これからも保育課等と連携しながら、その辺りの情報交換等を検討していきたいと考えています。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もし具体的にそういった会議体が現在あるならば、その会議体を教えていただきたいのですが。","respondent":"矢部教育総合支援センター長","answer":"会議の名称までは申し上げられませんが、特別支援教育担当は保育課と連携しての会議に出ていると承知しておりますので、また改めて確認しておきます。","id":"exchange-113"},{"speaker":"安藤委員","kind":"質問・要望","question":"充実が求められており、様々な角度から充実を求める請願が出され、議論がされています。伺いますが、現在の学校司書業務委託契約の更新時期はいつで、新しい契約内容の検討というのはいつから行うのか伺います。","respondent":"吉田品川図書館長","answer":"現在の学校図書館の運営スタッフ、今、学校図書館司書とおっしゃいましたが、契約上では学校図書館運営支援業務委託というものをやっておりまして、そちらは、平成３０年から令和４年度までの期間で更改、次に新しくなるのは令和５年度からになります。","id":"exchange-114"},{"speaker":"安藤委員","kind":"確認","question":"コスト面について伺いたいのですが、委託のほうが直接雇用より少ない経費になるということなのでしょうか。確認します。","respondent":"吉田品川図書館長","answer":"週２.５日の勤務で進めているところですけれども、これまでも学校司書２.５日のほかに、学校図書館の充実を図ってきた歴史があります。学校図書館の運営支援委託のほかには、当然、司書の委託が増えるとなりますと金額が上がるものと認識しております。","id":"exchange-115"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、委託にしていたほうが直接雇用よりは少ない経費になるのですかということを伺ったので、後でお答えください。偽装請負のことを追及しろと言っているわけではなくて、それそのものを見直すように求めたいと思いますけれども、いかがか尋ねました。","respondent":"吉田品川図書館長","answer":"それを実際のレベルに落としたものは、学校図書館の運営の手引というものがあります。偽装請負には該当しないと思われるところと、実際これで各学校が回っているところもありますので、特に問題がないものと考えております。","id":"exchange-116"},{"speaker":"安藤委員","kind":"質問・要望","question":"小学生では一番低くて何年生から行われているのか伺います。クラスの分け方はどのような方法で分けられているのかについても伺います。","respondent":"工藤指導課長","answer":"おおむね２学級３展開、１学級２展開をしたときには、打合せなどを行いながら進めているところです。その中で、発展的な指導の内容も盛り込むというのは、プラスアルファで行うということが多く行われているところです。","id":"exchange-117"},{"speaker":"安藤委員","kind":"質問","question":"この佐藤氏が指摘する習熟度別指導の問題点について何点か伺いたいのですが、１点目は、低学力の子どもは著しく学力が下がるという指摘があります。そうでないと言うのであれば、なぜそう言えるのか説明を求めました。","respondent":"工藤指導課長","answer":"先ほどの説明を補足します。おおむね８割以上の児童・生徒が、数学の授業が分かると回答しておりますので、一定程度の成果は出ていると把握しています。","id":"exchange-118"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、指導課長の口からも明らかになりましたけれども、それはどうなのでしょうかという立場で私は質問しております。習熟度別指導が学校の多様な仲間との協働と連帯の場所であるということを崩しているとの問題があると私は思うのですけれども、いかがか尋ねました。","respondent":"工藤指導課長","answer":"先ほど私も説明させていただきましたが、補助的な学習もしっかり行いながら、むしろ格差をなくす方向で行っているものと認識しています。","id":"exchange-119"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ様々な角度から、習熟度別指導が持つ弊害をきちんと研究して、見直しを求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"大沢委員","kind":"質問","question":"武蔵小山に文化施設が必要ではないかということで、いろいろな機会を見て、武蔵小山に図書館はどうでしょうかと。区の西の表玄関としての、区の売りになるのではないかという気がするのですけれども、その辺のご感想というかお考えを説明を求めました。","respondent":"吉田品川図書館長","answer":"床面積にしまして５００平米ぐらい、大きい図書館は当然それ以上になりますけれども、そのぐらいの床面積が必要となるところです。私どもも、いろいろ関係部署と今度は、そういう場所が確保できるかを含めて、これから検討してまいりたいと思っておるところです。","id":"exchange-121"},{"speaker":"大沢委員","kind":"意見","question":"そこのところをやはり、こういう言葉を使うのはあまり好きではないのですけれども、図書館については施設格差があるような気がしてならないのです。","respondent":"吉田品川図書館長","answer":"武蔵小山につきましての、今後のいろいろなまちの変わり方、その辺を含めまして、適切なタイミングのときに、そのようなことができるよう、努力してまいりたいと思います。","id":"exchange-122"},{"speaker":"大沢委員","kind":"質問","question":"９年間ということでやられて、９年間の集大成として７月にテストを行うということで、課題がありましたら説明を求めました。","respondent":"工藤指導課長","answer":"目標５０％と言っているところ、今年度の結果としても８０％を超えておりますので、そういった意味では成果が出ていると考えています。","id":"exchange-123"},{"speaker":"大沢委員","kind":"質問","question":"お願いしたいのは、書くというところで、どのような範疇があるのか。いわゆるディクテーションというものはされているのか尋ねました。","respondent":"工藤指導課長","answer":"やはり授業の中で、いわゆる聞き取りに当たるところ、それをまた英語で表現するといったことは、授業の中では行っているところではあります。","id":"exchange-124"},{"speaker":"大沢委員","kind":"質問","question":"音読が一番いいのですけれども。ここのところを主に考えられたらいかがかと思いまして、今お話をさせていただいているのですけれども、いかがお考えになりますか尋ねました。","respondent":"工藤指導課長","answer":"７年生以上の授業はオール・イングリッシュで行われておりますので、日本語で書くのではなく、それも英語で書いていくと。そこで基礎的な書くという力も含めて、英語力が高まると認識しています。","id":"exchange-125"},{"speaker":"大沢委員","kind":"質問・要望","question":"必要であると同時に、これは実践していただきたいと思うのです。そこのところはしっかりと子どもたちに、鍛え上げるように教えてほしいと求めましたけれども、最後にご決意をお願いいたします。","respondent":"工藤指導課長","answer":"ご指摘いただきました、書くということも含めて、生徒の英語力を高めるよう指導してまいります。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"今、現状の学習支援員との関係性というのか、縦分けというのか、仕切りというのか、その辺を教えてほしいと求めました。これは、学校ではどのように学んだり、また伝えたりしているのかというのもあれば説明を求めました。","respondent":"矢部教育総合支援センター長、黒田財政課長","answer":"学校は５校を予定していますが、それぞれの事情がありますので、まだ決定までは至っておりませんが、学校長と話を進めているところです。… 予算書自体は１０月１日現員で書いておりますので、この項目については記載はないというよりも、人件費の中に含まれているというものです。全校で実施するようになっているところですが、今、多くの学校では控えている状態です。","id":"exchange-127"},{"speaker":"若林委員","kind":"質問・要望","question":"１日７時間いるから、向上の部分を強調してお聞きしたかったので、もう一回そこはお話を伺います。議事録を再確認すると、しっかりと前に進めていただきたいということで、来年度の取組をもう一回お聞きします。","respondent":"矢部教育総合支援センター長","answer":"学習支援員は１週間で１２時間ですけれども、発達障害教育支援員は１週間で３５時間つくと考えていただけると分かりやすいかと思います。最後にウクライナ情勢につきましては、区議会、区としてそういう考えがあるということは、学校に伝わるように連絡してまいりたいと思います。","id":"exchange-128"},{"speaker":"小芝委員","kind":"提案","question":"農林水産省の事業で、和牛を使った学校給食を、品川区でもぜひ提供してもらいたいとの提案をさせていただきました。ここでお聞きしますが、どのような効果が生まれるとお考えなのか、区のお考えを教えてもらえますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"様々、これから持続可能な社会に向けて検討する内容でもあるのかと考えますので、ＳＤＧｓにも関わりまして教育できる分野かと考えております。すなわち、また全教育活動で食育にも当たっているということが言えるかと考えています。","id":"exchange-129"},{"speaker":"小芝委員","kind":"質問・要望","question":"そういう方々の努力によって、当たり前に米を食べることができるわけです。その反応といいますか、その取組をした結果の気づきというものがありましたら説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"学校の中では、主に小学生ですが２５校、バケツ稲に取り組んでいます。自分が教室で習ったことを、自分の体験と結びつけて学習していることで、実感を伴った理解になっていると認識しています。","id":"exchange-130"},{"speaker":"小芝委員","kind":"質問","question":"例えば毎年１つの学年が稲作を体験する取組を行うことで、また出来上がった後の楽しみを、体で覚えてもらえるのではないか。それが食育につながると考えますが、区のお考えを教えていただけますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"幼稚園ですけれども、わら細工が、この前の広報ですか、載っておりまして、そういった活用も進んでいるということは承知しています。米作りは、社会科以外にも幅広く活用できる内容だと認識しております。","id":"exchange-131"},{"speaker":"小芝委員","kind":"質問","question":"毎年９月に行われています旧東海道の宿場まつりで、売上金を、品川区を通じて寄附しているという取組が行われております。学校に農地がない学校の生徒は、遠方に行って農業体験をするような機会は実際にはあるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ちょっと今、お出かけについては、コロナ禍もあって自粛しているところはあります。１年生から栽培活動はしておりますので、チューリップだったり、ジャガイモだったりというところで触れている活動は全校であると認識しております。","id":"exchange-132"},{"speaker":"小芝委員","kind":"質問","question":"これは、先生の話を聞きますと、しめ縄の由来を先生が紙芝居で子どもたちに教えていたのです。神話を、小学生にも教える取組をぜひお願いしたいと思いますが、お考えがありましたらお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"そういった、地域と一緒に取り組むということの意味はとてもあると感じます。日本の文化・伝統を伝えるような話題を提供していただくよう、また学校と連携を強めていくよう、こちらからも働きかけてまいりたいと考えています。","id":"exchange-133"},{"speaker":"小芝委員","kind":"質問・要望","question":"この数字を８０％まで上げるですが、品川区の学校給食を題材にしました食育について教えてもらえますでしょうか。大体どのくらいの数で行っているかも含めて、取組状況を教えてほしいと求めました。","respondent":"勝亦学務課長","answer":"給食そのものが食育をしているというような考え方ではありますけれども、それから連携・交流協定を結んでおります、お米を頂くというような給食。そういった取組を、各学校それぞれ一つ一つの給食の中で取り組んでいると考えております。","id":"exchange-134"},{"speaker":"小芝委員","kind":"質問・要望","question":"ぜひ前向きに取り組んでほしいと求めました。大井四丁目には作守稲荷といって、作物の栽培を願う神社もありますので、そういった地域との交流をぜひ続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"大倉委員","kind":"質問・要望","question":"私は、部活動指導員と、学校改築から改築中のプールの利用、あとは学校地域コーディネーターについて伺えればと思います。減っている理由が分かれば教えていただきたいのと、まずは各１５校、ご答弁を頂きました。","respondent":"矢部教育総合支援センター長、有馬庶務課長、工藤指導課長","answer":"基本的には１校１人というようなことで、１５人分の予算を計上しておりますけれども、複数で対応も可能だという学校もございました。… 会員の方のコースも確保するという利用が可能なのかというようなこともありまして、そういうところで今、話が止まっております。というのは、コロナの中で… それは、やはりコーディネーターそのものの周知も必要だというところは認識しています。","id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"今１１校で１３名だと、予算的にもしっかり配分を増やして確保していくのかどうかというところについては、ご答弁ほしいと求めました。アシスタントコーディネーターでしたか、これは働き方としてはどのようになっているのか、説明を求めました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"よい人材は引き留めておきたいと考えておりますので、来年度もう予算が厳しいということであれば検討して、計上してまいりたいと考えております。毎日来ていない方もいらっしゃるので、上手にその辺りを組み合わせて… 会計年度任用職員になるほどの時間はないのだけれども、学校のために手伝えるという人がなっている状況があります。","id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"本当に、学校地域コーディネーターもアシスタントコーディネーターも、すごくいろいろなところにお話を聞きに行っていただいたり、汗をかいて、子どもたち、学校の要望することをできるだけ実現しようと頑張っていただいていますので、ぜひ周知も含めて応援してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"私は、３５９ページ、教育総務費、学習指導についてお聞きしたいと思います。このことに対して、教育委員会のご見解を説明を求めました。","respondent":"工藤指導課長","answer":"ある意味、その子が自分の秀でた能力を活かしていくという点においては、非常にいいことであると考えています。説明の前半にございましたように、指導方法を工夫・改善して取り組んでいるところですので、あってもよいことだと考えています。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういう実態も、やはりしっかり私は押さえてほしいと求めました。もう一度説明を求めました。","respondent":"工藤指導課長","answer":"その点において進学先を決めた生徒がいるということは、これまでもございましたし、そういうことがあってもよいと考えています。ただ、引き続き学校では、確かな学力を身につけさせるというところに注力して指導しているところではあります。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"１０段階層に分かれているのではないかと思うのですが、学校の指導は今現在、そのうち６段階か７段階をターゲットにして教えていると思うのです。それから、学力定着のターゲットを、下の段階の層、低学力層の子どもにも目を当てていただきたいのですが、その辺のご見解も説明を求めました。","respondent":"工藤指導課長","answer":"Ａ・Ｂ・Ｃ・Ｄ層の４つに分ける、いわゆる四分位分析を行いまして、全児童・生徒を対象に把握しています。これにより各学校が学力層の把握を行いながら、児童・生徒のつまずきを把握し、児童・生徒個々の課題をしっかりと把握して取り組んでいるところです。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"そこに２０人、習熟度別で、ここに１０人のクラスをつくったら、その中で段階がみんな違っていたら、どうやって見られるのですか。今、１万５,０００人の子どもたちが利用している塾代助成の事業を行い、そういうものを品川区もつくって利用したらどうか尋ねました。","respondent":"工藤指導課長","answer":"そういう意味では、個に応じた指導を行うというのは、全ての教科の授業の中において今進めているところです。思考力・判断力・表現力、また学びに向かう力、全てを勘案して人間力を育てるというところを進めているところです。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"だけど、１割から２割の生徒は残ってしまうではないですか。そういう手法をやっているからではないか尋ねました。","respondent":"工藤指導課長","answer":"私どもはやはり、通常の授業における指導の工夫はもちろん、補習等におきましても個別対応していくことが重要だと考えています。存在は認識していますけれども、やはり学力向上に資する使命がありますので、そこを改めて進めているところです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"まして、公立中学校を持っている品川区が、これでいいのですか。きちんと責任を取れるのか尋ねました。","respondent":"工藤指導課長","answer":"これまで説明していますけれども、全ての教育活動の成果等を総合的に鑑みて、校長が進級や卒業を判断しているというところではあります。そういう意味では、学力だけではないというところを改めて認識していただければです。","id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"まして、皆さん、自分のお子さんがいるのだったら、自分の子は将来どうあってほしい、どうなってほしいと真剣に考えると思います。私はもう少し、やはり教育委員会も真剣に考えてほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この２つの団体が、学校での生理休暇導入を求める要望書を、文部科学省に、昨年の１２月２４日に提出しています。伺います。","respondent":"矢部教育総合支援センター長","answer":"委員ご指摘の件につきましては承知しています。","id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"関係する所管課として、こうした要望書が出されたことについて、どう受け止められたか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"そのことを言えず無理をしてしまう事例などが課題になっていることは十分認識しておりますし、当然、配慮が必要だと捉えております。今後、国や都の動向を注視しながらも、配慮はこれまでどおり継続していきたいと考えております。","id":"exchange-147"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうした実態をどう思われているか、区教育委員会の認識を伺いたいと思います。そして、教職員の皆さんは生理休暇があるわけですけれども、教職員の生理休暇の取得率というのが分かれば教えてほしいと求めました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"生理にかかわらず、テストに参加できないような場合は、そのような配慮はこれまでどおりしているということでございました。生理休暇につきましては、現在、出欠席の扱いがないものでございまして、国や都の動向を注視しながらというこ… 教職員の方の生理休暇の取得ですけれども、手持ちの資料では把握してございません。","id":"exchange-148"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、ぜひ生理休暇導入を検討してほしいと求めました。把握していただくところから始めていただいて、ぜひ検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"これは女子に限らず、男子もそのときに参加できなければ、そういう対応になるということは考えられるわけです。扱いとして、現状、生理休暇というものがないので、国や都の動向を注視しながらという、繰り返しの答弁になります。","id":"exchange-149"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"扱いとしてないのであれば、ぜひ国や都に求めてほしいと求めました。このリプロダクティブ・ヘルス／ライツに関して、こうした連携を図ろうと言われているのですけれども、区としてはどうなっているか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"前回の委員のお話も伺い、１９９４年にカイロで開催された国際人口開発会議で提唱された、女性特有の健康問題についてのことだと認識しております。","id":"exchange-150"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、性に関する行動や考えが活発になっていく思春期だからこそ、どう選択して、どう行動するかという基礎にさせていくというものなのです。こうしたことを教えていくことが必要だと思うのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"性教育というのは、これまでの経緯や医学的な根拠も含めて協議されているものだと考えておりますので、保健指導を進めてまいりたいと考えております。","id":"exchange-151"},{"speaker":"石田（ち）委員","kind":"確認","question":"そして、またパートナーに積極的に自分の意思を伝えて、相手の同意を確認する。それでこそ、自分の身を守り、相手も大事にできる教育だと言えるのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３５３ページ、埋蔵文化財調査費、３６９ページ、地区図書館運営費、３６５ページ、学校支援地域本部事業経費についてお伺いいたします。初めに、３５３ページの埋蔵文化財調査費についてお伺いいたします。","respondent":"有馬庶務課長","answer":"は発掘調査の部分と、それから出土品の整理作業や、調査報告書を作成する経費、こちらで約１,０００万円ほど増額になってあります。これは北品川沿いになると思いますけれども、北品川近辺の調査を行う経費も一定程度、計上しているというような状況です。","id":"exchange-153"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今ご答弁のあった最初の改修工事、一般の戸建ての住宅ということでよろしいのか尋ねました。","respondent":"有馬庶務課長","answer":"特に居木橋周辺の包蔵地で、個人住宅の建て替えに伴う調査費用です。","id":"exchange-154"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"地域の声からも、階段の上り降りがつらいといった声も頂いている中で、障害者トイレが、南大井図書館と源氏前図書館の２館はないのです。特に源氏前図書館について、進捗というか、今後どういうふうに展開していくのかお知らせほしいと求めました。","respondent":"吉田品川図書館長","answer":"それから、障害者対応、一時期はリフトなどを検討した時期もあったところですが、実際、つけられないという、たしか判断が出たというところで。下に保育園を抱えたりしておりますので、また今後、建て替え等について検討していければと考えているところです。","id":"exchange-155"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"」という要望がありました。他区から校長先生が来て今２年目なのですけれども、そこのところを２点、お伺いしたいと思います。","respondent":"工藤指導課長","answer":"成果報告をまとめているところでは、地域の方々の多くの支援があって、今年度も行われているところがあります。校区教育協働委員会を中心に進めつつ、学校支援地域本部の体制を強化しながら、取組は進めていきたいと考えています。","id":"exchange-156"},{"speaker":"塚本委員","kind":"質問・要望","question":"先ほど同じ会派の若林委員からも質問があった、もう少し詳細を確認させていただきたい点がございまして、伺わせていただきます。その点をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"発達障害教育支援員の条件ですが、基本的に、業務を説明した中で、子どもに寄り添うということから、もちろん教員免許を持っているとか、これまでに特別支援の経験値がある方が望ましいとは考えておりますが、大きな縛りはないという理解です。","id":"exchange-157"},{"speaker":"塚本委員","kind":"質問","question":"常勤的にずっといらっしゃるということは、１対Ｎ、１人で何人かの方を見るという考え方にあると。こういう認識でよろしいか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"発達障害教育支援員は、複数のお子さんを見ることができます。ただ、会計年度任用職員ですので、５日間といいましても、３日と２日で２人入るような形にはなります。","id":"exchange-158"},{"speaker":"塚本委員","kind":"質問・要望","question":"求めに応じて学習支援員等がなかなかつかないというような話も時々あるわけですけれども、これまでのどういった課題が解消されるというようなことをねらわれているのか、最後にお伺いします。","respondent":"矢部教育総合支援センター長","answer":"東京都では特別支援教室を原則１年で、特別支援教室で学んだものを、これからずっと定着するように支援する方ということになります。１２時間が３５時間になりますので、より丁寧に見ていけるということ、または担任とも連携が図れるというよさがあると考えております。","id":"exchange-159"},{"speaker":"塚本委員","kind":"質問","question":"３６１ページ、キャリア教育というところでお伺いしたいのですけれども、キャリア教育の充実を図るということが明記されたと。現状、まず区としてのキャリア教育がどのように実施されているのか、お伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"国でマイ・キャリア・ノートというものを１人１冊、学年が上がるごとに、その進路に関わることを記入していくような施策が行われております。ファイナンス・パーク、また職場体験等で、キャリア教育を進めている現状です。","id":"exchange-160"},{"speaker":"塚本委員","kind":"確認","question":"それを１点確認と、ゲームというのを１つの職業と捉えて主張されているところがあって、「ゲームというのも１つの職業として今後成立していくのだ。自分が将来、いわゆる義務教育として育むべきキャリア教育というのは一体どういうところにあるとお考えか、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"国が実施しておりますが、本区も全員実施しています。これは私も会場におりましたので、そのように認識しております。","id":"exchange-161"},{"speaker":"塚本委員","kind":"質問・要望","question":"将来そういう力を身につけるためにというところに意義を求めているというふうになっております。中学３年生卒業時に、キャリア教育の結果、どのような意識を持った中学３年生の卒業生というのを描いているのかをお聞かせほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"大きくは、未来を切り開く子どもたちです。今おっしゃった、社会での自立に向けて、自分が成長していくということがねらいとなっております。","id":"exchange-162"},{"speaker":"塚本委員","kind":"質問・要望","question":"これまで各学校での活用状況に併せて、学校からの感想等ありましたら、ご紹介ほしいと求めました。ここの借料というところでは、リース期間終了後、空調機はどのような扱いになっているのか説明を求めました。","respondent":"有馬庶務課長","answer":"体育館への空調設置ですが、令和元年９月から順次入れておりますけれども、特に夏、大変涼しくて助かるというような声を聞いております。それから、リース期間が終わった後は、区に譲渡という形になるです。","id":"exchange-163"},{"speaker":"塚本委員","kind":"意見","question":"室外機が当然、体育館の外にあるのですけれども、その騒音が少し問題になっている学校もあったかと思います。この騒音の問題について、今現状どのような対応になっているのか説明を求めました。","respondent":"小林学校施設担当課長","answer":"苦情関係というか、ご意見を頂いた学校については、数校ありました。即、室外機の周辺に防音壁を設置したり、噴き出しの部分に消音器を設置したりという対策を講じて、今現在、全て済んでいるということです。","id":"exchange-164"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"行政、企業なども力を合わせて、社会全体で子育てや家庭教育を応援していくことが求められていると考えています。教育委員会もいろいろやっていらっしゃると思いますが、何をこうやっていろいろ行っていこうとされているのか、まずそこを伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"８・９年生は、今できることに目を向け、克服していくことをやり抜く活動を実施しております。子どもたちが粘り強くやり抜いたところで、それらを見ていた大人が価値づけたり褒めたりすることが、次の意欲につながると今は考えております。","id":"exchange-165"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけど、これは多分、一番よかった例だと、私は自分自身で思っているけれども、こういうことは学校にはたくさんあるじゃないですか。これからの部活というのを、ただ人が多いからやっていますよということではなくて、どう捉えてやっていくかというところを教えていただきたい。","respondent":"矢部教育総合支援センター長","answer":"目指す目的は何かというようなところを共有しながら、先ほどの部活動指導員の専門性なども活かして進めていくことが肝要だと考えています。本当に専門的な知識も必要ですので、少なくとも部活動指導員につきましては、大学の専門家から研修を行って取り組んでいるところです。","id":"exchange-166"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、１つ言えばよかったと思っていて、ここに書いてあったんだけど、今、コロナ禍で体力が落ちているような気がしてならなくて、これはやはりアフターコロナのところがあるかもしれないけれども、体力を回復させるということも非常に重要かと思っていて、その辺も併せて説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"教育総合支援センターでは、また学校長等が集まりまして、来年度の体育の今後の体力向上に向けての専門的な検討を行っております。さらに来年度に向けて、品川区独自のワンミニッツエクササイズとスポーツの施策とを絡めて、進めてまいりたいと考えています。","id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうことがあるらしいということを伺いました。品川区の優しさだと思っていて、それが必ず安全性にもつながっていくのかと思うので、その辺の見解を説明を求めました。","respondent":"勝亦学務課長","answer":"今、区内のアレルギーの対応につきまして頂きましたけれども、基本的には紙ベースになってあります。アレルギーに関しましては、機械に任せっきりにするのではなく、一人一人に応じた丁寧な対応を取りながら効率化していくことが大事かと考えています。","id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最後に１点だけ、これはもう要望だけにしますけれども、今、教室不足が頻発している。この辺のところはもう一度議論するということも、頭にもちろんあるのだろうけれども、ぜひそういうことも考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1156#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":127149,"voices":388}}]);
